    {
        for(j=0; j<m; j++)
        {
            if(flags[j] == 0 && block_size[j] >= process_size[i])
            {
                allocation[j] = i;
                flags[j] = 1;
                break;
            }
        }
    }

    for(i=0; i<n; i++)
