#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct node
{
    int size;
    int start;
    int end;
    int status;
    struct node *next;
};

struct node *head = NULL;

void insert(int size)
{
    struct node *temp = (struct node *)malloc(sizeof(struct node));
    temp->size = size;
    temp->start = 0;
    temp->end = size - 1;
    temp->status = 0;
    temp->next = NULL;

    if (head == NULL)
    {
        head = temp;
    }
    else
    {
        struct node *p = head;
        while (p->next != NULL)
        {
            p = p->next;
        }
        p->next = temp;
    }
}

void display()
{
    struct node *p = head;
    while (p != NULL)
    {
        printf("%d\t%d\t%d\t%d\n", p->size, p->start, p->end, p->status);
        p = p->next;
    }
}

void best_fit(int size)
{
    struct node *p = head;
    int min = 9999;
    struct node *temp = NULL;
    while (p != NULL)
    {
        if (p->status == 0 && p->size >= size)
        {
            if (p->size < min)
            {
                min = p->size;
                temp = p;
            }
        }
        p = p->next;
    }
    if (temp != NULL)
    {
        temp->status = 1;
        printf("Allocated memory of size %d at %d\n", size, temp->start);
    }
    else
    {
