function injectElement(elementType, attributes, node, innerProperty, innerValue) {
    const tag = document.getElementsByTagName(node)[0];
    const element = document.createElement(elementType);
    for (let key in attributes) {
        element.setAttribute(key, attributes[key]);
    }
    if (innerProperty) element[innerProperty] = innerValue;
    element.setAttribute('id', `Voron${elementType.charAt(0).toUpperCase() + elementType.slice(1)}`);
    if (tag) tag.appendChild(element);
}

function injectScript(file, node) {
    injectElement('script', {
        type: 'text/javascript',
        src: file
    }, node);
}

function injectCSSCode(code, node) {
    injectElement('style', {
        rel: 'stylesheet'
    }, node, 'textContent', code);
}

function injectCode(code, node) {
    injectElement('div', {}, node, 'innerHTML', code);
}

function injectCss(file, node) {
    injectElement('link', {
        href: file,
        rel: 'stylesheet'
    }, node);
}

function injectScriptModule(file, node) {
    injectElement('script', {
        type: 'module',
        src: file
    }, node);
}

function waitForElement(elementId, callBack, timeout = 5000) {
    const interval = setInterval(() => {
        let element = document.querySelector(elementId);
        if (element) {
            clearInterval(interval);
            callBack(elementId, element);
        }
    }, 50);
    setTimeout(() => {
        clearInterval(interval);
    }, timeout);
}

function injectHtml(path) {
    fetch(chrome.runtime.getURL(path))
        .then(response => response.text())
        .then(data => {
            try {
                if (document.body) {
                    const tempElement = document.createElement('template');
                    tempElement.innerHTML = data;
                    document.body.appendChild(tempElement.content);
                }
            } catch (e) {
                console.error("Failed to inject HTML: ", e.message);
            }
        })
        .catch(err => {
            console.error(err);
        });
}

function injectIfEnabled(storageKey, injectFunction) {
    chrome.storage.local.get(storageKey, function(items) {
        if (items[storageKey] === true) {
            injectFunction();
        }
    });
}

function fr() {
    // Для редактора
    if (window.location.href.indexOf("//tilda.cc/page/") !== -1) {
        injectScript(chrome.runtime.getURL("modules/editor/search.js"), "body");
        injectCss(chrome.runtime.getURL("styles.css"), "body");
        injectScript(chrome.runtime.getURL("blocks/inject.js"), "body");
        injectScript(chrome.runtime.getURL("modules/editor/picker.js"), "body");
        injectScript(chrome.runtime.getURL("showrec.js"), "body");
        injectIfEnabled('publish', () => {
            injectScript(chrome.runtime.getURL('modules/editor/publish.js'), 'body')
        });
        injectIfEnabled("recids", () => {
            injectScript(chrome.runtime.getURL("modules/editor/recid.js"), "body");
        });
        injectIfEnabled("blockids", () => {
            injectScript(chrome.runtime.getURL("modules/editor/blockid.js"), "body");
        });
    }
    // Для интерфейса
    if (
        (window.location.href.indexOf("//tilda.cc/projects/") !== -1 && window.location.href.indexOf("://tilda.cc/zero/") === -1) ||
        (window.location.href.indexOf("//store.tilda.cc/") !== -1 && window.location.href.indexOf("://tilda.cc/zero/") === -1)
    ) {
        injectIfEnabled("black", () => {
            document.querySelector("head > style")
                .remove();
            injectCss(chrome.runtime.getURL("black-mode/black-mode.css"), "head");
            injectCSSCode(
                `
            .td-button-ico_white {
              color: #fff !important;
              background-color: transparent !important;
              transition: 200ms;
              border-radius: 55px !important;
              border: 1px solid #ccc !important;
             }
              `,
                `body`
            );
        });
    }
}

chrome.storage.local.get('token', function(items) {
    // Если токен есть
    if (items.token) {
        chrome.storage.local.get('free', function(it) {
            // console.log('once here');
            // Free
            if (it.free === true) fr()
            else {
                // Если не free
                async function checklic() {
                    // Для Тильды
                    if (window.location.href.indexOf("tilda.cc") !== -1 &&
                        window.location.href.indexOf("?ref=https://tilda.cc") === -1 &&
                        window.location.href.indexOf("https://tilda.cc/ru/") === -1 &&
                        window.location.href.indexOf("https://help-ru.tilda.cc/") === -1) {
                        const data = await fetch("https://voron-api.ru/login", {
                            method: "POST",
                            headers: {
                                "Content-Type": "application/json",
                                "X-Auth-Token": items.token,
                            },
                        });
                        const result = await data.json();
                        // Pro
                        if (result.pro === "ok") {
                            // Для редактора
                            if (window.location.href.indexOf("//tilda.cc/page/") !== -1) {
                                injectScript(chrome.runtime.getURL("blocks/v.js"), "body");
                                injectIfEnabled("height123", () => {
                                    injectCss(chrome.runtime.getURL("modules/editor/height123.css"), "body");
                                });
                                injectIfEnabled("guides", () => {
                                    injectScript(chrome.runtime.getURL("modules/editor/guides.js"), "body");
                                });
                                injectIfEnabled("blocks", () => {
                                    injectScript(chrome.runtime.getURL("modules/editor/blockmap.js"), "body");
                                });
                                injectIfEnabled('minify', () => {
                                    injectScript(chrome.runtime.getURL('modules/editor/minify.js'), 'body')
                                });

                                chrome.storage.local.get("bt123", function(items) {
                                    switch (items.bt123) {
                                        case "monokai":
                                            injectCss(chrome.runtime.getURL("/ace/theme/monokai.css"), "body");
                                            break;
                                        case "tomorrow_night":
                                            injectCss(chrome.runtime.getURL("/ace/theme/tomorrow_night.css"), "body");
                                            break;
                                        case "merbivore_soft":
                                            injectCss(chrome.runtime.getURL("/ace/theme/merbivore_soft.css"), "body");
                                            break;
                                        case "sqlserver":
                                            injectCss(chrome.runtime.getURL("/ace/theme/sqlserver.css"), "body");
                                            break;
                                        default:
                                            console.log("No theme picked");
                                            break;
                                    }
                                });
                            }

                            // Для кода в настройках сайта
                            if (
                                window.location.href.indexOf("//tilda.cc/projects/editcustomcss/") !== -1 ||
                                window.location.href.indexOf("//tilda.cc/projects/editheadcode/") !== -1
                            ) {
                                waitForElement(".ace-github", function() {
                                    injectScriptModule(chrome.runtime.getURL("ace/ace.js"), "body");
                                    chrome.storage.local.get("bt123", function(items) {
                                        switch (items.bt123) {
                                            case "monokai":
                                                injectCss(chrome.runtime.getURL("/ace/theme/monokai.css"), "body");
                                                break;
                                            case "tomorrow_night":
                                                injectCss(chrome.runtime.getURL("/ace/theme/tomorrow_night.css"), "body");
                                                break;
                                            case "merbivore_soft":
                                                injectCss(chrome.runtime.getURL("/ace/theme/merbivore_soft.css"), "body");
                                                break;
                                            case "sqlserver":
                                                injectCss(chrome.runtime.getURL("/ace/theme/sqlserver.css"), "body");
                                                break;
                                            default:
                                                console.log("No theme picked");
                                                break;
                                        }
                                    });
                                });
                            }
                            // Для зеро
                            if (window.location.href.indexOf("//tilda.cc/zero/") !== -1) {
                                chrome.storage.local.get("sbscopy", function(items) {
                                    if (items.sbscopy == true) {
                                        chrome.storage.local.get("sbs", function(items) {
                                            if (items.sbs) {
                                                window.localStorage.tzerosbsanimation = items.sbs;
                                            }
                                        });
                                    }
                                });
                            }
                            chrome.storage.local.set({
                                expire: result.expire,
                            });
                            if (it.free === true) {
                                chrome.storage.local.set({
                                    token: '',
                                    pro: '',
                                    expire: '',
                                    free: ''
                                })
                            }
                        } else {
                            chrome.storage.local.set({
                                free: true,
                                inspect: false,
                                whattype: false,
                                sitemap: false,
                                editing: false,
                            });
                        }
                        // Истекла
                        if (result.auth === "ok") {
                            fr()
                        }
                    } else {
                        // Для опубликованных страниц
                        if (
                            window.location.href.indexOf("//tilda.cc/projects/") === -1 &&
                            window.location.href.indexOf("//tilda.cc/zero/") === -1 &&
                            document.querySelector('.t-body #allrecords')
                        ) {
                            chrome.storage.local.get("inspect", function(items) {
                                if (items.inspect == true) {
                                    injectScriptModule(chrome.runtime.getURL("modules/published/hljs.js"), "head");
                                    injectCss(chrome.runtime.getURL("modules/published/highlight.min.css"), `head`);
                                    injectCSSCode(
                                        `.codeToT123 {display: block;
                padding: 9.5px;
                margin: 0 0 10px;
                font-size: 13px;
                line-height: 1.428571429;
                color: #333;
                word-break: break-all;
                display: flex;
                word-wrap: break-word;
                background-color: #f5f5f5 !important;
                border: 1px solid #ccc;
                border-radius: 4px;}
                #v {
                  display: table-cell;
                  vertical-align: middle;
                  padding-left: 12px;
                  padding-right: 12px;
                  background-color: #FFF;
                  border: 1px solid;
                  border-radius: 3px;
                  cursor: pointer;
                  padding-top: 5px;
                  padding-bottom: 5px;
                  position: relative;
                  left: 15px;
                  z-index: 99999;
                  top: 10px;
                  font-family: 'Open Sans',arial;
                  font-size: 13px;
                  line-height: 15px;
                  font-weight: 400;
                  color: #333;
                  height: 20px;
                }
                .v-edit {
                  background-color: #FA876B !important;
                  border-color: #FA876B !important;
                }
                .tn-right-box {
                  display: none;
                }
                `, `body`
                                    );
                                }
                            });

                            chrome.storage.local.get("whattype", function(items) {
                                if (items.whattype == true) {
                                    injectHtml("modules/published/rightbox-wrap.html");
                                    injectHtml("modules/published/rightbox.html");
                                    injectScript(chrome.runtime.getURL("modules/published/whattype.js"), "head");
                                    injectCss(chrome.runtime.getURL(`modules/published/zeroSet.css`), `head`);
                                    injectCSSCode(
                                        `#v {
                  display: table-cell;
                  vertical-align: middle;
                  padding-left: 12px;
                  padding-right: 12px;
                  background-color: #FFF;
                  border: 1px solid;
                  border-radius: 2px;
                  cursor: pointer;
                  padding-top: 5px;
                  padding-bottom: 5px;
                  position: relative;
                  left: 15px;
                  z-index: 99999;
                  top: 10px;
                  font-family: 'Open Sans',arial;
                  font-size: 13px;
                  line-height: 15px;
                  font-weight: 400;
                  color: #333;
                  height: 20px;
                }
                .v-edit {
                  background-color: #FA876B !important;
                  border-color: #FA876B !important;
                }
                .tn-right-box {
                  display: none;
                }
                `, `body`
                                    );
                                }
                            });

                            chrome.storage.local.get("sitemap", function(items) {
                                if (items.sitemap == true) {
                                    injectScript(chrome.runtime.getURL("modules/published/sitemap.js"), "body");
                                }
                            });

                            injectIfEnabled("editing", () => {
                                injectHtml("context-menu/context-menu.html");
                                injectCss(chrome.runtime.getURL(`context-menu/context-menu.css`), `head`);
                                injectScript(chrome.runtime.getURL("context-menu/context-menu.js"), "body");
                            });

                            window.addEventListener("message", function(event) {
                                if (event.data.hasOwnProperty("event") && event.data.event == "chatMessage") {
                                    let sbs = event.data.value;
                                    chrome.storage.local.set({
                                        sbs: sbs,
                                    });
                                }
                            });

                            // Прием сообщений для переключения вкадок
                            window.addEventListener("message", function(event) {
                                if (event.data.hasOwnProperty("event") && event.data.event == "tabsswitch") {
                                    chrome.runtime.sendMessage({
                                        info: "tabpublish"
                                    }, function(response) {

                                    });
                                }
                            });

                            // Отправка сообщения сразу, чтобы keep alive service worker
                            chrome.runtime.sendMessage({
                                info: "keepalive"
                            }, function(response) {
                                if (response !== undefined) {}
                            });
                            // injectCSSCode(`#allrecords{overflow:hidden!important;}`, 'body', 'VoronCss')
                        }
                    }
                }
                checklic();
            }
        })
    }
})

