Per creare un programma PHP che permetta di scaricare report di Matomo da un frontend, possiamo seguire questi passaggi:

1. **Creare il frontend**: Utilizzare HTML, CSS e JavaScript per creare un'interfaccia utente che mostri i siti disponibili, permetta di selezionare il sito, le date e il formato di uscita.
2. **Creare il backend**: Utilizzare PHP per gestire le richieste del frontend, connettere a Matomo, ottenere i dati e generare i file CSV, Excel e PDF.
3. **Utilizzare la libreria Matomo PHP**: Utilizzare la libreria ufficiale di Matomo per PHP per connettere e ottenere i dati.

Ecco un esempio di codice per il backend PHP:

```php
<?php
require_once 'matomo.php'; // Assicurati di includere il file della libreria Matomo

// Connessione a Matomo
$matomo = new Matomo();
$matomo->setSiteId(1); // Sostituisci con l'ID del tuo sito Matomo
$matomo->setSiteUrl('https://your-matomo-url.com'); // Sostituisci con l'URL del tuo sito Matomo

// Funzione per ottenere i siti disponibili
function getAvailableSites() {
    global $matomo;
    $sites = $matomo->getSites();
    return array_column($sites, 'name');
}

// Funzione per ottenere i dati di Matomo
function getMatomoData($siteId, $startDate, $endDate) {
    global $matomo;
    $matomo->setSiteId($siteId);
    $matomo->setStartDate($startDate);
    $matomo->setEndDate($endDate);
    $data = $matomo->getSiteTraffic();
    return $data;
}

// Funzione per generare il file CSV
function generateCsv($data, $filename) {
    $fp = fopen($filename, 'w');
    fputcsv($fp, array_keys($data[0]));
    foreach ($data as $row) {
        fputcsv($fp, $row);
    }
    fclose($fp);
}

// Funzione per generare il file Excel
function generateExcel($data, $filename) {
    require_once 'PHPExcel.php'; // Assicurati di includere la libreria PHPExcel
    $objPHPExcel = new PHPExcel();
    $objPHPExcel->getActiveSheet()->setTitle('Matomo Report');
    $objPHPExcel->getActiveSheet()->setCellValue('A1', 'Date');
    $objPHPExcel->getActiveSheet()->setCellValue('B1', 'Visits');
    $objPHPExcel->getActiveSheet()->setCellValue('C1', 'Visits Unique');
    $objPHPExcel->getActiveSheet()->setCellValue('D1', 'Bounce Rate');
    $objPHPExcel->getActiveSheet()->getStyle('A1:D1')->getFont()->setBold(true);
    $objPHPExcel->getActiveSheet()->getStyle('A1:D1')->getFill()->setFillType(PHPExcel_Style_Fill::FILL_SOLID);
    $objPHPExcel->getActiveSheet()->getStyle('A1:D1')->getFill()->setColor(new PHPExcel_Style_Color(PHPExcel_Style_Color::COLOR_LIGHT_GRAY));
    $row = 2;
    foreach ($data as $rowData) {
        $objPHPExcel->getActiveSheet()->setCellValue('A' . $row, $rowData['date']);
        $objPHPExcel->getActiveSheet()->setCellValue('B' . $row, $rowData['visits']);
        $objPHPExcel->getActiveSheet()->setCellValue('C' . $row, $rowData['visits_unique']);
        $objPHPExcel->getActiveSheet()->setCellValue('D' . $row, $rowData['bounce_rate']);
        $row++;
    }
    $objPHPExcel->getActiveSheet()->getStyle('A1:D' . $row)->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setOrientation(PHPExcel_Worksheet_PageSetup::ORIENTATION_LANDSCAPE);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setPaperSize(PHPExcel_Worksheet_PageSetup::PAPERSIZE_A4);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setRowsPerColumn(10);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setHorizontalResolution(300);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setVerticalResolution(300);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToWidth(1);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToHeight(1);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToWidth(1);
    $objPHPExcel->getActiveSheet()->getPageSetup()->setFitToHeight(1);
