  const clearErrors = () => {
    setErrorEmail("");
    setErrorPassword("");
    setErrorPseudo("");
    setErrorOldPassword("");
    setErrorVerifPassword("");
  }


  const handleConnexion = (e : React.FormEvent<HTMLFormElement>) => {
    clearErrors();
    e.preventDefault();
    setIsLoading(true);
    // verifie si les champs sont remplis
    // verifie si l'email est bien un email (regex)

    if (!checkEmail(email) || !checkPassword(password)){
      return;
    }

    // fais une requete post avec axios à localhost:8080/connecter

    const data = {
      email,
      password
    }

    axios.post("http://localhost:8080/connecter", data).then((res) => {
      const data = res.data;
      if (data.error){
        setErreur("email", data.error);
        setErreur("password", data.error);
        return;
      }
      const idUser = data.idUser;
      const pseudoUser = data.pseudoUser;
      const emailUser = data.emailUser;
      setUserCookie({idUser, pseudoUser, emailUser});
      goTo("connecte");
      setIsLoading(false);
    })
  }

  const handleDeconnexion = (e : React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    clearErrors();

    removeUserCookie();
    setCurrentMenu("connexion");
  }

  const handleInscription = (e : React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearErrors();
    setIsLoading(true);

    if (!checkEmail(email) || !checkPassword(password) || !checkPseudo(pseudo)){
      return;
    }

    const data = {
      pseudo,
      email,
      password
    }

    axios.post("http://localhost:8080/inscription", data).then((res) => {
      const data = res.data;

      if (data.error){
        setErreur("email", data.error);
        return;
      }

      const idUser = data.idUser;
      const pseudoUser = data.pseudoUser;
      const emailUser = data.emailUser;
      setUserCookie({idUser, pseudoUser, emailUser});
      goTo("connecte");
      setIsLoading(false);
    })

  }

  const handleResetMdp = (e : React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearErrors();
    setIsLoading(true);

    if (!checkEmail(email)){
      return;
    }

    const data = {
      email
    }

    axios.post("http://localhost:8080/envoyerCodeVerification", data).then((res) => {
      const dataRes = res.data;
      if (res.data.error){
        setErreur("email", dataRes.error);
        return;
      }

      if (res.data.success){
        goTo("codeVerification")
        setCodeVerification("");
        setEmail(data.email);
      }
      setIsLoading(false);

    })
  }

  const handleEnvoyerCode = (e : React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearErrors();
    setIsLoading(true);

    if (codeVerification.length !== 6){
      setErreur("codeVerification", "Le code doit faire 6 caractères");
      return;
    }

    const data = {
      email,
      code:codeVerification
    }

    axios.post("http://localhost:8080/testerCodeVerification", data).then((res) =>{
      const dataRes = res.data;
      if(dataRes.error){
        setErreur("codeVerification", dataRes.error);
        setCodeVerification("");
        return;
      }

      if(res.data.success){
        console.log("code correct");
        goTo("changerMdp")
        setEmail(data.email);
        setCodeVerification(data.code);
      }
      setIsLoading(false);
    })
  };

  const handleModifierInfos = (e : React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearErrors();
    setIsLoading(true);

    if (isConnected() === false){
      goTo("connexion");
      return;
    }

    const currentID = getUserCookie().idUser;

    if (!checkEmail(email) || !checkPassword(password) || !checkPseudo(pseudo) || !CheckOldPassword(oldPassword)){
      return;
    }

    const data = {
      id:currentID,
      pseudo,
      email,
      password,
      oldPassword
    } 

    axios.post("http://localhost:8080/modifierProfil", data).then((res) => {
      const data = res.data;

      if (data.error){
        setErreur("oldPassword", data.error);
        return;
      }

      const idUser = data.idUser;
      const pseudoUser = data.pseudoUser;
      const emailUser = data.emailUser;
      setUserCookie({idUser, pseudoUser, emailUser});
      goTo("connecte");
      setIsLoading(false);
    })
  }

  const handleModifierMdp = (e : React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearErrors();
    setIsLoading(true);

    if (!checkPassword(password) || !checkPasswordMatching(password, verifierPassword)){
      return;
    }

    const data = {
      email,
      password,
      code: codeVerification
    }

    axios.post("http://localhost:8080/modifierMdp", data).then((res) => {
      const dataRes = res.data;

      if (dataRes.error){
        alert(dataRes.error);

        return;
      }

      if (dataRes.success){
        removeUserCookie();
        goTo("connexion");
      }
      setIsLoading(false);
    })
  }

  const menuVariants = {
    hidden:{
      x: "42rem",
      transition:{
        duration: 0.5,
        ease: [1, -0.02, 0,1]
      }
    },
    visible:{
      x: 0,
      transition:{
        duration: 0.5,
        ease: [1, -0.02, 0,1]
      }
    }
  }

  const menuSwitchVariants = {
    exit:{
      // part à gauche et disparait
      x: "-100vw",
      transition:{
        duration: 0.5,
        ease: [1, -0.02, 0,1]
      }
    },
    appearing:{
      // vient de droite et apparait
      x: "100vw",
      transition:{
        duration: 0.5,
        ease: [1, -0.02, 0,1]
      }
    },
    default:{
      // reste au centre
      x: 0,
      transition:{
        duration: 0.5,
        ease: [1, -0.02, 0,1]
      }
    },
    wrong:{
      // fais remuer le menu de gauche à droite avant qu'il aille au centre
      x: [0, -20, 20, -20, 20, 0],
      transition:{
        duration: 0.4,
        ease: "linear"
      }
    }

  }

  )
}import React, { useContext } from 'react';
import { CartContext } from '../../../../App.tsx'; // Assurez-vous que le chemin est correct
import { ItemPanier } from './ItemPanier';
import { motion, AnimatePresence } from 'framer-motion';
import Button from '../../../../components/form/Button';


type Props = {
  isOpen: boolean;
  setIsOpen: (isOpen: boolean) => void;
};

const MenuPanier: React.FC<Props> = ({ isOpen, setIsOpen }) => {
  const { cart } = useContext(CartContext);

  // Calculer le sous-total
  const subtotal = cart.reduce((acc: number, item: { price: number; quantity: number; }) => acc + item.price * item.quantity, 0);

  const handleReservation = async () => {
    try {
      const cartString = JSON.stringify({billets: cart});
      console.log(cartString);
      const response = await fetch('/reserver_billets', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({billets: cart}),
      });
      if (!response.ok) throw new Error('Erreur lors de la réservation');
      // Gérer la réponse du serveur ici
      alert('Réservation réussie');
      // Mettre à jour le contexte du panier, le vider si nécessaire
    } catch (error) {
      console.error('Échec de la réservation:', error);
    }
  };

  const menuVariants = {
    hidden: {
      x: '42rem',
      transition: {
        duration: 0.5,
        ease: [1, -0.02, 0, 1]
      }
    },
    visible: {
      x: 0,
      transition: {
        duration: 0.5,
        ease: [1, -0.02, 0, 1]
      }
    },


  };

  return (
    <motion.div
      className="side-menu cart"
      variants={menuVariants}
      initial="hidden"
      animate={isOpen ? "visible" : "hidden"}
    >
      <svg className="cross" onClick={() => setIsOpen(false)} width="36" height="28" viewBox="0 0 36 28" fill="none" xmlns="http://www.w3.org/2000/svg">
  <rect x="6.52539" y="0.321533" width="35.8974" height="3.58974" rx="1.79487" transform="rotate(45 6.52539 0.321533)" fill="#E45A3B"/>
  <rect x="3.87891" y="25.5957" width="35.8974" height="3.58974" rx="1.79487" transform="rotate(-45 3.87891 25.5957)" fill="#E45A3B"/>
</svg>
      <div className="container">
        <h2>Mon panier</h2>
        <section className='le-panier'>
          <AnimatePresence>
          {cart.length > 0 ? (
            cart.map((item) => (
              <ItemPanier
                key={item.uniqueId}
                id={item.id}
                typeBillet={item.id}
                title={item.title}
                price={typeof item.price === 'number' ? item.price : parseInt(item.price, 10)}
                quantite={item.quantity}
                selectedDays={item.selectedDaysSortedString ? item.selectedDaysSortedString.split('-') : undefined}
                uniqueId={item.uniqueId}
                />
                ))
                ) : (
                  <p>Panier Vide</p>
                  )}
              </AnimatePresence>
        </section>

        <div className="sous-total">
          <h4>Sous total: </h4>
          <h4>{subtotal.toFixed(2)}€</h4>
        </div>

        <Button onClick={handleReservation} text="RESERVER"></Button>
      </div>
    </motion.div>
  );
};

export default MenuPanier;import React, { useContext } from 'react';
import { CartContext } from '../../../../App.tsx'; 
import { setCookie } from '../../../../cookies/CookiesLib.tsx';
import { AnimatePresence, motion } from 'framer-motion';


type Props = {
    id: number;
    uniqueId: string;
    typeBillet: number,
    title: string,
    price: number,
    quantite: number,
    selectedDays?: Array<string>;
  };



export const ItemPanier: React.FC<Props> = ({ typeBillet, price, quantite, title, selectedDays, uniqueId}) => {
  const { cart, setCart } = useContext(CartContext);

  // Fonction pour enlever un billet du panier
  const removeFromCart = () => {
    const updatedCart = cart.filter((item) => item.uniqueId !== uniqueId);
    setCart(updatedCart);
    setCookie('cart', updatedCart, { expires: 7, sameSite: 'None', secure: true });
  };

  // Fonction pour mettre à jour la quantité d'un billet dans le panier
  const updateQuantity = (newQuantity: number) => {
    const updatedCart = cart.map((item) => {
      if (item.uniqueId === uniqueId) {
        return { ...item, quantity: newQuantity };
      }
      return item;
    });
    setCart(updatedCart);
    setCookie('cart', updatedCart, { expires: 7, path: '/' }); 
  };// Ajoutez le chemin si nécessaire

  const itemVariant = {
    hidden: { opacity: 0, x: -20 },
    visible: { opacity: 1, x: 0 },
    exit: { opacity: 0, x: 20, transition: {duration: 0.1} }
  };


  const daysList = selectedDays && (
    <div className="selected-days-container">
      {selectedDays.map(day => (
        <span key={day} className="selected-day-badge">{day}</span>
      ))}
    </div>
  );

  return (
      <motion.div
      className="item-panier"
      layout
      initial="visible"
      animate="visible"
      exit="exit"
      variants={itemVariant}
      key={uniqueId}
      >        <div className="container-item-panier">
            <div className="container-image">
                <img src="/images/billet.png" alt="billet" />
            </div>
            <div className="informations">
              <div className='partie-texte'>
                <div className="textes">
                    <h4>{title}</h4>
                    <h5>{price}€</h5> 
                    <div className="jours">
                    {daysList}
                    </div>
                </div>
                </div>
                <div className="compteur-quantitee">
                    <span className='ajout-retrait' onClick={() => updateQuantity(Math.max(0, quantite - 1))}>-</span>
                    <input type="number" className='quantite' value={quantite} readOnly />
                    <span className='ajout-retrait' onClick={() => updateQuantity(quantite + 1)}>+</span>
                </div>
            </div>
        </div>   
              <img className='cross' src="/icones/cross.svg" alt="croix" onClick={removeFromCart} />
    </motion.div>
  );
};import { TargetAndTransition, motion } from "framer-motion";
import { useContext, useState } from "react";
import Button from "../components/form/Button";
import { getCookie, setCookie } from "../cookies/CookiesLib.tsx";
import { CartContext } from "../App";

const initialDays = {
  "20 Jui": false,
  "21 Jui": false,
  "22 Jui": false,
};

type Props = {
  id: number;
  title: string;
  price: number | string;
  nbTicket: number;
  isForfait?: boolean;
  disabled?: boolean;
};

export default function TicketCard({
  id,
  title,
  price,
  nbTicket,
  isForfait,
}: Props) {
  const [isOpen, setIsOpen] = useState(false);
  const [tickets, setTickets] = useState(nbTicket);
  const [rotation, setRotation] = useState(0);
  const [days, setDays] = useState(initialDays);
  const { cart, setCart } = useContext(CartContext);
  const [isLoading, setIsLoading] = useState(false);
  const [isAdded, setIsAdded] = useState(false);
  type DayKey = "20 Jui" |"21 Jui"|"22 Jui";
  const pricesByDay:{[key in DayKey]: number} = {
    "20 Jui": 60,
    "21 Jui": 80,
    "22 Jui": 90,
  };


  const selectedDayCount = () => {
    return Object.values(days).filter(Boolean).length;
  }
  const isDisabled = tickets === 0 || (isForfait && selectedDayCount() !== 2); 

  const handleTicketChange = (newTickets: number, event: React.MouseEvent) => {
    event.stopPropagation();
    setTickets(newTickets);
  }


  const addToCartHandler = async (
    event: React.MouseEvent<HTMLButtonElement>
    ) => {
      event.stopPropagation();
      setIsLoading(true);

      // Longueur actuelle du panier dans les cookies
      const selectedDaysSortedString = isForfait
      ? Object.entries(days)
          .filter(([_, isChosen]) => isChosen)
          .map(([day, _]) => day)
          .sort()
          .join('-')
      : null;

      const calculPrixSelonJourSelec = isForfait && selectedDaysSortedString
    ? selectedDaysSortedString.split('-').reduce((total, dayKey) => {
        return total + pricesByDay[dayKey as DayKey];
      }, 0)
    : (typeof price === "number" ? price : 0);

    const uniqueId = isForfait && selectedDaysSortedString 
          ? `${id}-${selectedDaysSortedString}` 
          : `${id}`;    

    const itemForCart = {
      id,
      uniqueId,
      title,
      price: isForfait ? calculPrixSelonJourSelec : (typeof price === "number" ? price : 0),
      quantity: tickets,
      selectedDaysSortedString: isForfait ? selectedDaysSortedString : null,
    };


    // const currentCartLength = (getCookie("cart") || []).length;
    // condition non valide car si on ajoute un typê billet déjà présent dans le panier, 
    // l'ajout des nouveaux billets ne ferons que changer la valeur de quantité dans le tableau et 
    // donc la longueur du tableau ne changera pas
     // Initialise la vérification de l'ajout
  let expectedNewQuantity = itemForCart.quantity;
  let newCart = [...cart];


  const forfaitIndex = newCart.findIndex((billet) => billet.uniqueId === uniqueId);

  // si l'article existait déjà dans le panie on garde la quantité précédente et on détermine la nouvelle quantité attendue
  if (forfaitIndex > -1) {
    // si ce type de billet existe déjà, ajoute à la quantité et calcule la nouvelle quantité attendue
    expectedNewQuantity += newCart[forfaitIndex].quantity;
    newCart[forfaitIndex].quantity = expectedNewQuantity;
  } else {
    // sinon on l'ajoute au panier
    newCart.push(itemForCart);
  }
    setCart(newCart);
  setCookie("cart", newCart, { expires: 7, sameSite: "None", secure: true });

  setTimeout(() => {
    // trouver l'article après la mise à jour pour vérifier que la quantité est correcte
    const newForfaitIndex = newCart.findIndex((billet) => billet.uniqueId === uniqueId);
    const hasCorrectQuantity = newForfaitIndex > -1
      ? newCart[newForfaitIndex].quantity === expectedNewQuantity
      : false;

    if (hasCorrectQuantity) {
      setIsAdded(true);
    } else {
      console.error('Erreur : la quantité dans le panier ne correspond pas à la quantité attendue.');
    }

    setIsLoading(false);

    // Afficher le message 'ARTICLE AJOUTÉ' pendant un certain temps
    setTimeout(() => {
      setIsAdded(false);
    }, 2000);
  }, 400);
};
  const displayDay = (day: string) => day.replace("Juillet", "Juillet");

  const buttonVariants: { [key: string]: TargetAndTransition } = {
    tap: { scale: 0.95 },
    selected: { scale: 1.1, backgroundColor: "#E45A3B" },
    unselected: { scale: 1, backgroundColor: "#FFFFFF" },
  };

  const contentVariants = {
    closed: {
      opacity: 0,
      height: 0,
      overflow: "hidden",
      transition: {
        duration: 0.2,
        ease: "easeInOut",
        when: "afterChildren",
      },
    },
    open: {
      opacity: 1,
      height: title === "Forfait 2 jours" ? 160 : 150,
      transition: {
        duration: 0.2,
        ease: "easeInOut",
        when: "beforeChildren",
      },
    },
  };

  const cardVariants = {
    hidden: { opacity: 0, y: 50 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        type: "spring",
        stiffness: 120,
      },
    },
  };

  const maxSelectedDays = 2;

  const toggleDaySelection = (day: keyof typeof initialDays) => {
    setDays((prevDays) => {
      const isSelected = prevDays[day];
      const count = selectedDayCount();

      if (!isSelected && count >= maxSelectedDays) {
        return prevDays;
      }

      return { ...prevDays, [day]: !prevDays[day] };
    });
  };

  return (
    <motion.div
      className="ticket-card"
      layout
      initial="hidden"
      animate="visible"
      variants={cardVariants}
      onClick={() => {
        setIsOpen(!isOpen);
        setRotation(rotation === 0 ? 90 : 0);
      }}
    >
      <div className="content">
        <div className="left-part">
          <h4>{title}</h4>
          <p>Les tickets ne sont pas remboursables.</p>
          <p>Dernière entrée à 11H.</p>
        </div>
        <div className="right-part">
          <p>{price}€</p>
          <motion.div className="svg-container" animate={{ rotate: rotation }}>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="13"
              height="20"
              viewBox="0 0 13 20"
              fill="none"
            >
              <path d="M2 18L10 10L2 2" stroke="#4E4E4E" strokeWidth="4" />
            </svg>
          </motion.div>
        </div>
      </div>
      <motion.div
        className={`sub-menu ${
          title === "Forfait 2 jours" ? "forfait-2j" : ""
        }`}
        variants={contentVariants}
        initial="closed"
        animate={isOpen ? "open" : "closed"}
        exit="closed"
      >
        <div className="top-partsubmenu">
          <div className="left-part-sub">
            <div className="sub-menu-left-part">
              <div className="rect">
                <img
                  className=""
                  src="images/billet_pass1j.png"
                  alt="Billet pass 1 jour"
                />
              </div>
              <div className="container"></div>
              <div className="article-select">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  width="22"
                  height="21"
                  viewBox="0 0 22 21"
                  fill="none"
                >
                  <path
                    d="M22 9.03848H14.6966L19.8599 4.10947L17.6953 2.04109L12.532 6.97007V0H9.46799V6.97007L4.30475 2.04109L2.13807 4.10947L7.30131 9.03848H0V11.9615H7.30131L2.13807 16.8906L4.30475 18.9589L9.46799 14.0299V21H12.532V14.0299L17.6953 18.9589L19.8599 16.8906L14.6966 11.9615H22V9.03848Z"
                    fill="#FFD600"
                  />
                </svg>
                <p>x{tickets} Article(s) sélectionné(s)</p>
              </div>

            </div>

            <div className="ticket-control">
              <button
                className="minusButton"
                onClick={(event) =>
                  handleTicketChange(Math.max(tickets - 1, 0), event)
                }
              >
                -
              </button>
              <span>{tickets}</span>
              <button
                className="sommeButton"
                onClick={(event) => handleTicketChange(tickets + 1, event)}
              >
                +
              </button>
            </div>
          </div>
        </div>
        <div className="delimiter-submenu"></div>
        <div className="bottom-partsubmenu">
          <div className="bottom-part-left">
              <div className="day-checkbox-container">
                {isForfait &&
                  (Object.keys(days) as Array<keyof typeof initialDays>).map(
                    (day) => (
                      <motion.label
                        key={day}
                        className="day-checkbox"
                        whileTap="tap"
                      >
                        <input
                          type="checkbox"
                          checked={days[day]}
                          onChange={() => toggleDaySelection(day)}
                          style={{ display: "none" }}
                        />
                        <motion.div
                          className="day-button"
                          variants={buttonVariants}
                          animate={days[day] ? "selected" : "unselected"}
                        >
                          {displayDay(day)}
                        </motion.div>
                      </motion.label>
                    )
                  )}
              </div>
            <p>Sous-total</p>
            <p>{tickets * (typeof price === "number" ? price : 0)}€</p>
          </div>
          <Button
            text={
              isLoading
                ? "Chargement…"
                : isAdded
                ? "ARTICLE AJOUTÉ"
                : "AJOUT PANIER"
            }
            isLoading={isLoading}
            onClick={(event: React.MouseEvent<HTMLElement>) =>
              addToCartHandler(event as React.MouseEvent<HTMLButtonElement>)
            }
            isDisabled={isDisabled} // Passer la prop disabled ici
          />
        </div>
      </motion.div>
    </motion.div>
  );
}-- Table USER

