#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    char line[256];
    const int MAXN = 100;
    int a[MAXN][MAXN];
    int dr[4] = {1, 0, -1, 0};
    int dc[4] = {0, -1, 0, 1};

    while (fgets(line, sizeof(line), stdin)) {
        int n;
        if (sscanf(line, "%d", &n) != 1) continue;
        int r = 0, c = n - 1, dir = 0;
        for (int k = 1; k <= n * n; ++k) {
            a[r][c] = k;
            int nr = r + dr[dir];
            int nc = c + dc[dir];
            if (nr < 0 || nr >= n || nc < 0 || nc >= n || a[nr][nc] != 0) {
                dir = (dir + 1) % 4;
                nr = r + dr[dir];
                nc = c + dc[dir];
            }
            r = nr;
            c = nc;
        }
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (j) putchar(' ');
                printf("%d", a[i][j]);
            }
            putchar('\n');
        }
        putchar('\n');
    }
    return 0;
}

