下面给出一个完整、**安全**的登录实现示例（仅保留关键文件，全部放在同一代码块中，方便直接复制粘贴）。  
核心改进点：

1. **密码永不以明文存储**：在注册时使用 `BCryptPasswordEncoder` 对密码进行哈希；登录时再用 `matches()` 进行验证。  
2. **MyBatis Mapper 使用参数化查询**（`#{}`），防止 SQL 注入。  
3. **使用 Spring Security 的 `PasswordEncoder` 进行统一加密**。  
4. **登录成功后将管理员信息保存在 `HttpSession`，避免在前端暴露密码**。  

```java
/* ==========================================================
   1. com/example/admin/pojo/Admin.java
   ========================================================== */
package com.example.admin.pojo;

public class Admin {
    private Integer id;
    private String username;
    private String password;   // 存储的是 BCrypt 加密后的字符串
    // 省略 getter/setter
    public Integer getId() { return id; }
    public void setId(Integer id) { this.id = id; }
    public String getUsername() { return username; }
    public void setUsername(String username) { this.username = username; }
    public String getPassword() { return password; }
    public void setPassword(String password) { this.password = password; }
}

/* ==========================================================
   2. com/example/admin/mapper/AdminMapper.java
   ========================================================== */
package com.example.admin.mapper;

import com.example.admin.pojo.Admin;
import org.apache.ibatis.annotations.Select;
import org.apache.ibatis.annotations.Param;

public interface AdminMapper {
    // 参数化查询，防止 SQL 注入
    @Select("SELECT id, username, password FROM admin_user WHERE username = #{username}")
    Admin findByUsername(@Param("username") String username);
}

/* ==========================================================
   3. com/example/admin/service/AdminService.java
   ========================================================== */
package com.example.admin.service;

import com.example.admin.pojo.Admin;

public interface AdminService {
    /**
     * 验证管理员账号密码
     * @param username     登录名
     * @param rawPassword  明文密码
     * @return 若验证通过返回对应 Admin 对象，否则返回 null
     */
    Admin authenticate(String username, String rawPassword);
}

/* ==========================================================
   4. com/example/admin/service/UserServiceImpl.java
   ========================================================== */
package com.example.admin.service;

import com.example.admin.mapper.AdminMapper;
import com.example.admin.pojo.Admin;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;

@Service
public class AdminServiceImpl implements AdminService {

    @Autowired
    private AdminMapper adminMapper;

    @Autowired
    private PasswordEncoder passwordEncoder;  // 在配置类里注册的 BCryptPasswordEncoder

    @Override
    public Admin authenticate(String username, String rawPassword) {
        Admin admin = adminMapper.findByUsername(username);
        if (admin == null) {
            return null;  // 未找到用户
        }
        // BCryptPasswordEncoder.matches() 负责对比哈希值
        if (passwordEncoder.matches(rawPassword, admin.getPassword())) {
            return admin;   // 登录成功
        }
        return null;       // 密码错误
    }
}

