package com.example.admin.controller;

import com.example.admin.pojo.Admin;
import com.example.admin.service.AdminService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import javax.servlet.http.HttpServletRequest;
import org.springframework.ui.Model;

@Controller
@RequestMapping("/admin")
public class LoginController {

    @Autowired
    private AdminService adminService;

    /* 登录页面 */
    @GetMapping("/login")
    public String loginForm() {
        return "admin/login";   // 对应 /WEB-INF/views/admin/login.jsp
    }

    /* 登录提交 */
    @PostMapping("/login")
    public String login(@RequestParam String username,
                        @RequestParam String password,
                        HttpServletRequest request,
                        Model model) {

        Admin admin = adminService.authenticate(username, password);
        if (admin == null) {
            model.addAttribute("error", "用户名或密码错误");
            return "admin/login";
        }

        // 登录成功：把管理员信息保存在 session（不放密码）
        request.getSession().setAttribute("adminId", admin.getId());
        request.getSession().setAttribute("adminName", admin.getUsername());

        // 跳转到管理员主页
        return "redirect:/admin/home";
    }

    /* 后续示例：管理员主页（需加前置过滤器或注解防止未登录访问） */
    @GetMapping("/home")
    public String adminHome() {
        return "admin/home";
    }
}

