class MyUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        print(module)
        print(name)
        print(name.count("."))
        if module == "empty" and name.count(".") <= 1 and "setattr" not in name and "setitem" not in name:
            print("Success")
            return super().find_class(module, name)
        else:
