def check(data):
    for opcode,b,c in pickletools.genops(data):
        if opcode.name in BLACKLIST_OPCODES:
            print(f"Triggered on {opcode.name}")
    return (
        all(
            opcode.name not in BLACKLIST_OPCODES
            for opcode, _, _ in pickletools.genops(data)
        )
        and len(data) <= 400
    )


