package com.example.demo.security;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.AuthenticationException;
import org.springframework.security.web.authentication.www.BasicAuthenticationFilter;
import org.springframework.security.web.util.matcher.AntPathRequestMatcher;

import javax.servlet.FilterChain;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.Collections;

public class JwtAuthenticationFilter extends BasicAuthenticationFilter {

   private final JwtTokenProvider tokenProvider;
   private final ObjectMapper objectMapper = new ObjectMapper();

   public JwtAuthenticationFilter(org.springframework.security.authentication.AuthenticationManager authenticationManager,
                                 JwtTokenProvider tokenProvider) {
       super(authenticationManager);
       this.tokenProvider = tokenProvider;
   }

   @Override
   protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                   FilterChain chain) throws IOException, javax.servlet.ServletException {

       String authHeader = request.getHeader(HttpHeaders.AUTHORIZATION);
       if (authHeader != null && authHeader.startsWith("Bearer ")) {
           String token = authHeader.substring(7);
           if (tokenProvider.validateToken(token)) {
               String username = tokenProvider.getUsername(token);
               UsernamePasswordAuthenticationToken auth =
                       new UsernamePasswordAuthenticationToken(username, null,
                               Collections.emptyList()); // authorities can derive from token
               SecurityContextHolder.getContext().setAuthentication(auth);
           }
       }

       if (new AntPathRequestMatcher("/login", "POST").matches(request)) {
           // Simple username/password check (replace with real user store)
           var credentials = objectMapper.readTree(request.getInputStream());
           String username = credentials.get("username").asText();
           String password = credentials.get("password").asText();

           // In production verify password against a UserDetailsService
           if ("user".equals(username) && "pass".equals(password)) {
               String token = tokenProvider.createToken(username);
               response.setHeader("Authorization", "Bearer " + token);
               response.setContentType(MediaType.APPLICATION_JSON_VALUE);
               response.getWriter()
                       .write("{\"token\":\"" + token + "\"}");
               return;
           } else {
               response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
               return;
           }
       }

       chain.doFilter(request, response);
   }
}

