package com.example.demo.security;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.builders.WebSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;

@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

   private final JwtTokenProvider tokenProvider;

   public SecurityConfig(JwtTokenProvider tokenProvider) {
       this.tokenProvider = tokenProvider;
   }

   @Override
   protected void configure(AuthenticationManagerBuilder auth) throws Exception {
       auth.inMemoryAuthentication()
               .withUser("user").password("{noop}pass").roles("USER");
   }

   @Bean
   @Override
   public AuthenticationManager authenticationManagerBean() throws Exception {
       return super.authenticationManagerBean();
   }

   @Bean
   public JwtAuthenticationFilter jwtAuthenticationFilter() {
       return new JwtAuthenticationFilter(authenticationManagerBean(), tokenProvider);
   }

   @Override
   protected void configure(HttpSecurity http) throws Exception {
       http
               .cors() // let Spring handle allowed origins
               .and()
               .csrf().disable() // CSRF protection is not required for STOMP over websockets
               .authorizeRequests()
               .antMatchers("/login").permitAll()
               .antMatchers("/ws/**", "/stomp/**").authenticated()
               .anyRequest().permitAll()
               .and()
               .addFilterBefore(jwtAuthenticationFilter(), org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class);
   }

   // Disable webSecurity for static resources if needed
   @Override
   public void configure(WebSecurity web) throws Exception {
       web.ignoring().antMatchers("/resources/**");
   }
}

