// 6. WebSocketConfig.java (STOMP over WebSocket + authentication interceptor)
// The handshake interceptor extracts JWT from a request header or query param
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////

package com.example.demo.websocket;

import com.example.demo.security.JwtTokenProvider;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.server.ServerHttpRequest;
import org.springframework.http.server.ServerHttpResponse;
import org.springframework.messaging.Message;
import org.springframework.messaging.MessageChannel;
import org.springframework.messaging.support.ChannelInterceptor;
import org.springframework.messaging.support.MessageHeaderAccessor;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.userdetails.User;
import org.springframework.web.socket.WebSocketHandler;
import org.springframework.web.socket.server.HandshakeInterceptor;
import org.springframework.web.socket.config.annotation.*;

import java.util.Map;
import java.util.Objects;

@Configuration
@EnableWebSocketMessageBroker
public class WebSocketConfig implements WebSocketMessageBrokerConfigurer {

   private final JwtTokenProvider tokenProvider;

   public WebSocketConfig(JwtTokenProvider tokenProvider) {
       this.tokenProvider = tokenProvider;
   }

   @Override
   public void registerStompEndpoints(StompEndpointRegistry registry) {
       registry.addEndpoint("/ws")
               .addInterceptors(new JwtHandshakeInterceptor(tokenProvider))
               .setAllowedOriginPatterns("*") // production: restrict to domains
               .withSockJS(); // optionally use SockJS fallback
   }

   @Override
   public void configureMessageBroker(MessageBrokerRegistry registry) {
       registry.enableSimpleBroker("/topic", "/queue");
       registry.setApplicationDestinationPrefixes("/app");
   }

   // Optional: ChannelInterceptor to enforce authentication on every message
   @Override
   public void configureClientOutboundChannel(ChannelRegistration registration) {
       registration.interceptors(new AuthenticationChannelInterceptor());
   }

   // -----  HandshakeInterceptor -----
   private static class JwtHandshakeInterceptor implements HandshakeInterceptor {
       private final JwtTokenProvider tokenProvider;

       public JwtHandshakeInterceptor(JwtTokenProvider tokenProvider) {
           this.tokenProvider = tokenProvider;
       }

       @Override
       public boolean beforeHandshake(ServerHttpRequest request, ServerHttpResponse response,
                                      WebSocketHandler wsHandler, Map<String, Object> attributes) throws Exception {
           // Expect token in header or query param "token"
           String token = request.getHeaders().getFirst("Authorization");
           if (token != null && token.startsWith("Bearer ")) {
               token = token.substring(7);
           } else {
               token = request.getURI().getQuery() != null
                       ? request.getURI().getQuery().replace("token=", "")
                       : null;
           }

           if (token != null && tokenProvider.validateToken(token)) {
               String username = tokenProvider.getUsername(token);
               // store the authenticated principal in the session attributes
               attributes.put("user", new User(username, "", java.util.Collections.emptyList()));
               return true;
           }
           return false; // reject handshake
       }

       @Override
       public void afterHandshake(ServerHttpRequest request, ServerHttpResponse response,
                                  WebSocketHandler wsHandler, Exception exception) {}
   }

   // -----  ChannelInterceptor to reject unauthenticated messages -----
   private static class AuthenticationChannelInterceptor implements ChannelInterceptor {
       @Override
       public Message<?> preSend(Message<?> message, MessageChannel channel) {
           MessageHeaderAccessor accessor = MessageHeaderAccessor.getAccessor(message, MessageHeaderAccessor.class);
           if (accessor != null) {
               Authentication auth = accessor.getLeaveMutable().get("simpUser");
               if (!(auth instanceof User)) {
                   throw new IllegalStateException("Unauthenticated user");
               }
           }
           return message;
       }
   }
}

