            // creo un pool di thread per gestire connessioni in parallelo
            ExecutorService threadPool = Executors.newFixedThreadPool(20);

            while (true) {
                // rimango in attesa di connessioni, accetto la connessione e passo il socket al ClientHandler usando un thread del pool
                threadPool.execute(new ClientHandler(listener.accept(), server));
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void readConfig() throws FileNotFoundException, IOException {
        InputStream input = Server.class.getResourceAsStream(configFile);
        Properties prop = new Properties();
        prop.load(input);
        port = Integer.parseInt(prop.getProperty("port"));
        maxDelay = Integer.parseInt(prop.getProperty("maxDelay"));
        input.close();
        String hotelsJsonFilePath = "Hotels.json";
        String usersJsonFilePath = "Users.json";
        String reviewJsonFilePath = "Review.json";
        HOTELIERServer server = new HOTELIERServer(hotelsJsonFilePath, usersJsonFilePath, reviewJsonFilePath);
    }
}



