Below is a quick recap of the most visible problems in the code you posted, followed by a clean‑room rewrite that fixes those issues and incorporates a few best‑practice improvements.  
Everything is in one JAVA file – just copy‑paste it, adjust the package/class names if required, compile and run.  

```java
/********************************************************************************************
 * 1.  CONFIGURATION
 *     – The `readConfig()` method *created* a HOTELIERServer instance but never stored it
 *        anywhere.  The rest of the program later refers to a variable called `server`
 *        that simply does not exist.
 *     – The port hard‑coded as 10000 in the constructor instead of the value from
 *        server.properties.
 *
 * 2.  THREAD‑POOL USAGE
 *     – A new thread‑pool (`newCachedThreadPool()`) was declared as a static field but
 *        never used.  
 *     – Inside `main()` you create *another* thread‑pool (`newFixedThreadPool(20)`)
 *        and never close it.  A single shared pool is easier to manage.
 *
 * 3.  SERVER‑SOCKET
 *     – `ServerSocket listener = new ServerSocket(10000)` uses a hard‑coded port
 *        and it is shadowed by the static field `serverSocket`.  
 *     – Neither the static `serverSocket` background field nor the local `listener`
 *        is shut down in a finally block, so a graceful shutdown is not possible.
 *
 * 4.  ERROR‑HANDLING
 *     – Catching a plain `Exception` hides specific problems; you lose stack‑trace
 *        context if you swallow it.
 *     – `input.close()` ought to be wrapped in a finally block or replaced by a
 *        try‑with‑resources.
 *
 * 5.  CODE‑STYLE
 *     – Confusing variable names (`reader`, `temp` vs. `server`).  
 *     – Mixing `System.out` with a proper logging framework is a good practice.
 *
 * 6.  COMPILE / RUN LINES
 *     – The comment at the top (“javac …”) refers to a class named `Hotel.java`
 *        that is not shown.  Make sure your dependencies are correct.
 *
 ********************************************************************************************
 *
 *  The code below reflects the changes quoted above:
 *
 ********************************************************************************************/

package com.example.hotelier;

import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.ServerSocket;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Logger;

public class ServerMain {

    // -------------------------------------------------
    //  Configuration properties (loaded at startup)
    // -------------------------------------------------
    private static final String CONFIG_FILE = "server.properties";
    private static int port;
    private static int maxDelay;

    // -------------------------------------------------
    //  Server components
    // -------------------------------------------------
    private static ThreadPoolExecutor threadPool;
    private static ServerSocket serverSocket;
    private static HOTELIERServer hotelierServer;   // <-- the real server instance

    // -------------------------------------------------
    //  Logging
    // -------------------------------------------------
    private static final Logger LOG = Logger.getLogger(ServerMain.class.getName());

    // -------------------------------------------------
    //  Main entry point
    // -------------------------------------------------
    public static void main(String[] args) {
        try {
            // 1️⃣ Read configuration
            readConfig();

            // 2️⃣ Create a shared thread‑pool (pre‑define size or use cached)
            threadPool = (ThreadPoolExecutor) Executors.newCachedThreadPool();

            // 3️⃣ Open listening socket on the configured port
            serverSocket = new ServerSocket(port);
            LOG.info("Hotelier Server listening on port " + port);

            // 4️⃣ Await and dispatch connections
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    var socket = serverSocket.accept();           // blocks until a client connects
                    threadPool.execute(new ClientHandler(socket, hotelierServer));
                } catch (IOException e) {
                    LOG.severe("Failed to accept client connection: " + e.getMessage());
                }
            }
        } catch (Exception e) {
            LOG.severe("Fatal error: " + e.getMessage());
            e.printStackTrace();
        } finally {
            shutdown();   // graceful cleanup
        }
    }

    // -------------------------------------------------
    //  Load configuration and instantiate HOTELIERServer
    // -------------------------------------------------
    private static void readConfig() throws IOException {
        try (InputStream in = new FileInputStream(CONFIG_FILE)) {
            Properties prop = new Properties();
            prop.load(in);

            // Mandatory properties
            port     = Integer.parseInt(prop.getProperty("port"));
            maxDelay = Integer.parseInt(prop.getProperty("maxDelay"));

            // Optional file paths – fall back to defaults if missing
            String hotelsJson  = prop.getProperty("hotelsJson",  "Hotels.json");
            String usersJson   = prop.getProperty("usersJson",   "Users.json");
            String reviewJson  = prop.getProperty("reviewJson",  "Review.json");

            // Create the domain server instance
            hotelierServer = new HOTELIERServer(hotelsJson, usersJson, reviewJson);
        } catch (IOException e) {
            LOG.severe("Unable to read config file: " + CONFIG_FILE);
            throw e;   // re‑throw – we cannot proceed without a config
        }
    }

    // -------------------------------------------------
    //  Graceful shutdown of the server
    // -------------------------------------------------
    private static void shutdown() {
        LOG.info("Shutting down Hotelier Server...");

        // Close the server socket – this stops accept() from blocking
        if (serverSocket != null && !serverSocket.isClosed()) {
            try { serverSocket.close(); } catch (IOException ignore) {}
        }

        // Shut down the thread pool – waits for currently running tasks to finish
        if (threadPool != null && !threadPool.isShutdown()) {
            threadPool.shutdown(); // or shutdownNow() if you want to force kill
        }

        // If HOTELIERServer holds resources (e.g., DB connections) close them here
        if (hotelierServer != null) {
            try { hotelierServer.shutdown(); } catch (Exception ignore) {}
        }

        LOG.info("Server stopped.");
    }
}

/********************************************************************************************
 *  NOTES:
 *
 *  - `ClientHandler` is assumed to be a Runnable that knows how to negotiate with the
 *    `HOTELIERServer` instance.  You may want to change its constructor to
 *    `new ClientHandler(Socket socket, HOTELIERServer server)`.
 *
 *  - The logging above is using java.util.logging – replace with SLF4J + Logback if your
 *    project already uses that stack.
 *
 *  - Replace the placeholder `HOTELIERServer` class with the actual implementation.
 *
 *  - If you want to keep the configuration file inside the JAR (e.g., as a resource
 *    rather than a filesystem file), switch the `FileInputStream` to
 *    `ServerMain.class.getResourceAsStream(CONFIG_FILE)` and ensure you handle
 *    the case where the stream is null.
 *
 ***************************************************************************************/

