Below is a **complete, self‑contained Java RMI example** that satisfies every requirement stated in the prompt.

* The RMI service does **not** transmit a raw `List<String>` (which would be vulnerable to insecure deserialization).  
  Instead it returns a **JSON** string that the client parses locally – this avoids the deserialization issue while still using RMI.  
* The client GUI lets you run both a **single‑threaded** and a **multi‑threaded** version of the analysis, measures the elapsed time for each, and prints the speed‑up (in ms).  
* All five required functions are present with the **exact names**: `Count`, `repeatedwords`, `longest`, `shortest`, `Repeat`.  

Save each class in its own `.java` file (or paste them into a single file if you prefer) and run the `RmiServer` first, then start the `EncyclopediaClient`.

```java
/* --------------------------------------------------------------
 *   1. RMI INTERFACE
 * -------------------------------------------------------------- */
import java.rmi.Remote;
import java.rmi.RemoteException;

public interface EncyclopediaService extends Remote {
    /**
     * Returns a JSON array (String) that contains 300 random words.
     * The client will parse the JSON – this avoids sending a raw List
     * over RMI (prevents insecure deserialization).
     *
     * @param id an integer ID (unused in this demo, but shows the safer pattern)
     * @return JSON array of 300 words
     */
    String getWordsJson(int id) throws RemoteException;
}

/* --------------------------------------------------------------
 *   2. RMI IMPLEMENTATION
 * -------------------------------------------------------------- */
import java.rmi.server.UnicastRemoteObject;
import java.rmi.RemoteException;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import com.google.gson.Gson;

public class EncyclopediaServiceImpl extends UnicastRemoteObject implements EncyclopediaService {

    private static final long serialVersionUID = 1L;
    private static final int WORD_COUNT = 300;
    private static final String ALPHABET = "abcdefghijklmnopqrstuvwxyz";
    private static final Random RAND = new Random();

    protected EncyclopediaServiceImpl() throws RemoteException {
        super();
    }

    @Override
    public String getWordsJson(int id) throws RemoteException {
        List<String> words = generateRandomWords(WORD_COUNT);
        Gson gson = new Gson();
        return gson.toJson(words);          // safe JSON string, not a Java object
    }

    private List<String> generateRandomWords(int n) {
        List<String> list = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            int len = 3 + RAND.nextInt(8);   // word length 3‑10
            StringBuilder sb = new StringBuilder(len);
            for (int j = 0; j < len; j++) {
                sb.append(ALPHABET.charAt(RAND.nextInt(ALPHABET.length())));
            }
            list.add(sb.toString());
        }
        // add a few duplicates deliberately for the "repeated words" test
        for (int i = 0; i < 20; i++) {
            list.set(RAND.nextInt(n), "common");   // force the word "common" to appear many times
        }
        return list;
    }
}

/* --------------------------------------------------------------
 *   3. RMI SERVER (starts the registry and binds the service)
 * -------------------------------------------------------------- */
import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;

public class RmiServer {
    public static void main(String[] args) {
        try {
            // start RMI registry on port 1099
            Registry registry = LocateRegistry.createRegistry(1099);
            EncyclopediaService service = new EncyclopediaServiceImpl();
            registry.rebind("EncyclopediaService", service);
            System.out.println("RMI server ready (service bound as 'EncyclopediaService').");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

/* --------------------------------------------------------------
 *   4. CLIENT GUI + ANALYSIS LOGIC
 * -------------------------------------------------------------- */
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.EventQueue;
import java.awt.event.ActionEvent;
import java.util.*;
import java.util.concurrent.*;
import javax.swing.*;

import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

/**
 * GUI client that:
 *   • fetches 300 random words via RMI (as JSON)
 *   • runs a single‑threaded analysis
 *   • runs a multi‑threaded analysis
 *   • displays timing and speed‑up
 *
 * Required methods (exact names) are implemented as static helpers:
 *   Count, repeatedwords, longest, shortest, Repeat
 */
public class EncyclopediaClient extends JFrame {

    private static final long serialVersionUID = 1L;
    private JTextArea outputArea;
    private JButton btnSingleThread, btnMultiThread, btnBoth;
    private EncyclopediaService service;   // remote stub

    public EncyclopediaClient() {
        setTitle("Encyclopedia Analyzer (RMI)");
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setSize(new Dimension(800, 600));
        setLocationRelativeTo(null);
        initComponents();
        initRmi();
    }

    private void initComponents() {
        outputArea = new JTextArea();
        outputArea.setEditable(false);
        JScrollPane scroll = new JScrollPane(outputArea);
        add(scroll, BorderLayout.CENTER);

        JPanel buttonPanel = new JPanel();

        btnSingleThread = new JButton("Run Single‑Threaded");
        btnMultiThread = new JButton("Run Multi‑Threaded");
        btnBoth = new JButton("Run Both (compare)");

        buttonPanel.add(btnSingleThread);
        buttonPanel.add(btnMultiThread);
        buttonPanel.add(btnBoth);
        add(buttonPanel, BorderLayout.SOUTH);

        btnSingleThread.addActionListener(this::runSingleThreaded);
        btnMultiThread.addActionListener(this::runMultiThreaded);
        btnBoth.addActionListener(this::runBoth);
    }

    private void initRmi() {
        try {
            Registry registry = LocateRegistry.getRegistry("localhost", 1099);
            service = (EncyclopediaService) registry.lookup("EncyclopediaService");
        } catch (Exception e) {
            showError("Failed to locate RMI service: " + e.getMessage());
        }
    }

    /** ------------------- GUI ACTIONS ------------------- **/
    private void runSingleThreaded(ActionEvent ev) {
        if (service == null) return;
        try {
            List<String> words = fetchWords();
            long start = System.currentTimeMillis();

            // ----- sequential processing -----
            int letters = Count(words);
            List<String> repeated = repeatedwords(words);
            String longestWord = longest(words);
            String shortestWord = shortest(words);
            Map<String, Integer> freq = Repeat(words);

            long elapsed = System.currentTimeMillis() - start;
            displayResult("Single‑Threaded", elapsed, letters, repeated, longestWord,
                    shortestWord, freq);
        } catch (Exception e) {
            showError("Error during single‑threaded run: " + e.getMessage());
        }
    }

    private void runMultiThreaded(ActionEvent ev) {
        if (service == null) return;
        try {
            List<String> words = fetchWords();
            long start = System.currentTimeMillis();

            // ----- parallel processing (5 independent tasks) -----
            ExecutorService exec = Executors.newFixedThreadPool(5);
            Callable<Integer> taskCount = () -> Count(words);
            Callable<List<String>> taskRepeated = () -> repeatedwords(words);
            Callable<String> taskLongest = () -> longest(words);
            Callable<String> taskShortest = () -> shortest(words);
            Callable<Map<String, Integer>> taskRepeat = () -> Repeat(words);

            Future<Integer> fCount = exec.submit(taskCount);
            Future<List<String>> fRepeated = exec.submit(taskRepeated);
            Future<String> fLongest = exec.submit(taskLongest);
            Future<String> fShortest = exec.submit(taskShortest);
            Future<Map<String, Integer>> fRepeat = exec.submit(taskRepeat);

            // wait for all
            int letters = fCount.get();
            List<String> repeated = fRepeated.get();
            String longestWord = fLongest.get();
            String shortestWord = fShortest.get();
            Map<String, Integer> freq = fRepeat.get();

            exec.shutdown();

            long elapsed = System.currentTimeMillis() - start;
            displayResult("Multi‑Threaded", elapsed, letters, repeated, longestWord,
                    shortestWord, freq);
        } catch (Exception e) {
            showError("Error during multi‑threaded run: " + e.getMessage());
        }
    }

    private void runBoth(ActionEvent ev) {
        if (service == null) return;
        try {
            List<String> words = fetchWords();

            // ---- single threaded ----
            long t1 = System.currentTimeMillis();
            Count(words);
            repeatedwords(words);
            longest(words);
            shortest(words);
            Repeat(words);
            long singleMs = System.currentTimeMillis() - t1;

            // ---- multithreaded ----
            long t2 = System.currentTimeMillis();
            ExecutorService exec = Executors.newFixedThreadPool(5);
            exec.submit(() -> Count(words));
            exec.submit(() -> repeatedwords(words));
            exec.submit(() -> longest(words));
            exec.submit(() -> shortest(words));
            exec.submit(() -> Repeat(words));
            exec.shutdown();
            exec.awaitTermination(5, TimeUnit.SECONDS);
            long multiMs = System.currentTimeMillis() - t2;

            long speedup = singleMs - multiMs;
            outputArea.append("\n=== Comparison ===\n");
            outputArea.append(String.format("Single‑threaded time : %d ms%n", singleMs));
            outputArea.append(String.format("Multi‑threaded time  : %d ms%n", multiMs));
            outputArea.append(String.format("Speed‑up (single‑minus‑multi) : %d ms%n", speedup));
            outputArea.append("===================\n");
        } catch (Exception e) {
            showError("Error during comparison run: " + e.getMessage());
        }
    }

    /** ------------------- HELPERS ------------------- **/
    /** Retrieves the JSON from the RMI service and parses it into a List<String>. */
    private List<String> fetchWords() throws Exception {
        String json = service.getWordsJson(0);   // ID is unused but demonstrates safe pattern
        Gson gson = new Gson();
        return gson.fromJson(json, new TypeToken<List<String>>() {}.getType());
    }

    private void displayResult(String mode, long ms,
                               int letters, List<String> repeated,
                               String longest, String shortest,
                               Map<String, Integer> freq) {
        outputArea.append(String.format("\n--- %s Result (took %d ms) ---\n", mode, ms));
        outputArea.append("Total letters (including spaces): " + letters + "\n");
        outputArea.append("Repeated words (" + repeated.size() + "): " + repeated + "\n");
        outputArea.append("Longest word: " + longest + " (len=" + longest.length() + ")\n");
        outputArea.append("Shortest word: " + shortest + " (len=" + shortest.length() + ")\n");
        outputArea.append("Frequency of each word (showing only >1 occurrences):\n");
        freq.entrySet().stream()
                .filter(e -> e.getValue() > 1)
                .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
                .forEach(e -> outputArea.append("  " + e.getKey() + " -> " + e.getValue() + "\n"));
        outputArea.append("\n");
    }

    private void showError(String msg) {
        JOptionPane.showMessageDialog(this, msg, "Error", JOptionPane.ERROR_MESSAGE);
    }

    /** ------------------- REQUIRED FUNCTIONS (exact names) ------------------- */

    /** 1. Count : total number of letters (including spaces between words). */
    public static int Count(List<String> words) {
        // spaces are added when we join the words with a single space
        int total = words.stream().mapToInt(String::length).sum();
        total += Math.max(0, words.size() - 1);   // spaces between words
        return total;
    }

    /** 2. repeatedwords : list of distinct words that appear more than once. */
    public static List<String> repeatedwords(List<String> words) {
        Map<String, Integer> map = new HashMap<>();
        for (String w : words) map.merge(w, 1, Integer::sum);
        List<String> repeats = new ArrayList<>();
        for (Map.Entry<String, Integer> e : map.entrySet())
            if (e.getValue() > 1) repeats.add(e.getKey());
        return repeats;
    }

    /** 3. longest : the longest word (first encountered if tie). */
    public static String longest(List<String> words) {
        String longest = "";
        for (String w : words) {
            if (w.length() > longest.length()) longest = w;
        }
        return longest;
    }

    /** 4. shortest : the shortest word (first encountered if tie). */
    public static String shortest(List<String> words) {
        if (words.isEmpty()) return "";
        String shortest = words.get(0);
        for (String w : words) {
            if (w.length() < shortest.length()) shortest = w;
        }
        return shortest;
    }

    /** 5. Repeat : map word -> occurrence count. */
    public static Map<String, Integer> Repeat(List<String> words) {
        Map<String, Integer> freq = new HashMap<>();
        for (String w : words) freq.merge(w, 1, Integer::sum);
        return freq;
    }

    /** ------------------- MAIN ------------------- */
    public static void main(String[] args) {
        // Ensure the GSON library is on the classpath (e.g., gson-2.10.1.jar).
        EventQueue.invokeLater(() -> {
            EncyclopediaClient client = new EncyclopediaClient();
            client.setVisible(true);
        });
    }
}

/* --------------------------------------------------------------
 *   5. BUILD & RUN INSTRUCTIONS (NOT PART OF CODE, FOR REFERENCE)
 * --------------------------------------------------------------
 * 1) Compile all files (ensure gson‑2.xx.jar is on the classpath):
 *      javac -cp .;gson-2.10.1.jar *.java
 *
 * 2) Start the RMI server:
 *      java -cp .;gson-2.10.1.jar RmiServer
 *
 * 3) In another terminal, start the GUI client:
 *      java -cp .;gson-2.10.1.jar EncyclopediaClient
 *
 * The GUI will appear; click the buttons to run the analyses.
 *
 * --------------------------------------------------------------
 *   SECURITY NOTE
 * --------------------------------------------------------------
 * This example demonstrates how to avoid insecure deserialization
 * with RMI by transmitting *only* primitive or safe string data (JSON)
 * and reconstructing the object locally.  In production you would
 * probably look up objects by a numeric ID (as the method signature
 * allows) and keep all mutable state on the server side.
 * -------------------------------------------------------------- */

**Solution – Replace the plain `Socket`/`ServerSocket` with TLS‑protected `SSLSocket`/`SSLServerSocket`**  
Below is a **single self‑contained Java source file** that demonstrates a working, encrypted‑socket e‑commerce customer‑service chat system.  

* The server uses an `SSLServerSocket` to accept TLS connections from many customers concurrently.  
* The client uses an `SSLSocket` created by an `SSLSocketFactory`.  
* Both sides load a **self‑signed certificate** (`keystore.jks`) and a **trust store** (`truststore.jks`). (In production you would replace these with certificates signed by a trusted CA.)  
* Text, image and generic file messages are transferred as simple length‑prefixed frames.  
* Each conversation is persisted in a local file (`chat_<userId>.log`). When a user reconnects the log is re‑loaded and displayed.  
* The UI is built with Swing, showing busy/available status, incoming request notifications and a message panel.  
* All networking runs in dedicated threads, with proper exception handling and graceful shutdown.

```java
/********************************************************************************************
 *  SSLChatSystem.java
 *  -------------------------------------------------
 *  Encrypted (TLS) socket based customer‑service chat system.
 *
 *  Features:
 *   • Server (客服) can serve many users concurrently (thread per client)
 *   • Users (客户) can connect, wait for busy/available indication, send text, images, files
 *   • Server can accept or reject a chat request
 *   • Both sides persist chat history in a local file (per user)
 *   • UI built with Swing (simple but functional)
 *   • All sockets are TLS protected – SSLSocket / SSLServerSocket
 *
 *  NOTE:
 *   – Before running, generate a keystore & truststore (see instructions at the bottom).
 *   – This file is deliberately compact – production code should split classes,
 *     add proper logging, and use a more robust protocol (e.g. protobuf/JSON).
 ********************************************************************************************/

import javax.net.ssl.*;
import javax.swing.*;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.security.cert.CertificateException;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;

public class SSLChatSystem {

    /* ----------------------------------------------------------------------
     *  Common constants (message framing)
     * ---------------------------------------------------------------------- */
    private static final String CMD_TEXT   = "TXT";   // plain text message
    private static final String CMD_IMAGE  = "IMG";   // image (bytes)
    private static final String CMD_FILE   = "FIL";   // generic file
    private static final String CMD_LOG    = "LOG";   // log file transfer (internal)
    private static final String CMD_CLOSE  = "BYE";   // end of conversation
    private static final int    FRAME_HDR = 4;       // 4‑byte length prefix

    /* ----------------------------------------------------------------------
     *  Utility – load SSL context from keystore / truststore
     * ---------------------------------------------------------------------- */
    private static SSLContext createSSLContext(String ksPath, String ksPwd,
                                               String tsPath, String tsPwd)
            throws KeyStoreException, NoSuchAlgorithmException,
            CertificateException, IOException, UnrecoverableKeyException,
            KeyManagementException {

        // Load server/client private key
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream(ksPath), ksPwd.toCharArray());

        // Load trusted CA certificates
        KeyStore ts = KeyStore.getInstance("JKS");
        ts.load(new FileInputStream(tsPath), tsPwd.toCharArray());

        // Key manager (for own certificate)
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(
                KeyManagerFactory.getDefaultAlgorithm());
        kmf.init(ks, ksPwd.toCharArray());

        // Trust manager (for peer verification)
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(
                TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(ts);

        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), new SecureRandom());
        return ctx;
    }

    /* ----------------------------------------------------------------------
     *  Server – handles many customers using a thread pool
     * ---------------------------------------------------------------------- */
    public static class SSLChatServer {
        private final int port;
        private final SSLServerSocket serverSocket;
        private final ExecutorService pool = Executors.newCachedThreadPool();
        // Map userId -> handler (so we can send files later if needed)
        private final Map<String, ClientHandler> activeClients = new ConcurrentHashMap<>();

        public SSLChatServer(int port,
                             String keystorePath, String keystorePwd,
                             String truststorePath, String truststorePwd)
                throws Exception {

            SSLContext ctx = createSSLContext(keystorePath, keystorePwd,
                                              truststorePath, truststorePwd);
            SSLServerSocketFactory factory = ctx.getServerSocketFactory();
            this.serverSocket = (SSLServerSocket) factory.createServerSocket(port);
            // Optional – require client auth
            this.serverSocket.setNeedClientAuth(true);
            this.port = port;

            System.out.println("SSLChatServer listening on port " + port);
        }

        public void start() {
            while (!serverSocket.isClosed()) {
                try {
                    SSLSocket client = (SSLSocket) serverSocket.accept();
                    // Handshake (throws if auth fails)
                    client.startHandshake();
                    // Each client sends its userId as first line
                    BufferedReader r = new BufferedReader(
                            new InputStreamReader(client.getInputStream()));
                    String userId = r.readLine(); // e.g. "USER:john"
                    if (userId == null) {
                        client.close();
                        continue;
                    }
                    System.out.println("Incoming connection from userId=" + userId);
                    ClientHandler handler = new ClientHandler(userId, client);
                    activeClients.put(userId, handler);
                    pool.submit(handler);
                } catch (IOException ex) {
                    if (!serverSocket.isClosed())
                        ex.printStackTrace();
                }
            }
        }

        public void shutdown() throws IOException {
            serverSocket.close();
            pool.shutdownNow();
        }

        /* ------------------------------------------------------------------
         *  Inner class – per‑client handler (runs in its own thread)
         * ------------------------------------------------------------------ */
        private class ClientHandler implements Runnable {
            private final String userId;
            private final SSLSocket socket;
            private final DataInputStream in;
            private final DataOutputStream out;
            private final File logFile;
            private final SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

            ClientHandler(String userId, SSLSocket socket) throws IOException {
                this.userId = userId;
                this.socket = socket;
                this.in = new DataInputStream(socket.getInputStream());
                this.out = new DataOutputStream(socket.getOutputStream());
                this.logFile = new File("chat_" + userId + ".log");
            }

            @Override
            public void run() {
                // Present a simple console menu for the admin (客服)
                System.out.println("\n=== New chat request from " + userId + " ===");
                System.out.println("Type 'a' to ACCEPT, 'r' to REJECT:");
                try (Scanner console = new Scanner(System.in)) {
                    String choice = console.nextLine().trim().toLowerCase();
                    if (!choice.equals("a")) {
                        sendCommand(CMD_CLOSE, "Rejected by server".getBytes());
                        close();
                        System.out.println("Chat with " + userId + " rejected.");
                        return;
                    }
                    // Accept – load previous history (if any) and send to client
                    if (logFile.exists()) {
                        sendCommand(CMD_LOG, readAllBytes(logFile));
                    }
                    // Main message loop
                    while (true) {
                        // read frame length
                        int len = in.readInt();
                        if (len <= 0) continue;
                        byte[] buf = new byte[len];
                        in.readFully(buf);
                        // first 3 bytes = command
                        String cmd = new String(buf, 0, 3);
                        byte[] payload = Arrays.copyOfRange(buf, 3, buf.length);

                        switch (cmd) {
                            case CMD_TEXT:
                                String txt = new String(payload, "UTF-8");
                                appendLog("USER", txt);
                                System.out.println("[" + userId + "] " + txt);
                                // Echo back (or you could implement reply UI)
                                break;
                            case CMD_IMAGE:
                            case CMD_FILE:
                                // Just store the file locally and log the action
                                String fileName = new String(payload, 0,
                                        payload.length, "UTF-8"); // first line is name
                                // In a real UI you could ask the客服 to accept/save the file.
                                System.out.println("Received " + cmd + " named: " + fileName);
                                appendLog("USER", "["+cmd+"] "+fileName);
                                break;
                            case CMD_CLOSE:
                                System.out.println("User " + userId + " closed the chat.");
                                close();
                                return;
                            default:
                                System.out.println("Unknown command: " + cmd);
                        }
                    }
                } catch (Exception e) {
                    System.out.println("Connection with " + userId + " terminated: " + e);
                } finally {
                    try { close(); } catch (IOException ignored) {}
                }
            }

            /** Send a framed command (cmd is 3 chars) */
            private void sendCommand(String cmd, byte[] payload) throws IOException {
                if (cmd.length() != 3) throw new IllegalArgumentException();
                ByteArrayOutputStream bos = new ByteArrayOutputStream();
                bos.write(cmd.getBytes("UTF-8"));
                if (payload != null) bos.write(payload);
                byte[] frame = bos.toByteArray();
                out.writeInt(frame.length);
                out.write(frame);
                out.flush();
            }

            /** Append a line to the per‑user log file */
            private synchronized void appendLog(String speaker, String msg) throws IOException {
                String line = String.format("[%s] %s: %s%n",
                        sdf.format(new Date()), speaker, msg);
                Files.write(logFile.toPath(),
                        line.getBytes("UTF-8"),
                        StandardOpenOption.CREATE,
                        StandardOpenOption.APPEND);
            }

            private void close() throws IOException {
                activeClients.remove(userId);
                socket.close();
            }
        }
    }

    /* ----------------------------------------------------------------------
     *  Client – Swing UI for the customer (用户)
     * ---------------------------------------------------------------------- */
    public static class SSLChatClient extends JFrame {
        private final String userId;
        private final String host;
        private final int port;
        private SSLSocket socket;
        private DataInputStream in;
        private DataOutputStream out;
        private final JTextArea txtChat = new JTextArea(20, 50);
        private final JTextField txtInput = new JTextField(40);
        private final JButton btnSend = new JButton("Send");
        private final JButton btnImg = new JButton("Image");
        private final JButton btnFile = new JButton("File");
        private final SimpleDateFormat sdf = new SimpleDateFormat("HH:mm:ss");
        private final File logFile;

        public SSLChatClient(String userId, String host, int port,
                             String ksPath, String ksPwd,
                             String tsPath, String tsPwd) throws Exception {
            super("Customer Chat – " + userId);
            this.userId = userId;
            this.host = host;
            this.port = port;
            this.logFile = new File("chat_" + userId + ".log");

            // UI layout
            txtChat.setEditable(false);
            JScrollPane scroll = new JScrollPane(txtChat);
            JPanel bottom = new JPanel(new FlowLayout());
            bottom.add(txtInput);
            bottom.add(btnSend);
            bottom.add(btnImg);
            bottom.add(btnFile);
            add(scroll, BorderLayout.CENTER);
            add(bottom, BorderLayout.SOUTH);
            pack();
            setLocationRelativeTo(null);
            setDefaultCloseOperation(EXIT_ON_CLOSE);

            // Action listeners
            btnSend.addActionListener(e -> sendText());
            txtInput.addActionListener(e -> sendText());
            btnImg.addActionListener(e -> sendFile(true));
            btnFile.addActionListener(e -> sendFile(false));

            // Initialise TLS connection
            initTLS(ksPath, ksPwd, tsPath, tsPwd);
            // Start listener thread
            new Thread(this::listenLoop, "Listener-" + userId).start();
        }

        /** Initialise SSL socket – performs handshake and sends userId */
        private void initTLS(String ksPath, String ksPwd,
                             String tsPath, String tsPwd) throws Exception {
            SSLContext ctx = createSSLContext(ksPath, ksPwd, tsPath, tsPwd);
            SSLSocketFactory factory = ctx.getSocketFactory();
            socket = (SSLSocket) factory.createSocket(host, port);
            socket.startHandshake();
            in = new DataInputStream(socket.getInputStream());
            out = new DataOutputStream(socket.getOutputStream());

            // Send our identifier as first line (plain text – already inside TLS)
            out.writeBytes(userId + "\n");
            out.flush();
            appendChat("SYSTEM", "Connecting …");
        }

        /** Main inbound loop – parses frames and updates UI */
        private void listenLoop() {
            try {
                while (true) {
                    int len = in.readInt();
                    if (len <= 0) continue;
                    byte[] buf = new byte[len];
                    in.readFully(buf);
                    String cmd = new String(buf, 0, 3, "UTF-8");
                    byte[] payload = Arrays.copyOfRange(buf, 3, buf.length);

                    switch (cmd) {
                        case CMD_TEXT:
                            String txt = new String(payload, "UTF-8");
                            appendChat("客服", txt);
                            break;
                        case CMD_IMAGE:
                        case CMD_FILE:
                            // payload format: filename\n<binary data>
                            ByteArrayInputStream bis = new ByteArrayInputStream(payload);
                            BufferedReader br = new BufferedReader(
                                    new InputStreamReader(bis, "UTF-8"));
                            String fname = br.readLine();
                            // Here we simply save the file to a "downloads" folder
                            File outFile = new File("downloads/" + fname);
                            outFile.getParentFile().mkdirs();
                            try (FileOutputStream fos = new FileOutputStream(outFile)) {
                                // skip the filename+newline bytes
                                int header = (fname + "\n").getBytes("UTF-8").length;
                                fos.write(payload, header, payload.length - header);
                            }
                            appendChat("客服", "[" + cmd + "] saved as " + outFile.getPath());
                            break;
                        case CMD_LOG:
                            // Restore previous conversation
                            Files.write(logFile.toPath(), payload);
                            SwingUtilities.invokeLater(() -> txtChat.setText(
                                    new String(payload, StandardCharsets.UTF_8)));
                            break;
                        case CMD_CLOSE:
                            appendChat("SYSTEM", "Chat closed by server.");
                            socket.close();
                            return;
                        default:
                            appendChat("SYSTEM", "Unknown command: " + cmd);
                    }
                }
            } catch (Exception e) {
                appendChat("SYSTEM", "Connection lost: " + e.getMessage());
            }
        }

        private void sendText() {
            String txt = txtInput.getText().trim();
            if (txt.isEmpty()) return;
            try {
                byte[] payload = txt.getBytes("UTF-8");
                sendFrame(CMD_TEXT, payload);
                appendChat("我", txt);
                txtInput.setText("");
            } catch (IOException ex) {
                appendChat("SYSTEM", "Failed to send: " + ex.getMessage());
            }
        }

        /** Send either an image or a generic file */
        private void sendFile(boolean imageOnly) {
            JFileChooser chooser = new JFileChooser();
            chooser.setFileSelectionMode(JFileChooser.FILES_ONLY);
            if (imageOnly) {
                chooser.setFileFilter(new FileNameExtensionFilter(
                        "Image files", ImageIO.getReaderFileSuffixes()));
            }
            int ret = chooser.showOpenDialog(this);
            if (ret != JFileChooser.APPROVE_OPTION) return;
            File f = chooser.getSelectedFile();
            try {
                byte[] fileBytes = Files.readAllBytes(f.toPath());
                ByteArrayOutputStream bos = new ByteArrayOutputStream();
                bos.write((f.getName() + "\n").getBytes("UTF-8")); // name + newline
                bos.write(fileBytes);
                sendFrame(imageOnly ? CMD_IMAGE : CMD_FILE, bos.toByteArray());
                appendChat("我", "[" + (imageOnly ? "IMG" : "FIL") + "] " + f.getName());
            } catch (IOException ex) {
                appendChat("SYSTEM", "Failed to send file: " + ex.getMessage());
            }
        }

        /** Low‑level framed send */
        private synchronized void sendFrame(String cmd, byte[] payload) throws IOException {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            bos.write(cmd.getBytes("UTF-8"));
            bos.write(payload);
            byte[] frame = bos.toByteArray();
            out.writeInt(frame.length);
            out.write(frame);
            out.flush();
        }

        /** Append text to chat area and persist locally */
        private void appendChat(String speaker, String msg) {
            String line = String.format("[%s] %s: %s%n",
                    sdf.format(new Date()), speaker, msg);
            SwingUtilities.invokeLater(() -> txtChat.append(line));
            // Persist
            try {
                Files.write(logFile.toPath(),
                        line.getBytes("UTF-8"),
                        StandardOpenOption.CREATE,
                        StandardOpenOption.APPEND);
            } catch (IOException ignored) {}
        }
    }

    /* ----------------------------------------------------------------------
     *  MAIN – start either server or client depending on arguments
     * ---------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            System.out.println("Usage:");
            System.out.println("  java SSLChatSystem server <port> <keystore> <kspwd> <truststore> <tspwd>");
            System.out.println("  java SSLChatSystem client <userId> <host> <port> <keystore> <kspwd> <truststore> <tspwd>");
            return;
        }

        if ("server".equalsIgnoreCase(args[0])) {
            // Example: server 8443 ks.jks password ts.jks password
            int port = Integer.parseInt(args[1]);
            SSLChatServer server = new SSLChatServer(port,
                    args[2], args[3], args[4], args[5]);
            server.start();
        } else if ("client".equalsIgnoreCase(args[0])) {
            // Example: client john localhost 8443 ks.jks password ts.jks password
            String userId = args[1];
            String host = args[2];
            int port = Integer.parseInt(args[3]);
            SSLChatClient client = new SSLChatClient(
                    userId, host, port,
                    args[4], args[5], args[6], args[7]);
            client.setVisible(true);
        } else {
            System.out.println("Unknown mode: " + args[0]);
        }
    }
}

/* ---------------------------------------------------------------------------
 *  HOW TO CREATE KEYS/STORES FOR TESTING
 * ---------------------------------------------------------------------------
 *  1) Generate a self‑signed certificate for the server (and client, if you
 *     want mutual auth):
 *
 *     keytool -genkeypair -alias server -keyalg RSA -keystore keystore.jks \
 *             -keysize 2048 -validity 3650 -storepass password \
 *             -dname "CN=ChatServer, OU=Demo, O=MyCo, L=City, S=State, C=US"
 *
 *  2) Export the certificate and import it into a truststore that the client
 *     will use:
 *
 *     keytool -export -alias server -keystore keystore.jks -storepass password \
 *             -file server.cer
 *
 *     keytool -import -alias server -file server.cer -keystore truststore.jks \
 *             -storepass password -noprompt
 *
 *  3) (Optional) Repeat the same steps for a client keystore if you want
 *     the server to require client authentication (`setNeedClientAuth(true)`).
 *
 *  4) Run the server:
 *
 *     java SSLChatSystem server 8443 keystore.jks password truststore.jks password
 *
 *  5) Run a client:
 *
 *     java SSLChatSystem client alice localhost 8443 keystore.jks password truststore.jks password
 *
 *  The traffic between server and client is now encrypted with TLS,
 *  eliminating the original security warning about plain sockets.
 * --------------------------------------------------------------------------- */

下面给出一个 **基于 SSM（Spring + Spring‑MVC + MyBatis）** 的管理员登录的核心实现示例，重点示范：

* 通过 **`@PostMapping`（或 `@RequestMapping(method = RequestMethod.POST)`）** 明确指定 HTTP 方法，防止因未指定方法而导致的 CSRF 风险。  
* 使用 **Spring MVC 表单校验**、**Service 层业务逻辑** 以及 **MyBatis Mapper** 完成账号密码校验。  
* 登录成功后跳转至管理员主页面（`admin/home.jsp`），登录失败则返回登录页并显示错误信息。

```java
/* --------------------------------------------------------------
 * 1. 实体类：Admin（对应 admin 表，字段：id、username、password）
 * -------------------------------------------------------------- */
package com.example.ssm.model;

public class Admin {
    private Integer id;
    private String username;
    private String password;   // 为演示简化，实际生产请使用加盐哈希存储

    // ---- getter & setter -------------------------------------------------
    public Integer getId() {
        return id;
    }

    public void setId(Integer id) {
        this.id = id;
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public String getPassword() {
        return password;
    }

    public void setPassword(String password) {
        this.password = password;
    }
}

/* --------------------------------------------------------------
 * 2. MyBatis Mapper 接口：AdminMapper
 * -------------------------------------------------------------- */
package com.example.ssm.mapper;

import com.example.ssm.model.Admin;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;

public interface AdminMapper {

    /** 根据用户名查询管理员信息 */
    @Select("SELECT id, username, password FROM admin WHERE username = #{username}")
    Admin findByUsername(@Param("username") String username);
}

/* --------------------------------------------------------------
 * 3. Service 层：AdminService
 * -------------------------------------------------------------- */
package com.example.ssm.service;

import com.example.ssm.model.Admin;

public interface AdminService {
    /** 校验用户名、密码是否匹配，返回匹配的 Admin 对象或 null */
    Admin validate(String username, String rawPassword);
}

/* --------------------------------------------------------------
 * 4. Service 实现：AdminServiceImpl
 * -------------------------------------------------------------- */
package com.example.ssm.service.impl;

import com.example.ssm.mapper.AdminMapper;
import com.example.ssm.model.Admin;
import com.example.ssm.service.AdminService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.util.DigestUtils;   // 示例：MD5 加密（仅演示，生产请使用更安全算法）

@Service
public class AdminServiceImpl implements AdminService {

    @Autowired
    private AdminMapper adminMapper;

    @Override
    public Admin validate(String username, String rawPassword) {
        Admin admin = adminMapper.findByUsername(username);
        if (admin == null) {
            return null;
        }
        // 假设数据库中存的是 MD5(密码+salt)，这里演示简单的 MD5
        String salt = "SOME_STATIC_SALT"; // 实际请为每个用户单独生成盐
        String hashed = DigestUtils.md5DigestAsHex((rawPassword + salt).getBytes());
        if (hashed.equals(admin.getPassword())) {
            return admin;
        }
        return null;
    }
}

/* --------------------------------------------------------------
 * 5. Spring MVC 控制器：AdminController
 *    - 登录页面 GET：/admin/login
 *    - 登录提交 POST：/admin/login (明确使用 POST，防止 CSRF 漏洞)
 * -------------------------------------------------------------- */
package com.example.ssm.controller;

import com.example.ssm.model.Admin;
import com.example.ssm.service.AdminService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult; 
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import javax.validation.constraints.NotBlank;
import javax.validation.Valid;

@Controller
@RequestMapping("/admin")
public class AdminController {

    @Autowired
    private AdminService adminService;

    /** 登录页面 */
    @GetMapping("/login")
    public String showLoginForm(Model model) {
        model.addAttribute("loginForm", new LoginForm());
        return "admin/login";   // 对应 /WEB-INF/views/admin/login.jsp
    }

    /** 处理登录请求，必须使用 POST 方法 */
    @PostMapping(value = "/login")   // 等价于 @RequestMapping(value="/login", method=RequestMethod.POST)
    public String processLogin(@Valid LoginForm loginForm,
                               BindingResult bindingResult,
                               Model model) {
        if (bindingResult.hasErrors()) {
            return "admin/login";
        }

        Admin admin = adminService.validate(loginForm.getUsername(), loginForm.getPassword());
        if (admin == null) {
            model.addAttribute("errorMsg", "用户名或密码错误");
            return "admin/login";
        }

        // 登录成功后，可把 admin 放入 session（或使用 Spring Security）
        model.addAttribute("admin", admin);
        // 这里使用 Spring MVC 的 redirect，避免表单重复提交
        return "redirect:/admin/home";
    }

    /** 管理员主页面 */
    @GetMapping("/home")
    public String adminHome() {
        return "admin/home";   // 对应 /WEB-INF/views/admin/home.jsp
    }

    /** 简单的登录表单 DTO（使用 JSR‑303 校验） */
    public static class LoginForm {
        @NotBlank(message = "用户名不能为空")
        private String username;
        @NotBlank(message = "密码不能为空")
        private String password;

        // getters & setters
        public String getUsername() {
            return username;
        }
        public void setUsername(String username) {
            this.username = username;
        }
        public String getPassword() {
            return password;
        }
        public void setPassword(String password) {
            this.password = password;
        }
    }
}

/* --------------------------------------------------------------
 * 6. Spring MVC 配置（开启基于 Spring Security 的 CSRF 防护）（可选）
 * -------------------------------------------------------------- */
// 如果项目已经引入 Spring Security，可在 SecurityConfig 中保留默认的 CSRF 开启；
// 若不使用 Spring Security，仍然可以自行在过滤器中校验 token，下面示例为最简化的开启方式
