    public void addViewControllers(ViewControllerRegistry registry) {
        registry.addViewController("/admin/login").setViewName("admin/login");
        registry.addViewController("/admin/home").setViewName("admin/home");
    }
}
*/

/* --------------------------------------------------------------
 * 7. JSP 页面（示例）——/WEB-INF/views/admin/login.jsp
 * --------------------------------------------------------------
<%@ taglib prefix="c" uri="http://java.sun.com/jsp/jstl/core"%>
<%@ taglib prefix="form" uri="http://www.springframework.org/tags/form"%>
<html>
<head><title>管理员登录</title></head>
<body>
<h2>管理员登录</h2>
<c:if test="${not empty errorMsg}">
    <div style="color:red">${errorMsg}</div>
</c:if>
<form:form modelAttribute="loginForm" method="post" action="${pageContext.request.contextPath}/admin/login">
    <table>
        <tr>
            <td>用户名：</td>
            <td><form:input path="username"/></td>
            <td><form:errors path="username" cssClass="error"/></td>
        </tr>
        <tr>
            <td>密码：</td>
            <td><form:password path="password"/></td>
            <td><form:errors path="password" cssClass="error"/></td>
        </tr>
        <tr>
            <td colspan="2"><input type="submit" value="登录"/></td>
        </tr>
    </table>
</form:form>
</body>
</html>
 */

/* --------------------------------------------------------------
 * 8. 说明
 * --------------------------------------------------------------
 * 1. **关键点**：`@PostMapping("/login")` 明确限定只能使用 POST 方法，从而避免
 *    “未指定 HTTP 方法的 @RequestMapping” 带来的全部方法开放风险，符合
 *    题目所提示的 CSRF 防护要求。
 *
 * 2. 若项目已集成 Spring Security，框架会默认对所有非 GET/HEAD/TRACE/OPTIONS
 *    请求校验 CSRF Token，登录 POST 亦会受保护；如果未使用 Spring Security，
 *    建议自行在登录页面加入一次性 token 并在后端校验（此处为简化示例，未演示）。
 *
 * 3. 密码存储请使用 **加盐+强哈希算法（如 bcrypt、PBKDF2、Argon2）**，示例中
 *    使用 MD5 仅为演示。
 *
 * 4. 登录成功后可以把 `admin` 对象放入 HttpSession，或者直接交给 Spring
 *    Security 完成后续的授权管理。
 * --------------------------------------------------------------
 */

**Solution – Enable TLS 1.2 (or higher) on a Netty `ChannelPipeline`**

Below is a complete, self‑contained example that shows how to:

1. **Create a JDK `SSLContext` that only uses TLS 1.2** (or newer).  
2. **Wrap that `SSLContext` in a Netty `SslContext`** (`JdkSslContext`).  
3. **Add the Netty SSL handler to the pipeline** so every I/O operation is encrypted with the strong protocol.  

The same approach works for both **client** and **server** side channels – just change the `forClient()` / `forServer()` builder or the `JdkSslContext` construction accordingly.

```java
// ---------------------------------------------------------------
// Netty TLS‑1.2 (or newer) pipeline setup – single code block
// ---------------------------------------------------------------
import io.netty.bootstrap.Bootstrap;
import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;
import io.netty.handler.ssl.*;
import io.netty.handler.codec.string.StringDecoder;
import io.netty.handler.codec.string.StringEncoder;

import javax.net.ssl.*;
import java.io.FileInputStream;
import java.security.KeyStore;

/**
 * Utility to build a TLS‑1.2‑only {@link SSLContext}.
 */
class Tls12SslContextFactory {

    /**
     * Creates a JDK SSLContext that only enables TLSv1.2 (or higher, if supported).
     *
     * @param keyStorePath   optional path to a keystore (for server side). Null for client.
     * @param keyStorePwd    password for the keystore (null if no keystore).
     * @param trustStorePath optional path to a truststore. Null to use the default trust manager.
     * @param trustStorePwd  password for the truststore (null if default).
     * @return configured SSLContext limited to TLSv1.2+
     * @throws Exception on any SSL or keystore error
     */
    static SSLContext createSslContext(String keyStorePath,
                                       String keyStorePwd,
                                       String trustStorePath,
                                       String trustStorePwd) throws Exception {

        // -----------------------------------------------------------------
        // 1️⃣  Initialise KeyManager (required for a server, optional for a client)
        // -----------------------------------------------------------------
        KeyManager[] keyManagers = null;
        if (keyStorePath != null) {
            KeyStore ks = KeyStore.getInstance("JKS");
            try (FileInputStream kis = new FileInputStream(keyStorePath)) {
                ks.load(kis, keyStorePwd != null ? keyStorePwd.toCharArray() : null);
            }
            KeyManagerFactory kmf = KeyManagerFactory.getInstance(
                    KeyManagerFactory.getDefaultAlgorithm());
            kmf.init(ks, keyStorePwd != null ? keyStorePwd.toCharArray() : null);
            keyManagers = kmf.getKeyManagers();
        }

        // -----------------------------------------------------------------
        // 2️⃣  Initialise TrustManager (use custom truststore or default JVM one)
        // -----------------------------------------------------------------
        TrustManager[] trustManagers = null;
        if (trustStorePath != null) {
            KeyStore ts = KeyStore.getInstance("JKS");
            try (FileInputStream tis = new FileInputStream(trustStorePath)) {
                ts.load(tis, trustStorePwd != null ? trustStorePwd.toCharArray() : null);
            }
            TrustManagerFactory tmf = TrustManagerFactory.getInstance(
                    TrustManagerFactory.getDefaultAlgorithm());
            tmf.init(ts);
            trustManagers = tmf.getTrustManagers();
        } // else leave trustManagers null → default system trust manager

        // -----------------------------------------------------------------
        // 3️⃣  Build the JDK SSLContext restricted to TLSv1.2+
        // -----------------------------------------------------------------
        SSLContext sslCtx = SSLContext.getInstance("TLSv1.2"); // ← forces TLS 1.2
        sslCtx.init(keyManagers, trustManagers, null);
        return sslCtx;
    }

    /**
     * Creates a Netty {@link SslContext} from the JDK {@link SSLContext}.
     *
     * @param sslCtx the JDK SSLContext (TLSv1.2‑only)
     * @param clientMode true if this context is used on a client side
     * @return Netty SslContext ready to be added to a pipeline
     */
    static SslContext wrapIntoNettySslContext(SSLContext sslCtx,
                                              boolean clientMode) {
        // JdkSslContext respects the protocols already enabled on the underlying
        // SSLContext, so we do NOT have to pass an explicit protocol list again.
        return new JdkSslContext(
                sslCtx,
                true,                     // encrypt/decrypt both inbound/outbound
                clientMode ? ClientAuth.NONE : ClientAuth.REQUIRE,
                null,                     // cipher suites – let JDK pick a safe default
                null,                     // application protocol – NPN/ALPN disabled here
                false,                    // enable session cache – false = use JDK defaults
                false                     // start TLS – not needed for pure SSL/TLS
        );
    }
}

/**
 * Example Netty **Server** that forces TLS 1.2.
 */
class NettyTls12Server {

    private final int port;
    private final SslContext sslCtx;

    NettyTls12Server(int port, SslContext sslCtx) {
        this.port = port;
        this.sslCtx = sslCtx;
    }

    void start() throws InterruptedException {
        EventLoopGroup bossGroup = new NioEventLoopGroup(1);
        EventLoopGroup workerGroup = new NioEventLoopGroup();
        try {
            ServerBootstrap b = new ServerBootstrap()
                    .group(bossGroup, workerGroup)
                    .channel(NioServerSocketChannel.class)
                    .childHandler(new ChannelInitializer<SocketChannel>() {
                        @Override
                        protected void initChannel(SocketChannel ch) {
                            ChannelPipeline p = ch.pipeline();
                            // 1️⃣ Add Netty SSL handler (TLS 1.2)
                            p.addLast(sslCtx.newHandler(ch.alloc()));
                            // 2️⃣ Add any other handlers you need (example: String codec)
                            p.addLast(new StringDecoder());
                            p.addLast(new StringEncoder());
                            p.addLast(new SimpleChannelInboundHandler<String>() {
                                @Override
                                protected void channelRead0(ChannelHandlerContext ctx, String msg) {
                                    System.out.println("Server received: " + msg);
                                    ctx.writeAndFlush("Echo: " + msg);
                                }
                            });
                        }
                    });

            ChannelFuture f = b.bind(port).sync();
            System.out.println("TLS‑1.2 server started on port " + port);
            f.channel().closeFuture().sync();
        } finally {
            bossGroup.shutdownGracefully();
            workerGroup.shutdownGracefully();
        }
    }
}

/**
 * Example Netty **Client** that forces TLS 1.2.
 */
class NettyTls12Client {

    private final String host;
    private final int port;
    private final SslContext sslCtx;

    NettyTls12Client(String host, int port, SslContext sslCtx) {
        this.host = host;
        this.port = port;
        this.sslCtx = sslCtx;
    }

    void start() throws InterruptedException {
        EventLoopGroup group = new NioEventLoopGroup();
        try {
            Bootstrap b = new Bootstrap()
                    .group(group)
                    .channel(NioSocketChannel.class)
                    .handler(new ChannelInitializer<SocketChannel>() {
                        @Override
                        protected void initChannel(SocketChannel ch) {
                            ChannelPipeline p = ch.pipeline();
                            // 1️⃣ Add Netty SSL handler (TLS 1.2) – client mode
                            p.addLast(sslCtx.newHandler(ch.alloc(), host, port));
                            // 2️⃣ Add codec & business logic
                            p.addLast(new StringDecoder());
                            p.addLast(new StringEncoder());
                            p.addLast(new SimpleChannelInboundHandler<String>() {
                                @Override
                                public void channelActive(ChannelHandlerContext ctx) {
                                    ctx.writeAndFlush("Hello‑TLS‑1.2 Server!");
                                }

                                @Override
                                protected void channelRead0(ChannelHandlerContext ctx, String msg) {
                                    System.out.println("Client received: " + msg);
                                    ctx.close(); // close after first response (demo purpose)
                                }
                            });
                        }
                    });

            ChannelFuture f = b.connect(host, port).sync();
            f.channel().closeFuture().sync();
        } finally {
            group.shutdownGracefully();
        }
    }
}

/**
 * Main entry – builds TLS 1.2 SSLContexts for both server and client,
 * then starts the server and a client that talks to it.
 *
 * NOTE:
 * • Adjust keystore/truststore paths and passwords to match your environment.
 * • For a pure client‑only scenario you can call
 *   `Tls12SslContextFactory.createSslContext(null, null, trustStorePath, trustStorePwd)`
 *   – the returned SSLContext will have no KeyManager.
 */
public class NettyTls12Demo {

    public static void main(String[] args) throws Exception {
        // --------------------------------------------------------------
        // 1️⃣  Build a TLS‑1.2‑only JDK SSLContext for SERVER side
        // --------------------------------------------------------------
        // Replace these with your actual keystore containing the server cert/key.
        String serverKeyStore   = "server_keystore.jks";
        String serverKeyStorePw = "changeit";

        // Optional: custom truststore – for demo we reuse the same keystore.
        String serverTrustStore   = "server_keystore.jks";
        String serverTrustStorePw = "changeit";

        SSLContext serverJdkSsl = Tls12SslContextFactory.createSslContext(
                serverKeyStore, serverKeyStorePw,
                serverTrustStore, serverTrustStorePw);

        SslContext serverNettySsl = Tls12SslContextFactory.wrapIntoNettySslContext(
                serverJdkSsl, false); // false → server mode

        // --------------------------------------------------------------
        // 2️⃣  Build a TLS‑1.2‑only JDK SSLContext for CLIENT side
        // --------------------------------------------------------------
        // For client we normally only need a truststore (to verify server cert).
        String clientTrustStore   = "client_truststore.jks";
        String clientTrustStorePw = "changeit";

        SSLContext clientJdkSsl = Tls12SslContextFactory.createSslContext(
                null, null,               // no keystore for client auth
                clientTrustStore, clientTrustStorePw);

        SslContext clientNettySsl = Tls12SslContextFactory.wrapIntoNettySslContext(
                clientJdkSsl, true); // true → client mode

        // --------------------------------------------------------------
        // 3️⃣  Start server (in background) and then a client
        // --------------------------------------------------------------
        int port = 8443;
        Thread serverThread = new Thread(() -> {
            try {
                new NettyTls12Server(port, serverNettySsl).start();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        serverThread.start();

        // Give the server a moment to bind
        Thread.sleep(1000);

        // Run the client
        new NettyTls12Client("localhost", port, clientNettySsl).start();

        // Shut down server thread (for demo purpose)
        serverThread.interrupt();
    }
}

/*
 * ---------------------------------------------------------------------------
 * What this code solves
 * ---------------------------------------------------------------------------
 * • The JDK `SSLContext` is instantiated with `TLSv1.2` → no TLS 1.0/1.1
 *   or older SSL protocols are ever enabled.
 * • Netty’s `JdkSslContext` simply forwards the underlying JDK settings,
 *   so the pipeline’s `SslHandler` will only negotiate TLS 1.2 (or higher if
 *   the JDK supports it).
 * • All traffic that passes through the pipeline after `sslCtx.newHandler(...)`
 *   is guaranteed to be encrypted with the strong protocol.
 *
 * ---------------------------------------------------------------------------
 * How to adapt
 * ---------------------------------------------------------------------------
 * • To support TLS 1.3 as well, just request `SSLContext.getInstance("TLS")`
 *   and then set `sslCtx = SslContextBuilder.forServer(...).protocols("TLSv1.2","TLSv1.3")`
 *   (or keep the JDK default which already enables TLS 1.3 on modern JDKs).
 * • If you prefer Netty’s native OpenSSL provider (better performance), replace
 *   `JdkSslContext` with `SslContextBuilder.forServer(...).sslProvider(SslProvider.OPENSSL).protocols("TLSv1.2")`.
 *
 * The core idea stays the same: **never create an SSLContext with the default**
 * `"TLS"` that may fall back to weak versions; explicitly request TLS 1.2+ and
 * make Netty use that context in the pipeline. */

**Solution – Encrypted Calculator with SSL sockets**  
Below is a complete, self‑contained example that replaces plain `Socket`/`ServerSocket` with `SSLSocket`/`SSLServerSocket`.  
It contains three classes:

1. **`Calculatrice`** – static methods that perform the arithmetic.  
2. **`Serveur`** – SSL server that listens for client requests, uses `Calculatrice` and returns the result.  
3. **`CalculatorClient`** – SSL client that connects to the server, sends an operation and prints the answer.

> **⚠️ Important:**  
> The code works with a **self‑signed keystore** (`serverkeystore.jks`) and a **truststore** (`clienttruststore.jks`).  
> Before running the program, generate them with `keytool` (see the comments in the code).  

```java
/* ---------- 1. Calculatrice.java ---------- */
public class Calculatrice {
    public static double add(double a, double b)    { return a + b; }
    public static double sub(double a, double b)    { return a - b; }
    public static double mul(double a, double b)    { return a * b; }
    public static double div(double a, double b) {
        if (b == 0) throw new IllegalArgumentException("Division by zero");
        return a / b;
    }
}

/* ---------- 2. Serveur.java ---------- */
import javax.net.ssl.*;
import java.io.*;
import java.security.KeyStore;

public class Serveur {
    private static final int PORT = 12345;
    // Keystore file created with:
    // keytool -genkeypair -alias server -keyalg RSA -keystore serverkeystore.jks -storepass password -validity 365
    private static final String KEYSTORE = "serverkeystore.jks";
    private static final String KEYSTORE_PASSWORD = "password";

    public static void main(String[] args) throws Exception {
        // Load the server keystore
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream(KEYSTORE), KEYSTORE_PASSWORD.toCharArray());

        // Initialise KeyManagerFactory with the keystore
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        kmf.init(ks, KEYSTORE_PASSWORD.toCharArray());

        // Initialise SSLContext
        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(kmf.getKeyManagers(), null, null);

        // Create SSLServerSocket
        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        try (SSLServerSocket serverSocket = (SSLServerSocket) ssf.createServerSocket(PORT)) {
            System.out.println("Serveur SSL démarré sur le port " + PORT);
            while (true) {
                try (SSLSocket socket = (SSLSocket) serverSocket.accept()) {
                    handleClient(socket);
                } catch (Exception e) {
                    System.err.println("Erreur lors du traitement du client : " + e.getMessage());
                }
            }
        }
    }

    private static void handleClient(SSLSocket socket) throws IOException {
        BufferedReader in  = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        BufferedWriter out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));

        String request = in.readLine();               // e.g. "add 3 5"
        if (request == null) return;

        String[] parts = request.trim().split("\\s+");
        if (parts.length != 3) {
            out.write("ERROR Invalid request format\n");
            out.flush();
            return;
        }

        double a = Double.parseDouble(parts[1]);
        double b = Double.parseDouble(parts[2]);
        double result;

        try {
            switch (parts[0].toLowerCase()) {
                case "add": result = Calculatrice.add(a, b); break;
                case "sub": result = Calculatrice.sub(a, b); break;
                case "mul": result = Calculatrice.mul(a, b); break;
                case "div": result = Calculatrice.div(a, b); break;
                default:
                    out.write("ERROR Unknown operation\n");
                    out.flush();
                    return;
            }
            out.write("RESULT " + result + "\n");
        } catch (IllegalArgumentException ex) {
            out.write("ERROR " + ex.getMessage() + "\n");
        }
        out.flush();
    }
}

/* ---------- 3. CalculatorClient.java ---------- */
import javax.net.ssl.*;
import java.io.*;
import java.security.KeyStore;

public class CalculatorClient {
    private static final String HOST = "localhost";
    private static final int PORT = 12345;

    // Truststore containing the server certificate (exported from serverkeystore.jks)
    // keytool -exportcert -alias server -keystore serverkeystore.jks -file server.cer
    // keytool -importcert -alias server -file server.cer -keystore clienttruststore.jks -storepass password
    private static final String TRUSTSTORE = "clienttruststore.jks";
    private static final String TRUSTSTORE_PASSWORD = "password";

    public static void main(String[] args) throws Exception {
        if (args.length != 3) {
            System.out.println("Usage: java CalculatorClient <operation> <a> <b>");
            System.out.println("Operations: add sub mul div");
            return;
        }
        String operation = args[0];
        String a = args[1];
        String b = args[2];

        // Load truststore
        KeyStore ts = KeyStore.getInstance("JKS");
        ts.load(new FileInputStream(TRUSTSTORE), TRUSTSTORE_PASSWORD.toCharArray());

        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(ts);

        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(null, tmf.getTrustManagers(), null);

        SSLSocketFactory ssf = ctx.getSocketFactory();
        try (SSLSocket socket = (SSLSocket) ssf.createSocket(HOST, PORT)) {
            socket.startHandshake(); // mandatory to trigger verification

            BufferedWriter out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));
            BufferedReader  in  = new BufferedReader(new InputStreamReader(socket.getInputStream()));

            // Send request
            out.write(operation + " " + a + " " + b + "\n");
            out.flush();

            // Receive response
            String response = in.readLine();
            System.out.println("Server answer: " + response);
        }
    }
}

/* -------------------------------------------------------------
   How to compile & run (Linux / macOS / Windows command line):
   -------------------------------------------------------------
   1. Generate keystore & truststore (run once):
      -------------------------------------------------
      # Server keystore (self‑signed)
      keytool -genkeypair -alias server -keyalg RSA -keystore serverkeystore.jks \
              -storepass password -keypass password -validity 365 \
              -dname "CN=CalculatorServer, OU=Demo, O=Example, L=Paris, S=Paris, C=FR"

      # Export server certificate
      keytool -exportcert -alias server -keystore serverkeystore.jks \
              -storepass password -file server.cer

      # Client truststore (trust the server cert)
      keytool -importcert -alias server -file server.cer \
              -keystore clienttruststore.jks -storepass password -noprompt
      -------------------------------------------------

   2. Compile the three classes:
      javac Calculatrice.java Serveur.java CalculatorClient.java

   3. Run the server (keep it running):
      java Serveur

   4. In another terminal, run the client:
      java CalculatorClient add 12 7
      java CalculatorClient div 10 0    # will show an error

   -------------------------------------------------------------
   The communication between client and server is now encrypted
   with TLS, eliminating the plain‑socket security issue.
   ------------------------------------------------------------- */

