```javascript
/* -----------------------------------------------------------
   src/config.js               (unchanged – keep your ENDPOINT)
   ----------------------------------------------------------- */
export const ENDPOINT = "https://my‑api.example.com";

/* -----------------------------------------------------------
   src/services/Utils.js
   ----------------------------------------------------------- */
import DOMPurify from "dompurify";

export default {
  // -----------------------------------------------------------------
  // Parse a URL and break it into resource, id and verb
  // -----------------------------------------------------------------
  parseRequestURL: () => {
    const url = location.hash.slice(1).toLowerCase() || "/";
    const r = url.split("/");
    return {
      resource: r[1] || null,
      id: r[2] || null,
      verb: r[3] || null,
    };
  },

  // -----------------------------------------------------------------
  // Simple sleep implementation
  // -----------------------------------------------------------------
  sleep: (ms) => new Promise((res) => setTimeout(res, ms)),

  // -----------------------------------------------------------------
  // Escape HTML entities (used when we build a string manually)
  // -----------------------------------------------------------------
  escapeHTML: (str) => {
    if (typeof str !== "string") return "";
    return str
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  },

  // -----------------------------------------------------------------
  // Sanitise a full HTML string with DOMPurify (fallback safety)
  // -----------------------------------------------------------------
  sanitizeHTML: (dirty) => DOMPurify.sanitize(dirty),
};

/* -----------------------------------------------------------
