import Utils from "../services/Utils.js";

export default class SearchBar {
  constructor(container) {
    this.container = container; // DOM element where the bar lives
    this.debounceTimer = null;
    this.render();
  }

  render() {
    const html = `
      <input type="search" id="global-search" placeholder="Rechercher…" autocomplete="off"
             class="form-control" />
      <ul id="search-submenu" class="search-submenu list-group position-absolute w-100"></ul>
    `;
    this.container.innerHTML = html;
    this.input = this.container.querySelector("#global-search");
    this.submenu = this.container.querySelector("#search-submenu");

    this.input.addEventListener("input", (e) => this.onInput(e));
    this.input.addEventListener("focus", () => this.submenu.style.display = "block");
    this.input.addEventListener("blur", () => setTimeout(() => this.submenu.style.display = "none", 150));
  }

  onInput(e) {
    const term = e.target.value.trim();
    clearTimeout(this.debounceTimer);
    if (!term) {
      this.submenu.innerHTML = "";
      return;
    }

    this.debounceTimer = setTimeout(() => {
      // update URL – the router will pick up the new hash
      location.hash = `#/search?term=${encodeURIComponent(term)}`;
    }, 300);
  }
}

/* -----------------------------------------------------------
   src/views/pages/SearchResults.js
   ----------------------------------------------------------- */
import Utils from "../../services/Utils.js";
import PersonnagesProvider from "../../services/PersonnagesProvider.js";
import ArmesProvider from "../../services/ArmesProvider.js";
import ArmuresProvider from "../../services/ArmuresProvider.js";
import ObjetsProvider from "../../services/ObjetsProvider.js";

export default class SearchResults {
  // receives the raw query string (e.g. "?term=épée")
  constructor(queryString) {
    const params = new URLSearchParams(queryString);
    this.term = params.get("term")?.toLowerCase() ?? "";
  }

  async render() {
    if (!this.term) return `<p class="p-3">Commencez à taper pour rechercher…</p>`;

    // parallel fetches (you could add caching if needed)
    const [pers, armes, armures, objets] = await Promise.all([
      PersonnagesProvider.FetchPersonnages(),
      ArmesProvider.fetchArmes(),
      ArmuresProvider.fetchArmures(),
      ObjetsProvider.fetchObjets(),
    ]);

    const filter = (arr, key = "nom") =>
      arr.filter((it) => it[key].toLowerCase().includes(this.term)).slice(0, 5);

    const results = [
      ...filter(pers).map((p) => ({
        type: "personnage",
        id: p.id,
        label: `${p.nom} (Personnage)`,
      })),
      ...filter(armes).map((a) => ({
        type: "arme",
        id: a.id,
        label: `${a.nom} (Arme)`,
      })),
      ...filter(armures).map((a) => ({
        type: "armure",
        id: a.id,
        label: `${a.nom} (Armure)`,
      })),
      ...filter(objets).map((o) => ({
        type: "objet",
        id: o.id,
        label: `${o.nom} (Objet)`,
      })),
    ];

    if (results.length === 0) {
      return `<p class="p-3">Aucun résultat pour “${Utils.escapeHTML(this.term)}”.</p>`;
    }

    const listItems = results
      .map(
        (r) => `
        <li class="list-group-item list-group-item-action"
            onclick="location.hash='#/${r.type}/${r.id}'">
            ${Utils.escapeHTML(r.label)}
        </li>`
      )
      .join("");

    return `
      <ul class="list-group m-2">
        ${listItems}
      </ul>`;
  }
}

