import Home from "./views/pages/Home.js";
import Error404 from "./views/pages/Error404.js";
import Personnage from "./views/pages/Personnage.js";
import Search from "./views/pages/Search.js";
import Utils from "./services/Utils.js";

const routes = {
  "/": Home,
  "/personnage/:id": Personnage,
  "/search": Search,
  // you could also add /armes, /armures … similar to Home
};

const router = async () => {
  const outlet = document.querySelector("#content");
  const request = Utils.parseRequestURL();

  // build the route pattern (e.g. "/personnage/:id")
  const parsedURL =
    (request.resource ? `/${request.resource}` : "/") +
    (request.id ? "/:id" : "") +
    (request.verb ? `/${request.verb}` : "");

  const PageClass = routes[parsedURL] || Error404;
  const page = new PageClass(request.id ? `?id=${request.id}` : "");

  // render returns a string (HTML).  Sanitize it before injection.
  const rawHtml = await page.render();
  outlet.innerHTML = Utils.sanitizeHTML(rawHtml);
};

/* -----------------------------------------------------------------
   Initialise the app (index.js or equivalent)
   ----------------------------------------------------------------- */
