response:
**Solution – Enable HSTS globally (and explain the routing)**  

```csharp
// ---------------------------------------------------------------
// Program.cs (or Startup.cs for older ASP.NET Core versions)
// ---------------------------------------------------------------
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.Hosting;

var builder = WebApplication.CreateBuilder(args);

// Add services (controllers, auth, etc.)
builder.Services.AddControllers();
builder.Services.AddAuthentication();          // your auth services
builder.Services.AddScoped<IAuthService, AuthService>();

var app = builder.Build();

// -----------------------------------------------------------------
// 1️⃣  Enforce HTTPS & HSTS (the missing security header)
// -----------------------------------------------------------------
if (!app.Environment.IsDevelopment())
{
    // Sends the Strict‑Transport‑Security header on every response:
    //    Strict-Transport-Security: max‑age=31536000; includeSubDomains; preload
    // (max‑age = 1 year, you can adjust as needed)
    app.UseHsts(options => 
        options.MaxAge(days: 365)
               .IncludeSubDomains()
               .Preload());

    // Redirect any HTTP request to HTTPS before HSTS can be applied.
    app.UseHttpsRedirection();
}

// -----------------------------------------------------------------
// 2️⃣  Configure the request pipeline (routing, auth, etc.)
// -----------------------------------------------------------------
app.UseRouting();

app.UseAuthentication();   // if you use JWT / cookies
app.UseAuthorization();

app.MapControllers();      // Controllers use attribute routing

app.Run();


// ---------------------------------------------------------------
// Example Controller – how the endpoint is resolved
// ---------------------------------------------------------------
using Microsoft.AspNetCore.Mvc;

[ApiController]                                 // Enables attribute routing
[Route("api/[controller]")]                     // Base route = /api/Auth
public class AuthController : ControllerBase
{
    private readonly IAuthService _authService;

    public AuthController(IAuthService authService) =>
        _authService = authService;

    // -----------------------------------------------------------
    //  POST  /api/Auth/login   ← the URL that triggers this method
    // -----------------------------------------------------------
    [HttpPost("login")]                         // HTTP verb + route segment
    public IActionResult Login([FromBody] UserLoginDto loginDto)
    {
        var user = _authService.Login(loginDto);
        if (user != null)
        {
            var token = _authService.CreateAccessToken(user);

            // Store tokens in secure, HttpOnly cookies
            AddToCookie("X-Access-Token", token.Token, token.Expiration, true);
            AddToCookie("X-Refresh-Token", token.RefreshToken,
                        DateTime.UtcNow.AddDays(7), true);

            return Ok(token);
        }

        return BadRequest();
    }

    // Helper to add a cookie with best‑practice flags
    private void AddToCookie(string key, string value, DateTime expires, bool httpOnly)
    {
        var options = new CookieOptions
        {
            Expires = expires,
            HttpOnly = httpOnly,          // prevents client‑side script access
            Secure = true,                // cookie only sent over HTTPS
            SameSite = SameSiteMode.Strict
        };
        Response.Cookies.Append(key, value, options);
    }
}

/*
Explanation:

* **How the controller knows which endpoint to hit**

  - `[ApiController]` + `[Route("api/[controller]")]` defines a base route.
    `[controller]` is replaced with the class name without the “Controller”
    suffix (`Auth` → `/api/Auth`).
  - `[HttpPost("login")]` adds the HTTP verb *POST* and the relative path
    *login*. Combining both gives the final endpoint: **POST /api/Auth/login**.

* **What the added code does**

  - `app.UseHsts()` injects the `Strict-Transport-Security` header on every
    response, forcing browsers to always use HTTPS for the domain.
  - `app.UseHttpsRedirection()` ensures any plain‑HTTP request is automatically
    upgraded to HTTPS before the response is sent.
  - The cookie helper marks cookies as `Secure`, `HttpOnly`, and `SameSite=Strict`,
    further hardening the authentication flow.

Deploy this configuration and the missing HSTS header issue will be resolved. */

下面给出一个 **ASP.NET Core 6+（最小化托管模型）** 的完整示例，演示安全的登录流程以及对所有会改变状态的 MVC 方法（如 `Index`）进行 **CSRF 防护、严格的 Content‑Type 检查**，并通过 **授权策略/角色** 实现最小权限原则。所有代码放在同一个代码块中，复制后即可直接 `dotnet run` 运行。

```csharp
// ---------------------------------------------------------------
// Program.cs (ASP.NET Core 6+ Minimal Hosting)
// ---------------------------------------------------------------
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Net.Http.Headers;

var builder = WebApplication.CreateBuilder(args);

// 1️⃣ 注册认证（Cookie）和授权
builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme)
    .AddCookie(options =>
    {
        options.LoginPath = "/Account/Login";
        options.AccessDeniedPath = "/Account/AccessDenied";
        options.Cookie.HttpOnly = true;
        options.Cookie.SameSite = SameSiteMode.Strict;
        options.Cookie.SecurePolicy = CookieSecurePolicy.Always;
    });

builder.Services.AddAuthorization(options =>
{
    // 示例：仅 “Admin” 角色可以访问 Index
    options.AddPolicy("AdminOnly", policy => policy.RequireRole("Admin"));
});

// 2️⃣ 添加 Antiforgery（默认使用 Cookie+Form token）
builder.Services.AddAntiforgery(opts =>
{
    opts.HeaderName = "X-XSRF-TOKEN"; // 前端 Ajax 可通过此 Header 发送 token
});

// 3️⃣ 添加 MVC 并全局启用自动 CSRF 验证（对所有不标记 [IgnoreAntiforgeryToken] 的 POST/PUT/DELETE 生效）
builder.Services.AddControllersWithViews(options =>
{
    options.Filters.Add(new AutoValidateAntiforgeryTokenAttribute());
});

var app = builder.Build();

// 4️⃣ 中间件管线
if (!app.Environment.IsDevelopment())
{
    app.UseExceptionHandler("/Home/Error");
    app.UseHsts();
}
app.UseHttpsRedirection();
app.UseStaticFiles();

app.UseRouting();

// 认证 → 授权
app.UseAuthentication();
app.UseAuthorization();

app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Home}/{action=Index}/{id?}");

app.Run();

// ---------------------------------------------------------------
// Controllers/AccountController.cs
// ---------------------------------------------------------------
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System.Security.Claims;

[AllowAnonymous] // 只允许匿名访问登录页面
public class AccountController : Controller
{
    // GET: /Account/Login
    [HttpGet]
    public IActionResult Login(string? returnUrl = null)
    {
        ViewData["ReturnUrl"] = returnUrl;
        return View(); // 返回一个简单的表单视图
    }

    // POST: /Account/Login
    // ① 强制 Content-Type 为表单 urlencoded（防止 JSON 绕过 CORS 预检）
    // ② 自动验证 Antiforgery token（AutoValidateAntiforgeryToken 全局已开启）
    // ③ 登录成功后签发 Cookie，使用 Claim 存储用户名和角色
    [HttpPost]
    [Consumes("application/x-www-form-urlencoded")] // 严格 Content-Type 检查
    [ValidateAntiForgeryToken] // 冗余写法，确保即使全局失效也会检查
    public async Task<IActionResult> Login(string username, string password, string? returnUrl = null)
    {
        // ---------- 这里放置真实的用户校验逻辑 ----------
        // 为演示仅使用硬编码用户，实际请查询数据库或调用 IdentityServer
        if (username == "admin" && password == "P@ssw0rd")
        {
            var claims = new List<Claim>
            {
                new Claim(ClaimTypes.Name, username),
                new Claim(ClaimTypes.Role, "Admin") // 角色用于后续授权
            };
            var claimsIdentity = new ClaimsIdentity(claims, CookieAuthenticationDefaults.AuthenticationScheme);
            var authProperties = new AuthenticationProperties
            {
                IsPersistent = true, // 持久化 Cookie
                ExpiresUtc = DateTimeOffset.UtcNow.AddHours(8)
            };

            await HttpContext.SignInAsync(
                CookieAuthenticationDefaults.AuthenticationScheme,
                new ClaimsPrincipal(claimsIdentity),
                authProperties);

            // 登录成功后跳转
            if (!string.IsNullOrEmpty(returnUrl) && Url.IsLocalUrl(returnUrl))
                return Redirect(returnUrl);
            return RedirectToAction("Index", "Home");
        }

        // 登录失败，重新显示页面并给出错误信息
        ModelState.AddModelError(string.Empty, "用户名或密码错误");
        ViewData["ReturnUrl"] = returnUrl;
        return View();
    }

    // GET: /Account/Logout
    [HttpGet]
    [Authorize] // 必须已登录才可注销
    public async Task<IActionResult> Logout()
    {
        await HttpContext.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);
        return RedirectToAction("Login", "Account");
    }

    // GET: /Account/AccessDenied
    [HttpGet]
    public IActionResult AccessDenied() => View();
}

