using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

public class HomeController : Controller
{
    // 公开页面（任意用户可访问）
    [HttpGet]
    public IActionResult Public() => Content("公开页面：所有人都可以访问");

    // 需要登录的页面
    [HttpGet]
    [Authorize] // 只要登录即可
    public IActionResult Secure() => Content($"受保护页面，当前用户：{User.Identity?.Name}");

    // 示例：状态改变的 Action（Index）
    // 1️⃣ 必须通过授权策略，仅 Admin 角色可访问
    // 2️⃣ 必须是 POST 并且验证 Antiforgery
    // 3️⃣ 必须检查 Content-Type 为 application/x-www-form-urlencoded（或 application/json，根据业务需求）
    [HttpPost]
    [Authorize(Policy = "AdminOnly")]
    [ValidateAntiForgeryToken] // 虽然全局已开启，这里再次明确
    [Consumes("application/x-www-form-urlencoded")]
    public IActionResult Index([FromForm] string command)
    {
        // 这里放置实际的业务逻辑（例如更新数据库、触发工作流等）
        // command 参数仅做演示，实际请使用强类型 DTO 并进行模型验证
        return Content($"已收到管理员指令：{command}");
    }
}

