        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-security</artifactId>
    </dependency>

    <!-- JWT (jjwt) -->
    <dependency>
        <groupId>io.jsonwebtoken</groupId>
        <artifactId>jjwt-api</artifactId>
        <version>0.11.5</version>
    </dependency>
    <dependency>
        <groupId>io.jsonwebtoken</groupId>
        <artifactId>jjwt-impl</artifactId>
        <version>0.11.5</version>
        <scope>runtime</scope>
    </dependency>
    <dependency>
        <groupId>io.jsonwebtoken</groupId>
        <artifactId>jjwt-jackson</artifactId>
        <version>0.11.5</version>
        <scope>runtime</scope>
    </dependency>

    <!-- Lombok (optional) -->
    <dependency>
        <groupId>org.projectlombok</groupId>
        <artifactId>lombok</artifactId>
        <optional>true</optional>
    </dependency>
</dependencies>
*/

// 2️⃣  JwtUtil（生成、校验、失效时间等）
package com.example.security.jwt;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.stereotype.Component;

import java.security.Key;
import java.util.Date;

@Component
public class JwtUtil {
    // 建议放到配置中心或 environment 变量中
    private final String JWT_SECRET = "YOUR_SUPER_SECRET_KEY_256_BITS_LONG______";
    private final long JWT_EXPIRATION_MS = 3600_000; // 1h

    private final Key key = Keys.hmacShaKeyFor(JWT_SECRET.getBytes());

    public String generateToken(String username) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + JWT_EXPIRATION_MS);
        return Jwts.builder()
            .setSubject(username)
            .setIssuedAt(now)
            .setExpiration(expiry)
            .signWith(key, SignatureAlgorithm.HS256)
            .compact();
    }

    public String getUsernameFromToken(String token) {
        return parseClaims(token).getSubject();
    }

    public boolean validateToken(String token) {
        try {
            parseClaims(token);
            return true;
        } catch (JwtException | IllegalArgumentException ex) {
            // 日志或自定义异常均可
            return false;
        }
    }

    private Claims parseClaims(String token) {
        return Jwts.parserBuilder()
            .setSigningKey(key)
            .build()
            .parseClaimsJws(token)
            .getBody();
    }
}

// 3️⃣  自定义 UserDetails & UserDetailsService（使用 BCrypt 加密密码）
package com.example.security.service;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.userdetails.*;
import org.springframework.stereotype.Service;

import java.util.Collections;

// 这里仅演示，真实项目请对接 DB
@Service
public class MyUserDetailsService implements UserDetailsService {

    @Override
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        // 假设用户名为 admin，密码是 123456 (BCrypt 加密后)
        if (!"admin".equals(username)) {
            throw new UsernameNotFoundException("User not found");
        }
        // BCrypt hash of "123456"
        String encodedPwd = "$2a$10$7QKcbdGwe0Jk2uKj0W4F7eWQkT0qhtbPMqz7E0tN6U6DoX5jzEdpe";
        return new User(username, encodedPwd,
                Collections.singleton(new SimpleGrantedAuthority("ROLE_USER")));
    }
}

// 4️⃣  JwtAuthenticationFilter（把 JWT 装配到 Spring Security Context）
package com.example.security.jwt;

import jakarta.servlet.*;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.*;
import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;

import java.io.IOException;

@Component
@RequiredArgsConstructor
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtUtil jwtUtil;
    private final MyUserDetailsService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {

        String token = resolveToken(request);
        if (StringUtils.hasText(token) && jwtUtil.validateToken(token)) {
            String username = jwtUtil.getUsernameFromToken(token);
            UserDetails userDetails = userDetailsService.loadUserByUsername(username);
            UsernamePasswordAuthenticationToken authToken =
                    new UsernamePasswordAuthenticationToken(userDetails, null, userDetails.getAuthorities());
            authToken.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
            // 将认证信息放入上下文，后续即可通过 @AuthenticationPrincipal 获取
            SecurityContextHolder.getContext().setAuthentication(authToken);
        }
        filterChain.doFilter(request, response);
    }

    private String resolveToken(HttpServletRequest request) {
        String bearer = request.getHeader("Authorization");
        if (StringUtils.hasText(bearer) && bearer.startsWith("Bearer ")) {
            return bearer.substring(7);
        }
        return null;
    }
}

// 5️⃣  统一异常处理（返回 JSON，防止泄露 stacktrace）
package com.example.security.exception;

import jakarta.servlet.http.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.authentication.*;
import org.springframework.security.core.AuthenticationException;
import org.springframework.security.web.*;
import org.springframework.stereotype.Component;

import java.io.IOException;

@Component
public class RestAuthenticationEntryPoint implements AuthenticationEntryPoint {
    @Override
    public void commence(HttpServletRequest request,
                         HttpServletResponse response,
                         AuthenticationException authException) throws IOException {
        response.setContentType("application/json;charset=UTF-8");
        response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
        response.getWriter().write("{\"error\":\"UNAUTHORIZED\",\"msg\":\""+authException.getMessage()+"\"}");
    }
}

@Component
public class RestAccessDeniedHandler implements AccessDeniedHandler {
    @Override
    public void handle(HttpServletRequest request,
                       HttpServletResponse response,
                       AccessDeniedException accessDeniedException) throws IOException {
        response.setContentType("application/json;charset=UTF-8");
        response.setStatus(HttpServletResponse.SC_FORBIDDEN);
        response.getWriter().write("{\"error\":\"FORBIDDEN\",\"msg\":\""+accessDeniedException.getMessage()+"\"}");
    }
}

// 6️⃣  SecurityConfig（核心配置）
package com.example.config;

import com.example.security.exception.*;
import com.example.security.jwt.*;
import com.example.security.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.*;
import org.springframework.security.authentication.*;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.*;
import org.springframework.security.crypto.bcrypt.*;
import org.springframework.security.web.*;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.web.cors.*;

import java.util.*;

@Configuration
@EnableMethodSecurity
@RequiredArgsConstructor
public class SecurityConfig {

    private final JwtAuthenticationFilter jwtAuthenticationFilter;
    private final RestAuthenticationEntryPoint authenticationEntryPoint;
    private final RestAccessDeniedHandler accessDeniedHandler;

    // PasswordEncoder 👉 BCrypt (安全、单向、带盐)
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    // AuthenticationManager 用来在登录接口手动校验用户名/密码
    @Bean
    public AuthenticationManager authenticationManager(HttpSecurity http,
                                                       PasswordEncoder passwordEncoder,
                                                       MyUserDetailsService userDetailsService) throws Exception {
        DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
        provider.setUserDetailsService(userDetailsService);
        provider.setPasswordEncoder(passwordEncoder);
        return new ProviderManager(provider);
    }

    // 精准的 CORS 配置（只放开前端所在域）
    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration config = new CorsConfiguration();
        config.setAllowedOrigins(List.of("http://localhost:8080")); // 前端地址
        config.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));
        config.setAllowedHeaders(List.of("*"));
        config.setExposedHeaders(List.of("Authorization"));
        config.setAllowCredentials(false); // 采用 token 方式，无需 cookie
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/**", config);
        return source;
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            // ① 关闭不必要的默认配置
            .csrf(csrf -> csrf.disable())               // REST + JWT => 禁用 CSRF
            .sessionManagement(sess -> sess.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .cors(cors -> cors.configurationSource(corsConfigurationSource()))

            // ② 统一异常处理
            .exceptionHandling(ex -> ex
                    .authenticationEntryPoint(authenticationEntryPoint)
                    .accessDeniedHandler(accessDeniedHandler))

            // ③ 过滤器链
            .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class)

            // ④ 端点授权
            .authorizeHttpRequests(auth -> auth
                    // 登录/注册等不需要 token
                    .requestMatchers("/api/auth/**").permitAll()
                    // 任何其他接口都必须具备 ROLE_USER（或自行调整）
                    .anyRequest().hasRole("USER")
            );

        return http.build();
    }
}

// 7️⃣  登录控制器（返回 JWT）——演示用
package com.example.controller;

import com.example.security.jwt.*;
import lombok.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.*;
import org.springframework.security.core.userdetails.*;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authenticationManager;
    private final JwtUtil jwtUtil;

    @PostMapping("/login")
    public Map<String, String> login(@RequestBody AuthRequest req) {
        UsernamePasswordAuthenticationToken authToken =
                new UsernamePasswordAuthenticationToken(req.getUsername(), req.getPassword());

        Authentication auth = authenticationManager.authenticate(authToken);
        // authentication 成功后会把 UserDetails 放进去
        String token = jwtUtil.generateToken(req.getUsername());

        return Map.of("accessToken", token);
    }

    @Data
    static class AuthRequest {
        private String username;
        private String password;
    }
}

/* ====================  Vue 前端（JavaScript）  ==================== */
// 1️⃣  安装依赖（npm）
// npm i axios vue-router@4 pinia

// 2️⃣  src/api/axios.js  —— 统一的 axios 实例 & 拦截器
import axios from 'axios';
import router from '@/router';
import { useAuthStore } from '@/stores/auth';

// 创建实例，指向 SpringBoot API 根地址
const api = axios.create({
    baseURL: 'http://localhost:8088',      // 后端端口
    timeout: 12000,
    // 因为我们使用 stateless JWT，不需要 withCredentials
    // withCredentials: false,
});

// 请求拦截：自动把 token 加到 Authorization 头
api.interceptors.request.use(config => {
    const authStore = useAuthStore();
    const token = authStore.accessToken; // 从 Pinia / Vuex 中读取
    if (token) {
        config.headers['Authorization'] = `Bearer ${token}`;
    }
    return config;
}, error => Promise.reject(error));

// 响应拦截：统一处理 401/403
api.interceptors.response.use(resp => resp, error => {
    if (error.response) {
        const status = error.response.status;
        if (status === 401) {
            // token 失效或未登录 → 跳转登录页
            const authStore = useAuthStore();
            authStore.logout(); // 清理本地 token
            router.replace({ name: 'Login' });
        } else if (status === 403) {
            // 没有权限访问的资源
            alert('您没有访问权限');
        }
    }
    return Promise.reject(error);
});

export default api;

// 3️⃣  Pinia store (src/stores/auth.js) – 管理 token
import { defineStore } from 'pinia';
import api from '@/api/axios';

export const useAuthStore = defineStore('auth', {
    state: () => ({
        accessToken: localStorage.getItem('accessToken') || '',
        userInfo: null,
    }),
    actions: {
        async login(username, password) {
            const resp = await api.post('/api/auth/login', { username, password });
            this.accessToken = resp.data.accessToken;
            localStorage.setItem('accessToken', this.accessToken);
        },
        logout() {
            this.accessToken = '';
            this.userInfo = null;
            localStorage.removeItem('accessToken');
        },
        async fetchUserInfo() {
            // 示例：获取当前登录用户信息的接口（需要 token）
            const resp = await api.get('/api/user/me');
            this.userInfo = resp.data;
        }
    }
});

// 4️⃣  登录页面（src/views/Login.vue）示例
<template>
  <div class="login">
    <h2>登录</h2>
    <form @submit.prevent="onLogin">
      <input v-model="username" placeholder="用户名" required />
      <input type="password" v-model="password" placeholder="密码" required />
      <button type="submit">登录</button>
    </form>
    <p v-if="errorMsg" class="error">{{ errorMsg }}</p>
  </div>
</template>

<script setup>
import { ref } from 'vue';
import { useRouter } from 'vue-router';
import { useAuthStore } from '@/stores/auth';

const router = useRouter();
const auth = useAuthStore();

const username = ref('');
const password = ref('');
const errorMsg = ref('');

const onLogin = async () => {
  try {
    await auth.login(username.value, password.value);
    router.replace({ name: 'Home' });
  } catch (e) {
    errorMsg.value = e.response?.data?.msg || '登录失败';
  }
};
</script>

<style scoped>
.login { max-width: 320px; margin: auto; padding: 2rem; }
.error { color: red; margin-top: 0.5rem; }
</style>

// 5️⃣  路由守卫（src/router/index.js）——确保受保护页面只能在登录后访问
import { createRouter, createWebHistory } from 'vue-router';
import { useAuthStore } from '@/stores/auth';
import Home from '@/views/Home.vue';
import Login from '@/views/Login.vue';

const routes = [
  { path: '/', name: 'Home', component: Home, meta: { requiresAuth: true } },
  { path: '/login', name: 'Login', component: Login },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach((to, from, next) => {
  const auth = useAuthStore();
  if (to.meta.requiresAuth && !auth.accessToken) {
    next({ name: 'Login' });
  } else {
    next();
  }
});

export default router;

/* ====================   小结  ==================== */
//  ✅ 关键安全点：
//   • 密码使用 BCrypt 加密（不可逆）
//   • 所有受保护接口使用 JWT（Stateless）并在过滤器中校验
//   • 统一的 AuthenticationEntryPoint / AccessDeniedHandler，避免泄露堆栈信息
//   • 精准的 CORS 配置，仅放通前端域名
//   • 前端 axios 自动携带 token，统一处理 401/403，避免手动拼接 Authorization
//   • 前端 token 存储在 localStorage（若需要更安全可考虑 HttpOnly Cookie + CSRF）
//   • Session 关闭，防止 Session Fixation

把上面的代码复制到对应的项目结构中，重新编译（`mvn clean package`）并启动后端，`npm run dev` 启动 Vue 前端，即可得到一个 **安全可靠** 的用户认证/授权体系。祝开发顺利 🚀!

**Solution – Secure, Serializable Task Distribution Between an Android Client and a Desktop‑PC Server**  
The following self‑contained Java source file demonstrates a minimal but **secure** way to:

1. **Define a serializable work unit (`Task`).**  
2. **Run a TLS‑protected server on the PC** that receives tasks, hands them to a local `ExecutorService` (or `ForkJoinPool`) and returns results.  
3. **Run a TLS‑protected client on Android** that connects to the PC, streams serialized tasks, and receives the computed results.  

The code avoids the classic Java‑serialization vulnerability by **using JSON (Gson)** instead of raw `ObjectInputStream`.  It also uses **`javax.net.ssl`** (available on both the JDK and Android) to protect the data in‑flight.  The whole example lives in a single file (you can copy‑paste it into your IDE and split the `main` methods into two separate projects – one for the PC, one for Android).

```java
/**
 * ClusterExample.java
 *
 * A minimal, secure, cross‑platform example that:
 *   • Defines a simple, JSON‑serializable Task.
 *   • Starts a TLS server on a desktop PC (TaskManager) that
 *       – receives tasks,
 *       – processes them with an ExecutorService/ForkJoinPool,
 *       – sends back the result.
 *   • Starts a TLS client on Android that:
 *       – connects to the PC,
 *       – streams tasks,
 *       – receives results.
 *
 * IMPORTANT:
 *   – Add the appropriate network permissions on Android:
 *         <uses-permission android:name="android.permission.INTERNET"/>
 *   – Generate a self‑signed certificate for the desktop server
 *     (see comments below) and ship the public certificate with the
 *     Android app (or embed it as a resource) so the client can trust
 *     the server.
 *   – In production replace the self‑signed cert with a CA‑signed one
 *     and consider stronger authentication (e.g., mutual TLS).
 *
 * Compile & run (PC side):
 *   javac -cp gson-2.10.1.jar ClusterExample.java
 *   java -cp .:gson-2.10.1.jar ClusterExample server
 *
 * Run (Android side – treat as normal Java code inside an Activity/Service):
 *   new Thread(() -> ClusterExample.runAndroidClient("192.168.1.100", 8443)).start();
 */

import com.google.gson.*;
import com.google.gson.reflect.TypeToken;

import javax.net.ssl.*;
import java.io.*;
import java.lang.reflect.Type;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.cert.X509Certificate;
import java.util.*;
import java.util.concurrent.*;

public class ClusterExample {

    /* ---------------------------------------------------------------------- */
    /* 1️⃣  Task definition – simple POJO, JSON‑serializable                     */
    /* ---------------------------------------------------------------------- */
    static class Task {
        final String id;           // unique identifier (e.g. UUID)
        final String operation;    // e.g. "fib", "hash", "matrixMul"
        final double[] payload;    // generic numeric data

        Task(String id, String operation, double[] payload) {
            this.id = id;
            this.operation = operation;
            this.payload = payload;
        }
    }

    /* ---------------------------------------------------------------------- */
    /* 2️⃣  Result definition – mirrors the Task id so the caller can match   */
    /* ---------------------------------------------------------------------- */
    static class Result {
        final String taskId;
        final double  value;       // outcome of the computation

        Result(String taskId, double value) {
            this.taskId = taskId;
            this.value = value;
        }
    }

    /* ---------------------------------------------------------------------- */
    /* 3️⃣  Server (PC) – TLS protected, thread‑pooled task executor          */
    /* ---------------------------------------------------------------------- */
    public static void runServer(int port, String keystorePath, char[] keystorePass) throws Exception {

        // ---- 3.1 Load server certificate (PKCS12 or JKS) -------------------
        KeyStore ks = KeyStore.getInstance(KeyStore.getDefaultType());
        try (FileInputStream fis = new FileInputStream(keystorePath)) {
            ks.load(fis, keystorePass);
        }

        // ---- 3.2 Initialise SSLContext ------------------------------------
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        kmf.init(ks, keystorePass);
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(kmf.getKeyManagers(), null, new SecureRandom());

        // ---- 3.3 Create SSLServerSocket -----------------------------------
        SSLServerSocketFactory ssf = sslContext.getServerSocketFactory();
        try (SSLServerSocket serverSocket = (SSLServerSocket) ssf.createServerSocket(port)) {
            serverSocket.setNeedClientAuth(false);   // set true for mutual TLS
            System.out.println("[SERVER] Listening on port " + port + " …");

            // ---- 3.4 Thread pool for handling connections -----------------
            ExecutorService connectionPool = Executors.newCachedThreadPool();

            while (true) {
                final SSLSocket client = (SSLSocket) serverSocket.accept();
                connectionPool.submit(() -> handleClient(client));
            }
        }
    }

    /** Handles a single client connection: read Task → compute → write Result */
    private static void handleClient(SSLSocket socket) {
        try (socket;
             BufferedReader  in  = new BufferedReader(new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8));
             BufferedWriter  out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8))) {

            Gson gson = new Gson();
            String line;
            while ((line = in.readLine()) != null) {
                // ---- 3.5 Deserialize the incoming task --------------------
                Task task = gson.fromJson(line, Task.class);
                System.out.println("[SERVER] Received task " + task.id + " (" + task.operation + ")");

                // ---- 3.6 Process task using a local ForkJoinPool -------------
                double answer = processTask(task);
                Result result = new Result(task.id, answer);
                // ---- 3.7 Serialize & send back result ---------------------
                out.write(gson.toJson(result));
                out.newLine();
                out.flush();
                System.out.println("[SERVER] Sent result for " + task.id);
            }
        } catch (Exception e) {
            System.err.println("[SERVER] Connection error: " + e.getMessage());
        }
    }

    /** Sample task processor – add more ops as needed */
    private static double processTask(Task task) {
        switch (task.operation) {
            case "sum":
                return Arrays.stream(task.payload).sum();
            case "avg":
                return Arrays.stream(task.payload).average().orElse(Double.NaN);
            case "max":
                return Arrays.stream(task.payload).max().orElse(Double.NaN);
            // add heavy‑weight operations (matrix mul, FFT, etc.) here
            default:
                throw new IllegalArgumentException("Unsupported op: " + task.operation);
        }
    }

    /* ---------------------------------------------------------------------- */
    /* 4️⃣  Client (Android) – TLS protected, ExecutorService for parallelism */
    /* ---------------------------------------------------------------------- */
    public static void runAndroidClient(String host, int port, InputStream caCertStream) throws Exception {

        // ---- 4.1 Load the server's public certificate (to trust it) -------
        CertificateFactory cf = CertificateFactory.getInstance("X.509");
        X509Certificate caCert = (X509Certificate) cf.generateCertificate(caCertStream);

        // ---- 4.2 Initialise a TrustStore containing only the server cert ----
        KeyStore ts = KeyStore.getInstance(KeyStore.getDefaultType());
        ts.load(null); // create empty keystore
        ts.setCertificateEntry("caCert", caCert);
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(ts);
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, tmf.getTrustManagers(), new SecureRandom());

        // ---- 4.3 Create SSLSocket -----------------------------------------
        SSLSocketFactory sf = sslContext.getSocketFactory();
        try (SSLSocket socket = (SSLSocket) sf.createSocket(host, port)) {
            socket.startHandshake(); // forces verification at this point
            System.out.println("[CLIENT] TLS handshake succeeded");

            // ---- 4.4 I/O wrappers -----------------------------------------
            BufferedReader in  = new BufferedReader(new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8));
            BufferedWriter out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8));
            Gson gson = new Gson();

            // ---- 4.5 Executor for generating & sending tasks in parallel -----
            ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

            // Example: submit 10 asynchronous tasks
            List<Future<Result>> futures = new ArrayList<>();
            for (int i = 0; i < 10; i++) {
                final int idx = i;
                futures.add(executor.submit(() -> {
                    // --- create the task -------------------------------------------------
                    Task task = new Task(UUID.randomUUID().toString(),
                                         "sum",
                                         new double[]{idx, idx * 2, idx * 3});
                    // --- send JSON line --------------------------------------------------
                    synchronized (out) { // prevent interleaved writes
                        out.write(gson.toJson(task));
                        out.newLine();
                        out.flush();
                    }
                    // --- read the matching result ----------------------------------------
                    String respLine;
                    while ((respLine = in.readLine()) != null) {
                        Result r = gson.fromJson(respLine, Result.class);
                        if (r.taskId.equals(task.id)) {
                            return r;
                        }
                        // If the server sends results out of order we could queue them.
                    }
                    throw new IOException("No response for task " + task.id);
                }));
            }

            // ---- 4.6 Collect and display results ----------------------------------
            for (Future<Result> f : futures) {
                Result r = f.get(); // blocks until individual task finishes
                System.out.println("[CLIENT] Result for " + r.taskId + " = " + r.value);
            }

            executor.shutdownNow();
        }
    }

    /* ---------------------------------------------------------------------- */
    /* 5️⃣  Main entry point – choose role via command‑line argument            */
    /* ---------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        if (args.length == 0) {
            System.err.println("Usage: java ClusterExample <server|client> [options]");
            System.exit(1);
        }

        switch (args[0].toLowerCase(Locale.ROOT)) {
            case "server":
                // Example call:
                //   java -cp .:gson-2.10.1.jar ClusterExample server 8443 keystore.p12 password
                if (args.length != 4) {
                    System.err.println("Server syntax: server <port> <keystorePath> <keystorePassword>");
                    System.exit(2);
                }
                int port = Integer.parseInt(args[1]);
                String ksPath = args[2];
                char[] ksPass = args[3].toCharArray();
                runServer(port, ksPath, ksPass);
                break;

            case "client":
                // Example call:
                //   java -cp .:gson-2.10.1.jar ClusterExample client <host> <port> <caCertPem>
                if (args.length != 4) {
                    System.err.println("Client syntax: client <host> <port> <caCertPem>");
                    System.exit(3);
                }
                String host = args[1];
                int cPort = Integer.parseInt(args[2]);
                String caPem = args[3];
                try (FileInputStream fis = new FileInputStream(caPem)) {
                    runAndroidClient(host, cPort, fis);
                }
                break;

            default:
                System.err.println("Unknown role: " + args[0]);
                System.exit(4);
        }
    }
}

/**
 * --------------------------------------------------------------
 * HOW TO CREATE THE SELF‑SIGNED CERT & KEYSTORE (PC side only):
 * --------------------------------------------------------------
 *   1️⃣ Generate a private key & self‑signed cert (valid for 10y):
 *        openssl req -x509 -newkey rsa:2048 -keyout server.key -out server.crt -days 3650 -nodes -subj "/CN=ClusterServer"
 *
 *   2️⃣ Convert to PKCS12 (Java keystore format):
 *        openssl pkcs12 -export -in server.crt -inkey server.key -out keystore.p12 -name server -passout pass:yourPassword
 *
 *   3️⃣ Feed the keystore.p12 path and password to the server invocation.
 *
 *   4️⃣ Export the server public cert (to ship with the Android app):
 *        cp server.crt ca_cert.pem
 *
 *   5️⃣ In Android, place ca_cert.pem in assets/ or raw/ and open it via
 *        getResources().openRawResource(R.raw.ca_cert);
 *
 * --------------------------------------------------------------
 * SECURITY NOTES:
 * --------------------------------------------------------------
 * • **Never** use default Java serialization for untrusted data – it
 *   enables arbitrary object injection attacks.  JSON (or protobuf,
 *   msgpack, etc.) mitigates that risk.
 * • TLS validates the server’s identity; ship the exact CA cert
 *   (or server cert) with the app to avoid “trust‑all‑certificates”.
 * • For production, use a CA‑signed certificate and enable
 *   **mutual TLS** (`setNeedClientAuth(true)`) so the server also
 *   authenticates the Android device.
 * • All I/O is line‑oriented (`\n`) to simplify framing.  For binary
 *   payloads you would prefix each message with its length.
 * --------------------------------------------------------------
 */

**Solution Overview**

The error `Uncaught ReferenceError: require is not defined` appears when you try to run **Node‑only** code (e.g. `const sql = require('mssql');`) in a **browser** environment.  
`require` exists only in Node’s CommonJS runtime.  

Besides that, exposing the **SQL Server credentials** in a front‑end script is a serious security flaw – anyone can view the source and connect directly to your database.

The correct approach is:

1. **Create a Node.js back‑end (e.g. with Express)** that uses the `mssql` driver.
2. **Store the connection information in environment variables** (`.env`) – never commit them to source control.
3. **Expose only the needed data via API routes** (e.g. `/api/users`).  
   The front‑end calls these routes with `fetch`/`axios`; it never sees `require` or the DB credentials.

Below is a **complete, ready‑to‑run example** that demonstrates the above principles.  
All the code is placed inside a **single file** (`server.js`) for simplicity, but you can split it into modules if you wish.

```javascript
/*  ====================  server.js  ====================  */
/*  Run with:  node server.js  (or nodemon server.js)   */

///////////////////////
// 1️⃣  Load dependencies
///////////////////////

import express from 'express';
import sql from 'mssql';
import dotenv from 'dotenv';
import cors from 'cors';

// Load .env variables (DB credentials, etc.)
dotenv.config();

///////////////////////
// 2️⃣  Configure Express
///////////////////////

const app = express();
const PORT = process.env.PORT || 3000;

// Enable CORS for a front‑end running on a different origin
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // adjust to your front‑end URL
}));
app.use(express.json()); // parse JSON bodies

///////////////////////
// 3️⃣  MSSQL connection pool
///////////////////////

/**
 *   The pool is created once and reused for all requests.
 *   Using a pool improves performance and avoids exhausting connections.
 */
const dbConfig = {
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  server: process.env.DB_SERVER,          // e.g. 'localhost' or 'mydb.host.com'
  database: process.env.DB_DATABASE,
  // Optional flags – adjust to your environment
  options: {
    encrypt: process.env.DB_ENCRYPT === 'true', // for Azure
    trustServerCertificate: process.env.DB_TRUST_CERT === 'true', // self‑signed certs
  },
  // Increase pool size if you expect many concurrent requests
  pool: {
    max: 10,
    min: 0,
    idleTimeoutMillis: 30000,
  },
};

let pool; // will hold the connected pool

async function getPool() {
  if (!pool) {
    pool = await sql.connect(dbConfig);
    console.log('✅ Connected to MSSQL');
  }
  return pool;
}

///////////////////////
// 4️⃣  API routes
///////////////////////

// Example route: GET /api/users  → returns all users from dbo.Users
app.get('/api/users', async (req, res) => {
  try {
    const pool = await getPool();
    const result = await pool.request()
      .query('SELECT UserID, UserName, Email FROM dbo.Users'); // adjust to your schema

    res.json({ success: true, data: result.recordset });
  } catch (err) {
    console.error('❌ DB error:', err);
    res.status(500).json({ success: false, error: 'Database error' });
  }
});

// Example route: POST /api/users  → inserts a new user (basic validation)
app.post('/api/users', async (req, res) => {
  const { userName, email } = req.body;
  if (!userName || !email) {
    return res.status(400).json({ success: false, error: 'Missing fields' });
  }

  try {
    const pool = await getPool();

    // Parameterized query prevents SQL injection
    const result = await pool.request()
      .input('UserName', sql.NVarChar(100), userName)
      .input('Email', sql.NVarChar(200), email)
      .query(`
        INSERT INTO dbo.Users (UserName, Email)
        OUTPUT inserted.UserID, inserted.UserName, inserted.Email
        VALUES (@UserName, @Email);
      `);

    const inserted = result.recordset[0];
    res.status(201).json({ success: true, data: inserted });
  } catch (err) {
    console.error('❌ DB insert error:', err);
    res.status(500).json({ success: false, error: 'Database error' });
  }
});

///////////////////////
// 5️⃣  Global error handling (optional)
///////////////////////

app.use((err, _req, res, _next) => {
  console.error('🛑 Unexpected error:', err);
  res.status(500).json({ success: false, error: 'Internal server error' });
});

///////////////////////
// 6️⃣  Start the server
///////////////////////

app.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});

/*  ====================  End of server.js  ====================  */

/*  ----------------------------------------------------
    .env file (place it in the same folder, NEVER commit!)
    ----------------------------------------------------
   DB_USER=your_sql_user
   DB_PASSWORD=your_strong_password
   DB_SERVER=your_server_host_or_ip
   DB_DATABASE=YourDatabase
   DB_ENCRYPT=false          # true for Azure, otherwise false
   DB_TRUST_CERT=true        # set to true if using self‑signed certs
   CORS_ORIGIN=http://localhost:3001   # front‑end URL, or *
   PORT=3000
   ----------------------------------------------------   */

/*  ----------------------------------------------------
    Front‑end example (pure JavaScript, runs in the browser)
    ----------------------------------------------------
   fetch('http://localhost:3000/api/users')
     .then(r => r.json())
     .then(data => console.log('Users:', data));
    ----------------------------------------------------   */

/*  ======================================================
    What we fixed:
    1️⃣  Eliminated the “require is not defined” error by
        using native ES‑modules (`import`) inside Node.
    2️⃣  Removed any exposure of database credentials from
        the client side.
    3️⃣  Implemented parameterized queries to prevent SQL
        injection (security best‑practice).
    4️⃣  Centralised DB connection via a pool.
    5️⃣  Added CORS handling and environment‑based config.
    ======================================================   */

