package com.example.jwtauthdemo.service;

import com.example.jwtauthdemo.model.User;
import com.example.jwtauthdemo.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
public class UserService {
    private final UserRepository userRepository;
    private final BCryptPasswordEncoder passwordEncoder = new BCryptPasswordEncoder();

    public User register(String username, String rawPassword) {
        if (userRepository.existsByUsername(username)) {
            throw new IllegalArgumentException("Username already exists");
        }
        String encoded = passwordEncoder.encode(rawPassword);
        User user = User.builder()
                .username(username)
                .password(encoded)
                .build();
        return userRepository.save(user);
    }

    public User authenticate(String username, String rawPassword) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new IllegalArgumentException("Invalid credentials"));
        if (!passwordEncoder.matches(rawPassword, user.getPassword())) {
            throw new IllegalArgumentException("Invalid credentials");
        }
        return user;
    }
}

//=== file: src/main/java/com/example/jwtauthdemo/security/JwtUtil.java ===
package com.example.jwtauthdemo.security;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import java.security.Key;
import java.util.Date;

@Component
public class JwtUtil {
    private final Key key;
    private final long jwtExpirationMs;

    public JwtUtil(@Value("${jwt.secret}") String secret,
                   @Value("${jwt.expirationMs}") long jwtExpirationMs) {
        this.key = Keys.hmacShaKeyFor(secret.getBytes());
        this.jwtExpirationMs = jwtExpirationMs;
    }

    public String generateToken(String username) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + jwtExpirationMs);
        return Jwts.builder()
                .setSubject(username)
                .setIssuedAt(now)
                .setExpiration(expiry)
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    public String extractUsername(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(key)
                .build()
                .parseClaimsJws(token)
                .getBody()
                .getSubject();
    }

    public boolean isTokenValid(String token) {
        try {
            Jwts.parserBuilder()
                    .setSigningKey(key)
                    .build()
                    .parseClaimsJws(token);
            return true;
        } catch (JwtException | IllegalArgumentException e) {
            return false;
        }
    }
}

//=== file: src/main/java/com/example/jwtauthdemo/security/TokenBlacklistService.java ===
package com.example.jwtauthdemo.security;

import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Service
@RequiredArgsConstructor
public class TokenBlacklistService {
    // token -> expireAt (epoch ms)
    private final Map<String, Long> blacklist = new ConcurrentHashMap<>();

    // expiration for blacklist entries, configurable
    private final long blacklistEntryTtlMs = 3600000L; // 1h

    public void blacklist(String token, long tokenExpirationMs) {
        long expireAt = System.currentTimeMillis() + Math.min(tokenExpirationMs, blacklistEntryTtlMs);
        blacklist.put(token, expireAt);
    }

    public boolean isBlacklisted(String token) {
        Long expire = blacklist.get(token);
        if (expire == null) {
            return false;
        }
        if (expire < System.currentTimeMillis()) {
            // auto‑remove stale entry
            blacklist.remove(token);
            return false;
        }
        return true;
    }
}

