package com.example.jwtauthdemo.controller;

import com.example.jwtauthdemo.model.User;
import com.example.jwtauthdemo.payload.*;
import com.example.jwtauthdemo.security.*;
import com.example.jwtauthdemo.service.UserService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final UserService userService;
    private final JwtUtil jwtUtil;
    private final TokenBlacklistService blacklistService;
    private final AuthenticationManager authManager;

    /** 用户注册 */
    @PostMapping("/signup")
    public ResponseEntity<String> signup(@RequestBody SignupRequest req) {
        try {
            userService.register(req.getUsername(), req.getPassword());
            return ResponseEntity.ok("User registered successfully");
        } catch (IllegalArgumentException e) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(e.getMessage());
        }
    }

    /** 登录 → 返回 JWT */
    @PostMapping("/login")
    public ResponseEntity<AuthResponse> login(@RequestBody LoginRequest req) {
        try {
            Authentication authentication = authManager.authenticate(
                    new UsernamePasswordAuthenticationToken(req.getUsername(), req.getPassword()));
            // 若认证失败，会抛出异常
            SecurityContextHolder.getContext().setAuthentication(authentication);
            String token = jwtUtil.generateToken(req.getUsername());
            return ResponseEntity.ok(new AuthResponse(token));
        } catch (BadCredentialsException ex) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }
    }

    /** 退出（Token 加入黑名单） */
    @PostMapping("/logout")
    public ResponseEntity<String> logout(@RequestHeader(HttpHeaders.AUTHORIZATION) String authHeader) {
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            String token = authHeader.substring(7);
            // 解析 token 失效时间，用于设定黑名单存活期（可选）
            Claims claims = Jwts.parserBuilder().setSigningKey(jwtUtil.getKey())
                    .build().parseClaimsJws(token).getBody();
            long expMillis = claims.getExpiration().getTime() - System.currentTimeMillis();
            blacklistService.blacklist(token, Math.max(expMillis, 0));
        }
        SecurityContextHolder.clearContext();
        return ResponseEntity.ok("Logged out successfully");
    }

    /** 示例受保护资源 */
    @GetMapping("/me")
    public ResponseEntity<String> whoAmI() {
        var auth = SecurityContextHolder.getContext().getAuthentication();
        return ResponseEntity.ok("Hello, " + auth.getName());
    }
}

