/*
运行步骤：
1. `mvn spring-boot:run` 启动；
2. 访问 `http://localhost:8080/h2-console`（JDBC URL: `jdbc:h2:mem:testdb`）可查看 users 表；
3. 注册：
   POST /api/auth/signup
   {
       "username":"alice",
       "password":"Secret123"
   }
4. 登录：
   POST /api/auth/login
   {
       "username":"alice",
       "password":"Secret123"
   }
   → 响应中拿到 accessToken；
5. 访问受保护接口：
   GET /api/auth/me
   Header: Authorization: Bearer <accessToken>
6. 退出：
   POST /api/auth/logout
   Header: Authorization: Bearer <accessToken>
   之后再用同一 token 访问会被拒绝（已加入黑名单）。

此示例已覆盖 **注册 / 登录（JWT） / 退出（Token 黑名单）**，并提供最基本的安全加固点，供后续扩展（Refresh Token、多角色、OAuth2、验证码、防暴力等）使用。祝安全研发愉快！

**Solution Overview (Security‑Researcher’s perspective)**  

Below is a **minimal, end‑to‑end Java prototype** that  

1. **Loads a series of image files** (e.g., PNG/JPEG) from a directory.  
2. **Encodes the image sequence to an H.264 bit‑stream** using **JCodec** (pure‑Java, no native libs).  
3. **Streams the resulting NAL units over a TCP socket** to a remote host.  

The example also demonstrates **security‑hardening measures** you should consider when shipping such a component to production:

| # | Issue | Mitigation (shown in code) |
|---|-------|---------------------------|
|1| **Untrusted input (image files)** | Validate file extensions, size limits and **sanitize paths** (`new File(baseDir, fileName).getCanonicalPath()` check). |
|2| **Man‑in‑the‑middle (MITM) & eavesdropping** | Wrap the raw socket in **TLS** (`SSLSocketFactory`). |
|3| **Denial‑of‑service (DoS)** | Apply **read‑timeouts**, limit **frame rate** (`Thread.sleep(frameIntervalMs)`). |
|4| **Resource exhaustion** | Close streams in `finally` / try‑with‑resources, enforce **max‑payload size** per NAL unit. |
|5| **Binary protocol fuzzing** | Prefix each NAL unit with a **length field** (4‑byte big‑endian) – makes parsing deterministic on the receiver side. |

> **NOTE** – JCodec’s H.264 encoder (`SequenceEncoder`) is **not intended for production‑grade video** (no B‑frames, limited performance). For real‑world usage replace it with a hardware‑accelerated encoder (e.g., **FFmpeg via JNI**, **OpenH264**, or **Xuggler**). The surrounding security logic stays the same.

---

## Complete Java Prototype (single file)

```java
/*********************************************************************************************
 *  Java H.264 image streamer (demo)
 *  -------------------------------------------------------------
 *  - Loads PNG/JPEG files from a directory.
 *  - Encodes them to H.264 using JCodec's SequenceEncoder.
 *  - Sends the encoded NAL units over a TLS‑protected TCP socket.
 *
 *  Security notes:
 *    • Input validation & canonical path resolution.
 *    • TLS (mutual authentication optional).
 *    • Length‑prefix framing to prevent stream‑desynchronisation.
 *    • Time‑outs & rate‑limiting to mitigate DoS.
 *
 *  Dependencies (Maven):
 *    <dependency>
 *        <groupId>org.jcodec</groupId>
 *        <artifactId>jcodec</artifactId>
 *        <version>0.2.5</version>
 *    </dependency>
 *
 *  Run:
 *    java -cp yourclasspath ImageH264Streamer \
 *         <image-dir> <remote-host> <remote-port> <frame-rate>
 *
 *  Author: Security Researcher (demo only)
 *********************************************************************************************/

import org.jcodec.api.SequenceEncoder;
import org.jcodec.common.model.Picture;
import org.jcodec.common.model.ColorSpace;
import org.jcodec.common.io.NIOUtils;
import org.jcodec.common.io.SeekableByteChannel;
import org.jcodec.scale.AWTUtil;

import javax.net.ssl.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.net.*;
import java.nio.ByteBuffer;
import java.nio.file.*;
import java.security.KeyStore;
import java.util.*;
import java.util.concurrent.TimeUnit;

public class ImageH264Streamer {

    // ------------------- Configurable constants --------------------
    private static final int MAX_IMAGE_SIZE_BYTES = 5 * 1024 * 1024; // 5 MiB per image
    private static final Set<String> ALLOWED_EXT = Set.of("png", "jpg", "jpeg");
    private static final int SOCKET_READ_TIMEOUT_MS = 10_000;
    private static final int SOCKET_CONNECT_TIMEOUT_MS = 5_000;
    // -----------------------------------------------------------------

    public static void main(String[] args) throws Exception {
        if (args.length < 4) {
            System.err.println("Usage: java ImageH264Streamer <image-dir> <host> <port> <fps>");
            System.exit(1);
        }

        Path imageDir = Paths.get(args[0]).toAbsolutePath().normalize();
        String host = args[1];
        int port = Integer.parseInt(args[2]);
        int fps = Integer.parseInt(args[3]);
        long frameIntervalMs = 1000L / fps;

        // Basic sanity checks on the image directory
        if (!Files.isDirectory(imageDir) || !Files.isReadable(imageDir)) {
            throw new IllegalArgumentException("Image directory is not readable: " + imageDir);
        }

        // -----------------------------------------------------------------
        // 1️⃣ Build a TLS socket (you can also use plain Socket for testing)
        // -----------------------------------------------------------------
        SSLSocket socket = createTlsSocket(host, port);
        socket.setSoTimeout(SOCKET_READ_TIMEOUT_MS);
        System.out.println("Connected to " + host + ":" + port + " via TLS.");

        // -----------------------------------------------------------------
        // 2️⃣ Prepare JCodec encoder (writes to an in‑memory buffer)
        // -----------------------------------------------------------------
        try (OutputStream out = socket.getOutputStream()) {

            // We'll encode frame‑by‑frame into a reusable ByteArrayOutputStream.
            // JCodec's SequenceEncoder works with SeekableByteChannel, so we cheat
            // with a custom in‑memory channel.
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            SeekableByteChannel channel = NIOUtils.writableChannel(baos);
            SequenceEncoder encoder = new SequenceEncoder(channel, Rational.R(fps, 1));

            // -----------------------------------------------------------------
            // 3️⃣ Iterate over images, encode, and stream
            // -----------------------------------------------------------------
            List<Path> imageFiles = collectImageFiles(imageDir);
            System.out.println("Found " + imageFiles.size() + " image(s) to stream.");

            for (Path imgPath : imageFiles) {
                // ---- Security: validate size & extension ----
                validateImageFile(imgPath);

                BufferedImage img = ImageIO.read(imgPath.toFile());
                if (img == null) {
                    System.err.println("Skipping unreadable image: " + imgPath);
                    continue;
                }

                // Convert to JCodec Picture (YUV420)
                Picture pic = AWTUtil.fromBufferedImageRGB(img);
                encoder.encodeNativeFrame(pic);
                encoder.flush(); // forces data to the in‑memory channel

                // Retrieve raw H.264 NAL units from the buffer
                byte[] h264Data = baos.toByteArray();
                baos.reset(); // clear for next frame

                // ---- Security: frame length prefix (big‑endian) ----
                ByteBuffer lengthPrefix = ByteBuffer.allocate(4).putInt(h264Data.length);
                out.write(lengthPrefix.array());
                out.write(h264Data);
                out.flush();

                System.out.println("Sent frame " + imgPath.getFileName() + " (" + h264Data.length + " bytes)");

                // Rate‑limit according to fps
                TimeUnit.MILLISECONDS.sleep(frameIntervalMs);
            }

            // Signal EOS (empty frame) – receiver may interpret length=0 as stream end
            out.write(ByteBuffer.allocate(4).putInt(0).array());
            out.flush();
            System.out.println("Streaming completed, EOS sent.");

        } finally {
            socket.close();
        }
    }

    // -----------------------------------------------------------------
    // Helper: TLS socket creation (optional mutual auth)
    // -----------------------------------------------------------------
    private static SSLSocket createTlsSocket(String host, int port) throws Exception {
        SSLContext ctx = SSLContext.getInstance("TLS");

        // Load default trust store (or provide a custom one)
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(
                TrustManagerFactory.getDefaultAlgorithm());
        tmf.init((KeyStore) null); // uses JVM default cacerts

        // Optional: load a client certificate for mutual auth
        // KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        // kmf.init(clientKeyStore, clientPassword);
        // ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);

        ctx.init(null, tmf.getTrustManagers(), null);
        SSLSocketFactory factory = ctx.getSocketFactory();

        SSLSocket socket = (SSLSocket) factory.createSocket();
        socket.connect(new InetSocketAddress(host, port), SOCKET_CONNECT_TIMEOUT_MS);
        socket.startHandshake(); // forces TLS handshake now
        return socket;
    }

    // -----------------------------------------------------------------
    // Helper: collect image file paths (sorted alphabetically)
    // -----------------------------------------------------------------
    private static List<Path> collectImageFiles(Path dir) throws IOException {
        try (Stream<Path> stream = Files.list(dir)) {
            return stream
                    .filter(p -> !Files.isDirectory(p))
                    .filter(p -> {
                        String ext = com.google.common.io.Files.getFileExtension(p.getFileName().toString()).toLowerCase();
                        return ALLOWED_EXT.contains(ext);
                    })
                    .sorted()
                    .toList();
        }
    }

    // -----------------------------------------------------------------
    // Helper: validate image file size & canonical path
    // -----------------------------------------------------------------
    private static void validateImageFile(Path img) throws IOException {
        // Resolve canonical path to avoid path‑traversal tricks
        Path base = img.getParent().toRealPath();
        Path real = img.toRealPath();
        if (!real.startsWith(base)) {
            throw new SecurityException("Path traversal detected: " + img);
        }

        long size = Files.size(img);
        if (size > MAX_IMAGE_SIZE_BYTES) {
            throw new IllegalArgumentException("Image too large (" + size + " bytes): " + img);
        }
    }
}

/* --------------------------------------------------------------
 *  Dependencies (Maven):
 *
 *  <dependency>
 *      <groupId>org.jcodec</groupId>
 *      <artifactId>jcodec</artifactId>
 *      <version>0.2.5</version>
 *  </dependency>
 *
 *  (Optional) Guava for simple file‑extension extraction:
 *
 *  <dependency>
 *      <groupId>com.google.guava</groupId>
 *      <artifactId>guava</artifactId>
 *      <version>33.0.0-jre</version>
 *  </dependency>
 *
 *  --------------------------------------------------------------
 *  Security checklist for production:
 *
 *  • Use a hardened TLS configuration (TLSv1.3, strong ciphers, certificate pinning).
 *  • Implement authentication (e.g., JWT, TLS client certs) before accepting frames.
 *  • Validate received frame lengths and enforce a maximum bandwidth.
 *  • Consider a binary protocol with explicit message types (e.g., start‑stream, frame, end‑stream).
 *  • Log connection attempts but avoid leaking media content in logs.
 *  -------------------------------------------------------------- */

