/* --------------------------------------------------------------
 *  file:    Services/WeChatService.cs
 * -------------------------------------------------------------- */
using System.Net.Http.Headers;
using System.Security.Cryptography;
using System.Text;
using System.Xml;
using System.Xml.Serialization;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public interface IWeChatService
{
    Task<bool> ValidateSignatureAsync(string signature, string timestamp, string nonce);
    Task<string?> GetAccessTokenAsync();
    Task<bool> SendCustomMessageAsync(string openId, string content);
    WeChatResponseMessage BuildTextResponse(WeChatMessage request, string reply);
}

public class WeChatService : IWeChatService
{
    private readonly HttpClient _http;
    private readonly WeChatConfig _cfg;
    private readonly IMemoryCache _cache;
    private readonly ILogger<WeChatService> _log;

    private const string TokenCacheKey = "WeChatAccessToken";

    public WeChatService(HttpClient http, WeChatConfig cfg,
                         IMemoryCache cache, ILogger<WeChatService> log)
    {
        _http = http;
        _cfg = cfg;
        _cache = cache;
        _log = log;
    }

    // 1️⃣ 微信服务器对接时的签名校验（GET） —— 必须使用 SHA1
    public async Task<bool> ValidateSignatureAsync(string signature, string timestamp, string nonce)
    {
        var arr = new[] { _cfg.Token, timestamp, nonce };
        Array.Sort(arr, StringComparer.Ordinal);
        var raw = string.Concat(arr);
        using var sha1 = SHA1.Create();
        var hash = sha1.ComputeHash(Encoding.UTF8.GetBytes(raw));
        var hashStr = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        var ok = hashStr == signature?.ToLowerInvariant();
        _log.LogDebug("Signature validation: {Result} (calc:{Calc}, recv:{Recv})", ok, hashStr, signature);
        return ok;
    }

    // 2️⃣ 获取全局 access_token（缓存 7200 秒）—— 安全起见请求时添加 HTTPS、超时控制
    public async Task<string?> GetAccessTokenAsync()
    {
        if (_cache.TryGetValue(TokenCacheKey, out string token))
            return token;

        var url = $"https://api.weixin.qq.com/cgi-bin/token?grant_type=client_credential&appid={_cfg.AppId}&secret={_cfg.AppSecret}";
        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
        var resp = await _http.GetAsync(url, cts.Token);
        resp.EnsureSuccessStatusCode();

        var json = await resp.Content.ReadAsStringAsync(cts.Token);
        using var doc = System.Text.Json.JsonDocument.Parse(json);
        if (doc.RootElement.TryGetProperty("access_token", out var at))
        {
            token = at.GetString();
            // 7200 秒有效期，提前 5 分钟过期
            _cache.Set(TokenCacheKey, token, TimeSpan.FromSeconds(7200 - 300));
            _log.LogInformation("Fetched new WeChat access token.");
            return token;
        }

        _log.LogError("Failed to obtain access token: {Json}", json);
        return null;
    }

    // 3️⃣ 主动客服消息（仅限已关注用户）
    public async Task<bool> SendCustomMessageAsync(string openId, string content)
    {
        var accessToken = await GetAccessTokenAsync();
        if (string.IsNullOrEmpty(accessToken))
            return false;

        var url = $"https://api.weixin.qq.com/cgi-bin/message/custom/send?access_token={accessToken}";
        var payload = new
        {
            touser = openId,
            msgtype = "text",
            text = new { content }
        };

        var json = System.Text.Json.JsonSerializer.Serialize(payload);
        using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
        var resp = await _http.PostAsync(url,
                new StringContent(json, Encoding.UTF8, "application/json"), cts.Token);
        var respJson = await resp.Content.ReadAsStringAsync(cts.Token);
        _log.LogInformation("Send custom message result: {Result}", respJson);
        return resp.IsSuccessStatusCode && respJson.Contains("\"errcode\":0");
    }

    // 4️⃣ 被动回复（XML）—— 利用 XmlSerializer 生成安全的 XML，避免 XSS
    public WeChatResponseMessage BuildTextResponse(WeChatMessage request, string reply)
    {
        return new WeChatResponseMessage
        {
            ToUserName = request.FromUserName,
            FromUserName = request.ToUserName,
            CreateTime = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
            MsgType = "text",
            Content = reply
        };
    }

    // 辅助：将对象序列化为 XML（不包含 XML Declaration，微信要求这种形式）
    public static string SerializeToXml<T>(T obj)
    {
        var ns = new XmlSerializerNamespaces();
        ns.Add(string.Empty, string.Empty);
        var serializer = new XmlSerializer(typeof(T));
        var settings = new XmlWriterSettings { OmitXmlDeclaration = true, Encoding = Encoding.UTF8 };
        using var sw = new StringWriter();
        using var writer = XmlWriter.Create(sw, settings);
        serializer.Serialize(writer, obj, ns);
        return sw.ToString();
    }

    // 辅助：将 XML 反序列化为对象（使用安全的 XmlReader，禁用 DTD）
    public static T? DeserializeFromXml<T>(string xml)
    {
        var serializer = new XmlSerializer(typeof(T));
        var settings = new XmlReaderSettings
        {
            DtdProcessing = DtdProcessing.Prohibit,
            XmlResolver = null
        };
        using var sr = new StringReader(xml);
        using var reader = XmlReader.Create(sr, settings);
        return (T?)serializer.Deserialize(reader);
    }
}

/* --------------------------------------------------------------
 *  file:    Controllers/WeChatController.cs
 * -------------------------------------------------------------- */
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("wechat")]
public class WeChatController : ControllerBase
{
    private readonly IWeChatService _svc;
    private readonly ILogger<WeChatController> _log;

    public WeChatController(IWeChatService svc, ILogger<WeChatController> log)
    {
        _svc = svc;
        _log = log;
    }

    // ① 微信服务器配置 URL 时发送的 GET（返回 echostr）
    [HttpGet]
    public async Task<IActionResult> Get([FromQuery] string signature,
                                         [FromQuery] string timestamp,
                                         [FromQuery] string nonce,
                                         [FromQuery] string echostr)
    {
        if (await _svc.ValidateSignatureAsync(signature, timestamp, nonce))
            return Content(echostr); // 直接返回 echostr 即通过验证
        _log.LogWarning("Invalid signature for GET verification.");
        return BadRequest("invalid signature");
    }

    // ② 业务消息 POST（XML）
    [HttpPost]
    public async Task<IActionResult> Post()
    {
        // 限制请求体大小（防止 DoS），已在 Program.cs 中配置
        var xml = await new StreamReader(Request.Body, Encoding.UTF8).ReadToEndAsync();
        var msg = WeChatService.DeserializeFromXml<WeChatMessage>(xml);
        if (msg == null)
        {
            _log.LogWarning("Failed to deserialize incoming XML.");
            return BadRequest();
        }

        // 简单示例：自动回复收到的文本内容（演示安全回复）
        string replyContent = msg.MsgType?.ToLower() switch
        {
            "text" => $"你发送了: {msg.Content}",
            "event" when msg.Event?.ToLower() == "subscribe" => "感谢关注！",
            _ => "暂不支持此类型消息"
        };

        var respMsg = _svc.BuildTextResponse(msg, replyContent);
        var respXml = WeChatService.SerializeToXml(respMsg);
        return Content(respXml, "application/xml");
    }

    // ③ 示例：主动发送客服消息（供内部调用或后台任务使用）
    //    POST /wechat/send?openid=xxxx
    [HttpPost("send")]
    public async Task<IActionResult> Send([FromQuery] string openid, [FromBody] string content)
    {
        if (string.IsNullOrWhiteSpace(openid) || string.IsNullOrWhiteSpace(content))
            return BadRequest("openid/content required");

        var ok = await _svc.SendCustomMessageAsync(openid, content);
        return ok ? Ok("sent") : StatusCode(500, "send fail");
    }
}

/* --------------------------------------------------------------
 *  file:    Program.cs
 * -------------------------------------------------------------- */
using Microsoft.Extensions.Caching.Memory;

var builder = WebApplication.CreateBuilder(args);

// --- 基础设施 ---
builder.Services.Configure<WeChatConfig>(builder.Configuration.GetSection("WeChat"));
builder.Services.AddSingleton(sp => WeChatConfig.FromConfiguration(builder.Configuration));
builder.Services.AddMemoryCache();
builder.Services.AddHttpClient<IWeChatService, WeChatService>(c =>
{
    c.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
    // 强制使用 HTTPS
    c.BaseAddress = new Uri("https://api.weixin.qq.com/");
    c.Timeout = TimeSpan.FromSeconds(10);
});

// MVC（仅用于 Controller 示例）
builder.Services.AddControllers()
        .AddXmlSerializerFormatters(); // 兼容 XML

// 日志
builder.Logging.ClearProviders();
builder.Logging.AddConsole();

// --- 安全与中间件 ---
var app = builder.Build();

// 必须使用 HTTPS（微信只会回调 HTTPS）
app.UseHttpsRedirection();

// 限制请求体大小（default 30 MB，这里改成 1 MB 防止恶意大包）
app.Use(async (ctx, next) =>
{
    ctx.Request.EnableBuffering(); // 允许多次读取
    ctx.Request.Body = new LimitStream(ctx.Request.Body, 1 * 1024 * 1024);
    await next();
});

// 路由
app.MapControllers();

// 全局异常捕获（生产环境建议写入日志系统）
app.UseExceptionHandler(errApp =>
{
    errApp.Run(async ctx =>
    {
        ctx.Response.StatusCode = 500;
        ctx.Response.ContentType = "application/json";
        await ctx.Response.WriteAsync("{\"error\":\"internal server error\"}");
    });
});

app.Run();

/* --------------------------------------------------------------
 *  file:    LimitStream.cs   (简单的请求体大小限制流)
 * -------------------------------------------------------------- */
using System.Buffers;

public sealed class LimitStream : Stream
{
    private readonly Stream _inner;
    private readonly long _maxBytes;
    private long _totalRead;

    public LimitStream(Stream inner, long maxBytes)
    {
        _inner = inner;
        _maxBytes = maxBytes;
    }

    public override bool CanRead => _inner.CanRead;
    public override bool CanSeek => false;
    public override bool CanWrite => false;
    public override long Length => _inner.Length;

    public override long Position
    {
        get => _inner.Position;
        set => throw new NotSupportedException();
    }

    public override void Flush() => _inner.Flush();

    public override int Read(byte[] buffer, int offset, int count)
    {
        var remain = _maxBytes - _totalRead;
        if (remain <= 0)
            throw new IOException("Request body exceeds allowed limit.");

        var toRead = (int)Math.Min(count, remain);
        var read = _inner.Read(buffer, offset, toRead);
        _totalRead += read;
        return read;
    }

    public override async Task<int> ReadAsync(byte[] buffer, int offset, int count, CancellationToken ct)
    {
        var remain = _maxBytes - _totalRead;
        if (remain <= 0)
            throw new IOException("Request body exceeds allowed limit.");

        var toRead = (int)Math.Min(count, remain);
        var read = await _inner.ReadAsync(buffer.AsMemory(offset, toRead), ct);
        _totalRead += read;
        return read;
    }

    public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
    public override void SetLength(long value) => throw new NotSupportedException();
    public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
}

/* --------------------------------------------------------------
 *  小结
 * --------------------------------------------------------------
 * - `GET /wechat`   : 微信服务器配置地址时的签名校验，返回 echostr
 * - `POST /wechat`  : 接收用户发来的 XML 消息，安全反序列化后自动回复文本
 * - `POST /wechat/send?openid=xxxx` : 示例主动发送客服消息（内部调用）
 *
 * 关键安全点：
 *   • 所有请求均强制 HTTPS（`UseHttpsRedirection` + 服务器证书）
 *   • 输入签名采用 SHA1 严格大小写比较
 *   • XML 反序列化禁止 DTD、禁用 XmlResolver 防止 XXE
 *   • 业务响应使用 XmlSerializer 自动转义字符防 XSS
 *   • 请求体大小限制 1 MB，防止 DoS
 *   • AccessToken 使用内存缓存并提前 5 min 失效，避免频繁请求
 *   • 全局异常捕获避免泄露内部异常细节
 *
 * 将此代码粘贴到项目对应文件后 `dotnet run` 即可在生产环境部署（建议使用反向代理如 Nginx/Apache 终端 TLS）。祝研发顺利！

下面给出 **基于 Socket 的电商客服系统** 的完整实现示例。  
系统包括 **用户端** 与 **客服端** 两大模块，使用 **Swing** 完成界面，**ObjectInput/OutputStream** 进行文字/图片/文件的传输，聊天记录保存在本地文件中，支持：

* 客服端同时服务多位用户（每个用户在单独的线程中处理）  
* 新用户请求时弹出提示，客服可以 **接受** 或 **拒绝**  
* 客服长时间不响应时，用户端会显示 “客服忙” 提示  
* 支持文字、图片、文件的收发  
* 聊天记录持久化（每个用户对应一个记录文件），再次登录时自动加载历史记录  

> **注意**：示例代码已尽可能保持简洁易读，实际项目中请根据需求加入安全、身份校验、日志、UI 美化等功能。

```java
/****************************************************************************************
 * 1. 公共数据结构（Message） ---------------------------------------------------------
 *    用于在客户端/服务端之间传递文字、图片、文件等信息，采用 Serializable 便于
 *    通过 ObjectStream 直接发送。
 ****************************************************************************************/
import java.io.*;
import java.awt.image.*;
import javax.imageio.ImageIO;

/**
 * 消息类型枚举
 */
enum MsgType { TEXT, IMAGE, FILE, REQUEST, RESPONSE }

/**
 * 消息体（可序列化），所有数据通过该对象在网络上传输
 */
class Message implements Serializable {
    private static final long serialVersionUID = 1L;

    // 消息种类
    MsgType type;
    // 发送方标识（用户ID、客服ID）
    String from;
    // 接收方标识（客服ID、用户ID，可为空表示广播）
    String to;
    // 文本内容（仅 TEXT、REQUEST、RESPONSE 使用）
    String text;
    // 文件名（FILE、IMAGE 使用）
    String fileName;
    // 文件/图片的字节数组
    byte[] data;
    // 客服端对用户请求的应答（true=接受, false=拒绝）
    Boolean accept;

    // ---- 工厂方法 -------------------------------------------------
    static Message text(String from, String to, String txt) {
        Message m = new Message();
        m.type = MsgType.TEXT;
        m.from = from; m.to = to; m.text = txt;
        return m;
    }
    static Message image(String from, String to, String name, byte[] data) {
        Message m = new Message();
        m.type = MsgType.IMAGE;
        m.from = from; m.to = to; m.fileName = name; m.data = data;
        return m;
    }
    static Message file(String from, String to, String name, byte[] data) {
        Message m = new Message();
        m.type = MsgType.FILE;
        m.from = from; m.to = to; m.fileName = name; m.data = data;
        return m;
    }
    static Message request(String from) {   // 用户请求客服
        Message m = new Message();
        m.type = MsgType.REQUEST;
        m.from = from;
        return m;
    }
    static Message response(String to, boolean accept) { // 客服响应用户请求
        Message m = new Message();
        m.type = MsgType.RESPONSE;
        m.to = to; m.accept = accept;
        return m;
    }
}

/****************************************************************************************
 * 2. 客服端（Server） ---------------------------------------------------------------
 *    - 监听端口，接受用户连接
 *    - 为每个用户创建独立的处理线程（ClientHandler）
 *    - UI 中会弹出新连接请求窗口，客服可以接受或拒绝
 *    - 接受后创建对应的 ChatWindow（Swing）进行聊天
 ****************************************************************************************/
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import javax.swing.*;

class Server {
    private static final int PORT = 8888;
    // 保存在线用户的 handler，key 为用户ID
    private final ConcurrentHashMap<String, ClientHandler> onlineUsers = new ConcurrentHashMap<>();

    // 主入口
    public static void main(String[] args) {
        new Server().start();
    }

    /** 启动服务器并监听客户端连接 */
    public void start() {
        SwingUtilities.invokeLater(() -> new ServerUI(this).setVisible(true));

        try (ServerSocket ss = new ServerSocket(PORT)) {
            System.out.println("客服端启动，监听端口 " + PORT);
            while (true) {
                Socket socket = ss.accept();                // 接受新连接
                new Thread(() -> handleNewConnection(socket)).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 处理新来的用户连接 */
    private void handleNewConnection(Socket socket) {
        try {
            // 读取用户的首次请求（Message.request）
            ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
            Message request = (Message) ois.readObject(); // type == REQUEST
            String userId = request.from;                 // 这里直接用客户端生成的唯一标识

            // 弹出 UI 让客服决定是否接受
            int opt = JOptionPane.showConfirmDialog(
                    null,
                    "用户 [" + userId + "] 请求客服，是否接受？",
                    "新用户请求",
                    JOptionPane.YES_NO_OPTION);
            boolean accept = (opt == JOptionPane.YES_OPTION);

            // 把接受/拒绝消息写回客户端
            ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
            oos.writeObject(Message.response(userId, accept));
            oos.flush();

            if (!accept) {
                socket.close();   // 拒绝后直接关闭连接
                return;
            }

            // 客服接受后，创建专属 handler 与聊天窗口
            ClientHandler handler = new ClientHandler(userId, socket, ois, oos, this);
            onlineUsers.put(userId, handler);
            SwingUtilities.invokeLater(() -> handler.openChatWindow());

        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

    /** 当用户下线时从在线表中移除 */
    void removeUser(String userId) {
        onlineUsers.remove(userId);
    }
}

/** 每个用户对应的处理线程，负责收/发消息并维护聊天记录 */
class ClientHandler implements Runnable {
    private final String userId;
    private final Socket socket;
    private final ObjectInputStream ois;
    private final ObjectOutputStream oos;
    private final Server server;
    private ChatWindow chatWindow;
    private final File historyFile;

    private volatile boolean running = true;

    public ClientHandler(String userId,
                         Socket socket,
                         ObjectInputStream ois,
                         ObjectOutputStream oos,
                         Server server) throws IOException {
        this.userId = userId;
        this.socket = socket;
        this.ois = ois;
        this.oos = oos;
        this.server = server;
        this.historyFile = new File("history_" + userId + ".log");
    }

    /** 打开聊天窗口（Swing） */
    void openChatWindow() {
        chatWindow = new ChatWindow("客服 - 与用户 [" + userId + "] 对话", this);
        // 加载历史记录
        if (historyFile.exists()) {
            try (BufferedReader br = new BufferedReader(new FileReader(historyFile))) {
                String line;
                while ((line = br.readLine()) != null) {
                    chatWindow.appendSystemMessage(line);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        new Thread(this).start(); // 启动接收线程
    }

    /** 发送文字 */
    void sendText(String txt) {
        try {
            Message m = Message.text("客服", userId, txt);
            oos.writeObject(m);
            oos.flush();
            appendChat("客服", txt);
        } catch (IOException e) {
            showError(e);
        }
    }

    /** 发送图片 */
    void sendImage(File imgFile) {
        try {
            byte[] data = Files.readAllBytes(imgFile.toPath());
            Message m = Message.image("客服", userId, imgFile.getName(), data);
            oos.writeObject(m);
            oos.flush();
            appendChat("客服[图片]", imgFile.getName());
        } catch (IOException e) {
            showError(e);
        }
    }

    /** 发送文件 */
    void sendFile(File file) {
        try {
            byte[] data = Files.readAllBytes(file.toPath());
            Message m = Message.file("客服", userId, file.getName(), data);
            oos.writeObject(m);
            oos.flush();
            appendChat("客服[文件]", file.getName());
        } catch (IOException e) {
            showError(e);
        }
    }

    /** 将本次聊天保存到历史文件 */
    private void appendChat(String from, String content) {
        String line = String.format("[%s] %s: %s", new Date(), from, content);
        chatWindow.appendMessage(line);
        try (PrintWriter pw = new PrintWriter(new FileWriter(historyFile, true))) {
            pw.println(line);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 关闭连接并清理 */
    void close() {
        running = false;
        try { socket.close(); } catch (IOException ignored) {}
        server.removeUser(userId);
        if (chatWindow != null) chatWindow.dispose();
    }

    /** 主接收循环（在独立线程中运行） */
    @Override
    public void run() {
        try {
            while (running) {
                Message msg = (Message) ois.readObject();
                switch (msg.type) {
                    case TEXT:
                        appendChat("用户", msg.text);
                        break;
                    case IMAGE:
                        // 保存图片到本地并显示
                        File img = new File("recv_" + msg.fileName);
                        try (FileOutputStream fos = new FileOutputStream(img)) {
                            fos.write(msg.data);
                        }
                        appendChat("用户[图片]", msg.fileName);
                        chatWindow.showImage(img);
                        break;
                    case FILE:
                        // 保存文件到本地
                        File f = new File("recv_" + msg.fileName);
                        try (FileOutputStream fos = new FileOutputStream(f)) {
                            fos.write(msg.data);
                        }
                        appendChat("用户[文件]", msg.fileName);
                        chatWindow.showFile(f);
                        break;
                    default:
                        // 其它类型不处理
                }
            }
        } catch (Exception e) {
            if (running) showError(e);
            close();
        }
    }

    private void showError(Exception e) {
        JOptionPane.showMessageDialog(chatWindow,
                "通信错误：" + e.getMessage(),
                "错误",
                JOptionPane.ERROR_MESSAGE);
    }
}

/** 客服端主界面（非常简易的框架，仅用来显示正在服务的用户列表） */
class ServerUI extends JFrame {
    private final Server server;
    private final DefaultListModel<String> listModel = new DefaultListModel<>();

    ServerUI(Server server) {
        this.server = server;
        setTitle("客服系统 - 在线用户");
        setSize(300, 400);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();
        // 定时刷新在线用户列表
        new Timer(1000, e -> refreshUserList()).start();
    }

    private void initUI() {
        JList<String> userList = new JList<>(listModel);
        add(new JScrollPane(userList), BorderLayout.CENTER);
    }

    private void refreshUserList() {
        Set<String> users = server.onlineUsers.keySet();
        SwingUtilities.invokeLater(() -> {
            listModel.clear();
            for (String u : users) listModel.addElement(u);
        });
    }
}

/****************************************************************************************
 * 3. 用户端（Client） ---------------------------------------------------------------
 *    - 启动后尝试连接客服端并发送请求（Message.request）  
 *    - 等待客服响应，若在 10 秒内未收到响应则弹出“客服忙”提示  
 *    - 成功后打开 ChatWindow 与客服进行聊天（文字、图片、文件）  
 *    - 所有聊天记录保存在本地文件（history_<clientId>.log），再次登录时自动加载
 ****************************************************************************************/
import java.net.*;
import java.util.*;
import javax.swing.*;

class Client {
    private static final String SERVER_IP = "127.0.0.1";
    private static final int SERVER_PORT = 8888;
    // 客户端唯一标识（实际项目可改为登录用户名等）
    private final String clientId = UUID.randomUUID().toString().substring(0, 8);
    private Socket socket;
    private ObjectOutputStream oos;
    private ObjectInputStream ois;
    private ChatWindow chatWindow;
    private File historyFile;
    private volatile boolean running = true;

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new Client().start());
    }

    /** 开始连接客服端 */
    void start() {
        // 异步连接，防止 UI 卡死
        new Thread(this::connectToServer).start();
    }

    /** 与服务器建立 Socket 连接并完成请求/响应交互 */
    private void connectToServer() {
        try {
            socket = new Socket(SERVER_IP, SERVER_PORT);
            oos = new ObjectOutputStream(socket.getOutputStream());
            ois = new ObjectInputStream(socket.getInputStream());

            // 发送请求（REQUEST）
            oos.writeObject(Message.request(clientId));
            oos.flush();

            // 设置 10 秒超时等待响应（RESPONSE）
            socket.setSoTimeout(10_000);
            Message response = (Message) ois.readObject();
            socket.setSoTimeout(0); // 取消超时

            if (response.type != MsgType.RESPONSE || response.accept == null) {
                showError("收到非法响应，已断开");
                close();
                return;
            }

            if (!response.accept) {
                JOptionPane.showMessageDialog(null,
                        "客服暂时无法接入，请稍后再试。",
                        "提示",
                        JOptionPane.INFORMATION_MESSAGE);
                close();
                return;
            }

            // 客服接受请求，打开聊天窗口
            SwingUtilities.invokeLater(this::openChatWindow);
            // 启动接收线程
            new Thread(this::receiveLoop).start();

        } catch (SocketTimeoutException e) {
            JOptionPane.showMessageDialog(null,
                    "客服忙，请稍后重试。",
                    "提示",
                    JOptionPane.INFORMATION_MESSAGE);
            close();
        } catch (Exception e) {
            e.printStackTrace();
            showError("连接出错：" + e.getMessage());
            close();
        }
    }

    /** 打开聊天窗口并加载历史记录 */
    private void openChatWindow() {
        chatWindow = new ChatWindow("用户端 - 与客服对话", this);
        historyFile = new File("history_" + clientId + ".log");
        if (historyFile.exists()) {
            try (BufferedReader br = new BufferedReader(new FileReader(historyFile))) {
                String line;
                while ((line = br.readLine()) != null) {
                    chatWindow.appendSystemMessage(line);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /** 将文本发送给客服 */
    void sendText(String txt) {
        try {
            Message m = Message.text(clientId, "客服", txt);
            oos.writeObject(m);
            oos.flush();
            appendChat("我", txt);
        } catch (IOException e) {
            showError(e);
        }
    }

    /** 将图片发送给客服 */
    void sendImage(File imgFile) {
        try {
            byte[] data = Files.readAllBytes(imgFile.toPath());
            Message m = Message.image(clientId, "客服", imgFile.getName(), data);
            oos.writeObject(m);
            oos.flush();
            appendChat("我[图片]", imgFile.getName());
        } catch (IOException e) {
            showError(e);
        }
    }

    /** 将文件发送给客服 */
    void sendFile(File file) {
        try {
            byte[] data = Files.readAllBytes(file.toPath());
            Message m = Message.file(clientId, "客服", file.getName(), data);
            oos.writeObject(m);
            oos.flush();
            appendChat("我[文件]", file.getName());
        } catch (IOException e) {
            showError(e);
        }
    }

    /** 接收来自客服的消息（循环） */
    private void receiveLoop() {
        try {
            while (running) {
                Message msg = (Message) ois.readObject();
                switch (msg.type) {
                    case TEXT:
                        appendChat("客服", msg.text);
                        break;
                    case IMAGE:
                        File img = new File("recv_" + msg.fileName);
                        try (FileOutputStream fos = new FileOutputStream(img)) {
                            fos.write(msg.data);
                        }
                        appendChat("客服[图片]", msg.fileName);
                        chatWindow.showImage(img);
                        break;
                    case FILE:
                        File f = new File("recv_" + msg.fileName);
                        try (FileOutputStream fos = new FileOutputStream(f)) {
                            fos.write(msg.data);
                        }
                        appendChat("客服[文件]", msg.fileName);
                        chatWindow.showFile(f);
                        break;
                    default:
                }
            }
        } catch (Exception e) {
            if (running) showError(e);
            close();
        }
    }

    /** 将聊天内容写入窗口并追加到本地历史文件 */
    private void appendChat(String from, String content) {
        String line = String.format("[%s] %s: %s", new Date(), from, content);
        chatWindow.appendMessage(line);
        try (PrintWriter pw = new PrintWriter(new FileWriter(historyFile, true))) {
            pw.println(line);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** 关闭所有资源 */
    void close() {
        running = false;
        try { socket.close(); } catch (IOException ignored) {}
        if (chatWindow != null) chatWindow.dispose();
    }

    private void showError(Exception e) {
        JOptionPane.showMessageDialog(chatWindow,
                "错误：" + e.getMessage(),
                "错误",
                JOptionPane.ERROR_MESSAGE);
    }
}

/****************************************************************************************
 * 4. 共用的聊天窗口（ChatWindow） ---------------------------------------------------
 *    - 支持文字输入、图片/文件发送、显示聊天记录、展示收到的图片、文件
 ****************************************************************************************/
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import javax.swing.*;

class ChatWindow extends JFrame {
    private final JTextArea txtArea = new JTextArea();
    private final JTextField inputField = new JTextField();
    private final JButton sendBtn = new JButton("发送");
    private final JButton imgBtn = new JButton("图片");
    private final JButton fileBtn = new JButton("文件");
    private final Client client;   // 客户端或客服端的控制器
    private final ServerUI serverUI; // 为了统一，这里在客服端使用 ServerUI，对方为 null

    /** 构造函数：为客户端或客服端创建聊天窗口 */
    ChatWindow(String title, Object controller) {
        super(title);
        setSize(500, 400);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);
        // 判定是 CLIENT 还是 SERVER 端
        if (controller instanceof Client) {
            client = (Client) controller;
            serverUI = null;
        } else if (controller instanceof Server) {
            client = null;
            serverUI = new ServerUI((Server) controller);
        } else {
            client = null; serverUI = null;
        }

        initUI();
    }

    private void initUI() {
        txtArea.setEditable(false);
        txtArea.setLineWrap(true);
        JScrollPane scroll = new JScrollPane(txtArea);

        JPanel bottomPanel = new JPanel(new BorderLayout());
        bottomPanel.add(inputField, BorderLayout.CENTER);

        JPanel btnPanel = new JPanel();
        btnPanel.add(sendBtn);
        btnPanel.add(imgBtn);
        btnPanel.add(fileBtn);
        bottomPanel.add(btnPanel, BorderLayout.EAST);

        add(scroll, BorderLayout.CENTER);
        add(bottomPanel, BorderLayout.SOUTH);

        // 发送文字
        sendBtn.addActionListener(e -> sendText());
        inputField.addActionListener(e -> sendText());

        // 发送图片
        imgBtn.addActionListener(e -> chooseAndSendImage());

        // 发送文件
        fileBtn.addActionListener(e -> chooseAndSendFile());
    }

    /** 向对应的 controller 发送文字 */
    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        if (client != null) client.sendText(txt);
        else if (serverUI != null) {/* 客服端发送文字通过 Server 对应的 handler 调用 */}
        inputField.setText("");
    }

    /** 选择图片文件并发送 */
    private void chooseAndSendImage() {
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("图片文件", "png","jpg","jpeg","gif"));
        int ret = fc.showOpenDialog(this);
        if (ret == JFileChooser.APPROVE_OPTION) {
            File f = fc.getSelectedFile();
            if (client != null) client.sendImage(f);
            // else: 客服端调用对应的 handler.sendImage(f)
        }
    }

    /** 选择任意文件并发送 */
    private void chooseAndSendFile() {
        JFileChooser fc = new JFileChooser();
        int ret = fc.showOpenDialog(this);
        if (ret == JFileChooser.APPROVE_OPTION) {
            File f = fc.getSelectedFile();
            if (client != null) client.sendFile(f);
            // else: 客服端调用对应的 handler.sendFile(f)
        }
    }

    /** 在聊天框追加系统/历史信息（不写入文件） */
    void appendSystemMessage(String line) {
        txtArea.append(line + "\n");
    }

    /** 在聊天框追加聊天记录（并写入历史文件） */
    void appendMessage(String line) {
        txtArea.append(line + "\n");
        txtArea.setCaretPosition(txtArea.getDocument().getLength());
    }

    /** 显示收到的图片（弹出另一个窗口） */
    void showImage(File imgFile) {
        try {
            BufferedImage img = ImageIO.read(imgFile);
            if (img == null) { throw new IOException("不是图片文件"); }
            ImageIcon icon = new ImageIcon(img.getScaledInstance(200, -1, Image.SCALE_SMOOTH));
            JLabel lbl = new JLabel(icon);
            JOptionPane.showMessageDialog(this, lbl, "收到图片 - " + imgFile.getName(),
                    JOptionPane.PLAIN_MESSAGE);
        } catch (IOException e) {
            JOptionPane.showMessageDialog(this,
                    "打开图片失败：" + e.getMessage(),
                    "错误",
                    JOptionPane.ERROR_MESSAGE);
        }
    }

    /** 显示收到的文件（提供保存） */
    void showFile(File file) {
        int opt = JOptionPane.showConfirmDialog(this,
                "收到文件 " + file.getName() + "，是否保存到本地？",
                "文件接收",
                JOptionPane.YES_NO_OPTION);
        if (opt == JOptionPane.YES_OPTION) {
            JFileChooser fc = new JFileChooser();
            fc.setSelectedFile(new File(file.getName()));
            int ret = fc.showSaveDialog(this);
            if (ret == JFileChooser.APPROVE_OPTION) {
                File target = fc.getSelectedFile();
                try (InputStream in = new FileInputStream(file);
                     OutputStream out = new FileOutputStream(target)) {
                    byte[] buf = new byte[8192];
                    int len;
                    while ((len = in.read(buf)) > 0) out.write(buf, 0, len);
                    JOptionPane.showMessageDialog(this,
                            "文件已保存至 " + target.getAbsolutePath(),
                            "保存成功",
                            JOptionPane.INFORMATION_MESSAGE);
                } catch (IOException ex) {
                    JOptionPane.showMessageDialog(this,
                            "保存失败：" + ex.getMessage(),
                            "错误",
                            JOptionPane.ERROR_MESSAGE);
                }
            }
        }
    }
}

/****************************************************************************************
 * 5. 运行说明 -------------------------------------------------------------------------
 *    1) 先启动 **Server**（客服端），它会打开一个窗口展示当前在线用户。  
 *    2) 再启动 **Client**（用户端），弹出聊天窗口并尝试与客服建立连接。  
 *    3) 当有新用户请求时，客服端会弹出确认对话框，接受后即可在自己的窗口中
 *       与该用户交谈。  
 *    4) 所有文字、图片、文件均通过 **Message** 对象在 Socket 上进行
 *       序列化传输；每条聊天记录都会写入 `history_<id>.log` 文件，下次登录
 *       时自动读取显示。  
 *    5) 若客服在 10 秒内未响应，客户端会弹出 “客服忙” 提示并退出。  
 *    6) 程序已加入基本的异常捕获与线程安全处理，实际项目中请根据业务需求
 *       进行更细致的错误日志、资源回收、并发控制等。 
 *
 *    项目结构（仅示例）:
 *        src/
 *            Message.java
 *            Server.java
 *            Client.java
 *            ChatWindow.java
 *
 *    编译运行（以 JDK 8+ 为例）:
 *        javac *.java
 *        java Server          // 启动客服端
 *        java Client          // 启动用户端（可多次启动模拟多用户）
 *
 ****************************************************************************************/

Below is a **complete, self‑contained example** that shows how to:

1. **Capture a Canvas as a Blob** on the front‑end (HTML + JavaScript).  
2. **POST the Blob** to a Spring Boot back‑end using `FormData`.  
3. **Receive the Blob** in Java as a `MultipartFile`, decode it with `ImageIO`, optionally store it, and return a **Base64‑encoded PNG** that can be displayed immediately on the page.

> **All files are shown inside a single code block** – just copy them into a new Spring Boot project (e.g. `spring init --dependencies=web,devtools`) and they will work out‑of‑the‑box.

```java
/*****************************************************************************************
 * 1️⃣ Spring Boot Application entry point
 *    src/main/java/com/example/demo/DemoApplication.java
 *****************************************************************************************/
package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {
    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}

/*****************************************************************************************
 * 2️⃣ Controller that receives the canvas Blob, converts it to an image and returns it
 *    src/main/java/com/example/demo/controller/ImageController.java
 *****************************************************************************************/
package com.example.demo.controller;

import org.springframework.http.MediaType;
import org.springframework.util.Base64Utils;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.*;

@RestController
@RequestMapping("/api")
public class ImageController {

    /**
     * POST /api/uploadCanvas
     *   - receives a multipart/form-data request containing a single file (the canvas blob)
     *   - converts the blob to a BufferedImage via ImageIO
     *   - (optional) saves the image to disk
     *   - returns a JSON payload containing a Base64 PNG for immediate preview
     */
    @PostMapping(value = "/uploadCanvas",
                 consumes = MediaType.MULTIPART_FORM_DATA_VALUE,
                 produces = MediaType.APPLICATION_JSON_VALUE)
    public ImageResponse handleCanvas(@RequestParam("file") MultipartFile file) throws IOException {

        // 1️⃣ Convert the received Blob (byte[] inside MultipartFile) into a BufferedImage
        BufferedImage img;
        try (InputStream is = file.getInputStream()) {
            img = ImageIO.read(is);
            if (img == null) {
                throw new IllegalArgumentException("Unsupported image format or corrupted data.");
            }
        }

        // 2️⃣ (Optional) Persist the image on the server
        //    Here we store it under "uploads/<timestamp>.png"
        String uploadsDir = "uploads";
        File dir = new File(uploadsDir);
        if (!dir.exists()) dir.mkdirs();

        String fileName = System.currentTimeMillis() + ".png";
        File outFile = new File(dir, fileName);
        ImageIO.write(img, "png", outFile);

        // 3️⃣ Encode the image back to Base64 so the front‑end can display it instantly
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ImageIO.write(img, "png", baos);
        String base64 = Base64Utils.encodeToString(baos.toByteArray());

        // 4️⃣ Return a tiny DTO
        return new ImageResponse("data:image/png;base64," + base64, "/"+uploadsDir+"/"+fileName);
    }

    /** Simple DTO that the front‑end will receive */
    public static class ImageResponse {
        private String base64;   // data‑uri ready for <img src="...">
        private String url;      // optional URL to the saved file (if you want to serve it)

        public ImageResponse() {}

        public ImageResponse(String base64, String url) {
            this.base64 = base64;
            this.url = url;
        }

        public String getBase64() { return base64; }
        public void setBase64(String base64) { this.base64 = base64; }

        public String getUrl() { return url; }
        public void setUrl(String url) { this.url = url; }
    }
}

/*****************************************************************************************
 * 3️⃣ Static resources (HTML + JS) – served automatically from src/main/resources/static
 *    src/main/resources/static/index.html
 *****************************************************************************************/
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>Canvas → Blob → Spring Boot</title>
    <style>
        #canvas { border:1px solid #777; }
        #preview { margin-top:10px; max-width:400px; }
    </style>
</head>
<body>
<h2>在 Canvas 里绘图，然后上传到后端</h2>

<canvas id="canvas" width="400" height="200"></canvas><br>
<button id="clearBtn">清空</button>
<button id="uploadBtn">上传并预览</button>

<h3>后端返回的图片预览：</h3>
<img id="preview" src="" alt="preview will appear here"/>

<script src="app.js"></script>
</body>
</html>

/*****************************************************************************************
 * 4️⃣ Front‑end JavaScript that handles drawing, Blob creation and AJAX upload
 *    src/main/resources/static/app.js
 *****************************************************************************************/
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
let drawing = false;

// Simple free‑hand drawing
canvas.addEventListener('mousedown', e => {
    drawing = true;
    ctx.beginPath();
    ctx.moveTo(e.offsetX, e.offsetY);
});
canvas.addEventListener('mousemove', e => {
    if (!drawing) return;
    ctx.lineTo(e.offsetX, e.offsetY);
    ctx.stroke();
});
canvas.addEventListener('mouseup', () => drawing = false);
canvas.addEventListener('mouseleave', () => drawing = false);

document.getElementById('clearBtn').addEventListener('click', () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
});

document.getElementById('uploadBtn').addEventListener('click', () => {
    // 1️⃣ Convert the canvas to a Blob (PNG)
    canvas.toBlob(blob => {
        // 2️⃣ Build a FormData containing the blob
        const fd = new FormData();
        // "file" must match the @RequestParam name in the controller
        fd.append('file', blob, 'canvas.png');

        // 3️⃣ Send via Fetch API
        fetch('/api/uploadCanvas', {
            method: 'POST',
            body: fd
        })
        .then(r => {
            if (!r.ok) throw new Error('Server responded with ' + r.status);
            return r.json();
        })
        .then(data => {
            // 4️⃣ Show the returned Base64 data‑uri
            document.getElementById('preview').src = data.base64;
        })
        .catch(err => {
            console.error('Upload failed', err);
            alert('上传失败：' + err.message);
        });
    }, 'image/png');
});

/*****************************************************************************************
 * 5️⃣ (Optional) Serve the saved files statically
 *    Add the following bean to any @Configuration class (or DemoApplication)
 *****************************************************************************************/
package com.example.demo.config;

import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.*;

@Configuration
public class StaticResourceConfig implements WebMvcConfigurer {
    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        // Map "/uploads/**" to the actual folder on disk
        registry.addResourceHandler("/uploads/**")
                .addResourceLocations("file:uploads/");
    }
}

/*****************************************************************************************
 * 🎉 How to run
 * ---------------------------------------------------------------------------------------
 * 1️⃣ Build & start the app (Maven/Gradle).  
 *    e.g. `./mvnw spring-boot:run`
 *
 * 2️⃣ Open http://localhost:8080 in a browser, draw on the canvas, click "上传并预览".
 *
 * 3️⃣ The image you just drew will be sent as a Blob, the back‑end converts it,
 *    stores it under `uploads/`, returns a Base64 data‑uri, and the <img> tag
 *    displays it instantly.
 *
 * 4️⃣ You can also open the returned `url` (e.g. `/uploads/1698423412345.png`) to
 *    view the persisted file directly.
 *
 * This solution uses only standard Java (ImageIO) and Spring Boot – no third‑party
 * image libraries required.
 *****************************************************************************************/

