**How to test**  

1. Compile the plugin with Maven (`mvn clean package`).  
2. Drop the resulting JAR (the shaded “fat‑jar”) into your server’s `plugins/` folder.  
3. Restart the server.  
4. As a player, run `/camera add lobbycam`. A player‑head appears where you stand.  
5. Open a browser and navigate to `http://your-server-ip:8080/camera/lobbycam.png`.  
   You should see a small overhead map that updates every tick.  

Feel free to extend the renderer (e.g., draw entities, use a higher‑resolution image, or integrate a WebSocket stream for smoother video). The core architecture – **Jetty + Concurrent camera map + Bukkit scheduler** – stays the same. Enjoy building your in‑game surveillance system!

```javascript
/**
 * --------------------------------------------------------------
 *  KOMPLETNY PRZEWODNIK REJESTRACJI UŻYTKOWNIKA Z POTWIERDZANIEM EMAIL
 *  (Node.js + Express + PostgreSQL + Nodemailer + JWT + Prosty front‑end)
 * --------------------------------------------------------------
 *
 * 1. Użytkownik klika "Zarejestruj" w menu → wyświetla formularz.
 * 2. Po zatwierdzeniu formularza front‑end wyśle POST /api/register z danymi.
 * 3. Back‑end:
 *    - waliduje dane,
 *    - hashuje hasło (bcrypt),
 *    - generuje jednorazowy token weryfikacyjny,
 *    - zapisuje rekord w tabeli `users` (kolumna `is_verified = false`),
 *    - wysyła e‑mail z linkiem: https://myapp.com/api/verify?token=<token>.
 * 4. Użytkownik klikają link w mailu:
 *    - przeglądarka wywołuje GET /api/verify?token=…
 *    - back‑end znajduje użytkownika po tokenie,
 *    - sprawdza ważność (data wygaśnięcia),
 *    - ustawia `is_verified = true`, czyści token,
 *    - odsyła (302) do front‑endu np. https://myapp.com/login?verified=1
 * 5. Po zalogowaniu JWT jest tworzony tylko wtedy, gdy `is_verified = true`.
 * 6. Front‑end po zalogowaniu zapisuje token w localStorage i odblokowuje
 *    elementy dostępne wyłącznie dla zweryfikowanych użytkowników.
 *
 * --------------------------------------------------------------
 *  PUNKT KLUCZOWY – GDZIE ZAPISYWANY STATUS "ZWERYFIKOWANY"
 * --------------------------------------------------------------
 *   * W kolumnie `users.is_verified` (BOOLEAN) – domyślnie FALSE.
 *   * Aktualizacja odbywa się w jedynym miejscu: w endpointzie `/api/verify`.
 *   * Po pomyślnej weryfikacji zapisujemy:
 *
 *        UPDATE users
 *        SET is_verified = TRUE,
 *            verification_token = NULL,
 *            token_expires_at = NULL
 *        WHERE id = $1;
 *
 *   * Dzięki temu wszystkie dalsze operacje (logowanie, dostęp do chronionych
 *     zasobów) mogą po prostu sprawdzić flagę `is_verified`.
 *
 * --------------------------------------------------------------
 *  KOLEJNE KROKI – BLOKOWANIE / ODBLOKOWANIE ELEMENTÓW NA STRONIE
 * --------------------------------------------------------------
 *   * Po załadowaniu każdej podstrony front‑end wywołuje /api/me,
 *     które zwraca informacje o aktualnym użytkowniku (lub 401).
 *   * Na podstawie odpowiedzi:
 *        - jeśli brak autoryzacji → ukryj elementy wymagające logowania,
 *        - jeśli zalogowany, ale `is_verified = false` → pokaż komunikat
 *          „Musisz potwierdzić e‑mail”, ukryj sekcje wymagające pełnego konta.
 *        - jeśli `is_verified = true` → odblokuj wszystkie funkcje.
 *
 * --------------------------------------------------------------
 *  IMPLEMENTACJA (wszystko w jednym bloku kodu)
 * --------------------------------------------------------------
 */

/* ==============================
   === 1. Konfiguracja serwera ===
   ============================== */
const express       = require('express');
const bodyParser    = require('body-parser');
const bcrypt        = require('bcrypt');
const crypto        = require('crypto');
const jwt           = require('jsonwebtoken');
const nodemailer    = require('nodemailer');
const { Pool }      = require('pg');           // PostgreSQL
require('dotenv').config();                  // .env z kluczami

const app = express();
app.use(bodyParser.json());
app.use(express.static('public'));           // folder z plikami front‑endu

/* ---------- Połączenie z bazą ---------- */
const db = new Pool({
    connectionString: process.env.DATABASE_URL,
});

/* ---------- Transporter e‑mail ---------- */
const mailer = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT),
    secure: false,               // true dla 465
    auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS,
    },
});

/* ---------- Stałe ---------- */
const JWT_SECRET = process.env.JWT_SECRET || 'supersecretjwt';
const EMAIL_FROM = process.env.EMAIL_FROM || 'noreply@myapp.com';
const CLIENT_URL = process.env.CLIENT_URL || 'http://localhost:3000'; // np. http://localhost:3000

/* ==============================
   === 2. Schemat tabeli users ===
   ============================== */
// (do uruchomienia w migracji DB)
// CREATE TABLE users (
//   id              SERIAL PRIMARY KEY,
//   email           VARCHAR(255) UNIQUE NOT NULL,
//   password_hash   VARCHAR(255) NOT NULL,
//   is_verified     BOOLEAN DEFAULT FALSE,
//   verification_token VARCHAR(255),
//   token_expires_at TIMESTAMP,
//   created_at      TIMESTAMP DEFAULT NOW()
// );



/* ==============================
   === 3. Endpoint rejestracji ===
   ============================== */
app.post('/api/register', async (req, res) => {
    const { email, password } = req.body;

    // ---- prosta walidacja ----
    if (!email || !password) {
        return res.status(400).json({ message: 'Email i hasło są wymagane' });
    }

    try {
        // ---- sprawdź, czy email już istnieje ----
        const exist = await db.query('SELECT id FROM users WHERE email = $1', [email]);
        if (exist.rowCount > 0) {
            return res.status(409).json({ message: 'Użytkownik już istnieje' });
        }

        // ---- hash hasła ----
        const saltRounds = 12;
        const password_hash = await bcrypt.hash(password, saltRounds);

        // ---- token weryfikacyjny ----
        const verification_token = crypto.randomBytes(32).toString('hex');
        const token_expires_at = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24h

        // ---- zapisz w bazie ----
        await db.query(
            `INSERT INTO users
               (email, password_hash, verification_token, token_expires_at)
             VALUES ($1,$2,$3,$4)`,
            [email, password_hash, verification_token, token_expires_at]
        );

        // ---- wyślij e‑mail ----
        const verifyLink = `${process.env.SERVER_URL || 'http://localhost:4000'}/api/verify?token=${verification_token}`;
        const mailOptions = {
            from: EMAIL_FROM,
            to: email,
            subject: 'Potwierdź swój adres e‑mail',
            html: `
                <p>Dziękujemy za rejestrację w MyApp.</p>
                <p>Aby aktywować konto, kliknij w poniższy link:</p>
                <a href="${verifyLink}">Potwierdź mój e‑mail</a>
                <p>Link jest ważny 24 godziny.</p>
            `,
        };
        await mailer.sendMail(mailOptions);

        res.status(201).json({ message: 'Użytkownik zarejestrowany – sprawdź swoją skrzynkę e‑mail.' });
    } catch (err) {
        console.error('Błąd rejestracji:', err);
        res.status(500).json({ message: 'Wewnętrzny błąd serwera' });
    }
});

/* ==============================
   === 4. Endpoint weryfikacji ===
   ============================== */
app.get('/api/verify', async (req, res) => {
    const { token } = req.query;
    if (!token) return res.status(400).send('Brak tokenu');

    try {
        const result = await db.query(
            `SELECT id, token_expires_at, is_verified
               FROM users
              WHERE verification_token = $1`,
            [token]
        );

        if (result.rowCount === 0) {
            return res.status(404).send('Niepoprawny lub już użyty token');
        }

        const user = result.rows[0];

        // ---- sprawdź, czy już zweryfikowany ----
        if (user.is_verified) {
            return res.redirect(`${CLIENT_URL}/login?alreadyVerified=1`);
        }

        // ---- sprawdź datę wygaśnięcia tokenu ----
        if (new Date() > user.token_expires_at) {
            return res.redirect(`${CLIENT_URL}/login?tokenExpired=1`);
        }

        // ---- ZAPISZ STATUS ZWERYFIKOWANY ----
        await db.query(
            `UPDATE users
                SET is_verified = TRUE,
                    verification_token = NULL,
                    token_expires_at = NULL
              WHERE id = $1`,
            [user.id]
        );

        // ---- Przekierowanie z informacją o sukcesie ----
        res.redirect(`${CLIENT_URL}/login?verified=1`);
    } catch (err) {
        console.error('Błąd weryfikacji:', err);
        res.status(500).send('Wewnętrzny błąd serwera');
    }
});

/* ==============================
   === 5. Endpoint logowania ===
   ============================== */
app.post('/api/login', async (req, res) => {
    const { email, password } = req.body;
    if (!email || !password) return res.status(400).json({ message: 'Email i hasło wymagane' });

    try {
        const result = await db.query(
            `SELECT id, password_hash, is_verified FROM users WHERE email = $1`,
            [email]
        );

        if (result.rowCount === 0) {
            return res.status(401).json({ message: 'Nieprawidłowe dane logowania' });
        }

        const user = result.rows[0];

        // ---- Czy użytkownik zweryfikował e‑mail? ----
        if (!user.is_verified) {
            return res.status(403).json({ message: 'Konto nie jest zweryfikowane – sprawdź e‑mail' });
        }

        const match = await bcrypt.compare(password, user.password_hash);
        if (!match) {
            return res.status(401).json({ message: 'Nieprawidłowe dane logowania' });
        }

        // ---- Generowanie JWT ----
        const token = jwt.sign(
            { sub: user.id, email },
            JWT_SECRET,
            { expiresIn: '7d' }
        );

        res.json({ token });
    } catch (err) {
        console.error('Błąd logowania:', err);
        res.status(500).json({ message: 'Wewnętrzny błąd serwera' });
    }
});

/* ==============================
   === 6. Middleware autoryzacji ===
   ============================== */
function authenticate(req, res, next) {
    const authHeader = req.headers.authorization;
    if (!authHeader) return res.status(401).json({ message: 'Brak tokenu' });

    const token = authHeader.split(' ')[1];
    try {
        const payload = jwt.verify(token, JWT_SECRET);
        req.user = payload; // { sub, email, iat, exp }
        next();
    } catch (e) {
        return res.status(401).json({ message: 'Nieprawidłowy token' });
    }
}

/* ==============================
   === 7. Endpoint pobierania aktualnego usera ===
   ============================== */
app.get('/api/me', authenticate, async (req, res) => {
    try {
        const result = await db.query(
            `SELECT id, email, is_verified FROM users WHERE id = $1`,
            [req.user.sub]
        );
        if (result.rowCount === 0) return res.status(404).json({ message: 'Użytkownik nie istnieje' });

        const user = result.rows[0];
        res.json({ id: user.id, email: user.email, is_verified: user.is_verified });
    } catch (err) {
        console.error('Błąd /me:', err);
        res.status(500).json({ message: 'Wewnętrzny błąd serwera' });
    }
});

/* ==============================
   === 8. Przykładowe chronione API ===
   ============================== */
app.get('/api/secret-data', authenticate, async (req, res) => {
    // dodatkowo można sprawdzić is_verified, ale logowanie już to egzekwuje
    res.json({ secret: 'To jest tajna treść dostępna tylko dla zweryfikowanych użytkowników' });
});

/* ==============================
   === 9. Uruchomienie serwera ===
   ============================== */
const PORT = process.env.PORT || 4000;
app.listen(PORT, () => console.log(`Serwer działa na porcie ${PORT}`));

/* ==============================================================
   === 10. Front‑end (plik public/index.html + public/app.js)   ===
   ============================================================== */
/*
--- public/index.html -------------------------------------------------
