<html lang="pl">
<head>
    <meta charset="UTF-8">
    <title>MyApp – Rejestracja</title>
    <style>
        .hidden { display: none; }
        .menu a { margin-right: 1rem; cursor: pointer; }
    </style>
</head>
<body>
    <nav class="menu">
        <a id="menuLogin">Logowanie</a>
        <a id="menuRegister">Zarejestruj</a>
        <a id="menuSecret" class="hidden">Tajna sekcja</a>
        <a id="menuLogout" class="hidden">Wyloguj</a>
    </nav>

    <section id="sectionLogin" class="hidden">
        <h2>Logowanie</h2>
        <form id="loginForm">
            <input type="email" placeholder="E‑mail" required id="loginEmail"><br>
            <input type="password" placeholder="Hasło" required id="loginPassword"><br>
            <button type="submit">Zaloguj</button>
        </form>
        <p id="loginMsg"></p>
    </section>

    <section id="sectionRegister" class="hidden">
        <h2>Rejestracja</h2>
        <form id="registerForm">
            <input type="email" placeholder="E‑mail" required id="regEmail"><br>
            <input type="password" placeholder="Hasło" required id="regPassword"><br>
            <button type="submit">Zarejestruj</button>
        </form>
        <p id="registerMsg"></p>
    </section>

    <section id="sectionSecret" class="hidden">
        <h2>Tajna sekcja</h2>
        <p>Jeśli widzisz to, jesteś zweryfikowanym użytkownikiem!</p>
        <button id="fetchSecret">Pobierz tajną treść</button>
        <pre id="secretResult"></pre>
    </section>

    <script src="app.js"></script>
</body>
</html>
