--- public/app.js -------------------------------------------------------
/*  Funkcje pomocnicze  */
function show(el) { el.classList.remove('hidden'); }
function hide(el) { el.classList.add('hidden'); }
function setHTML(id, txt) { document.getElementById(id).innerHTML = txt; }

/*  Elementy DOM  */
const menuLogin    = document.getElementById('menuLogin');
const menuRegister = document.getElementById('menuRegister');
const menuSecret   = document.getElementById('menuSecret');
const menuLogout   = document.getElementById('menuLogout');

const secLogin     = document.getElementById('sectionLogin');
const secRegister  = document.getElementById('sectionRegister');
const secSecret    = document.getElementById('sectionSecret');

const loginForm    = document.getElementById('loginForm');
const registerForm = document.getElementById('registerForm');

/*  Obsługa menu  */
menuLogin.addEventListener('click', () => {
    hide(secRegister); hide(secSecret);
    show(secLogin);
});
menuRegister.addEventListener('click', () => {
    hide(secLogin); hide(secSecret);
    show(secRegister);
});
menuLogout.addEventListener('click', () => {
    localStorage.removeItem('jwt');
    updateUIUnauthenticated();
});

/*  Rejestracja  */
registerForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const email = document.getElementById('regEmail').value;
    const pass  = document.getElementById('regPassword').value;

    const resp = await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password: pass })
    });
    const data = await resp.json();
    setHTML('registerMsg', data.message || 'Nieznany błąd');
});

/*  Logowanie  */
loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const email = document.getElementById('loginEmail').value;
    const pass  = document.getElementById('loginPassword').value;

    const resp = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password: pass })
    });
    const data = await resp.json();
    if (resp.ok) {
        localStorage.setItem('jwt', data.token);
        await refreshCurrentUser(); // pobierz /me i odblokuj menu
    } else {
        setHTML('loginMsg', data.message);
    }
});

/*  Pobieranie aktualnego użytkownika (czy jest zweryfikowany?) */
async function refreshCurrentUser() {
    const token = localStorage.getItem('jwt');
    if (!token) return updateUIUnauthenticated();

    const resp = await fetch('/api/me', {
        headers: { Authorization: `Bearer ${token}` }
    });
    if (!resp.ok) return updateUIUnauthenticated();

    const user = await resp.json();
    if (user.is_verified) {
        updateUIAuthenticated();
    } else {
        // użytkownik zalogowany, ale nie zweryfikował e‑mail
        alert('Konto nie zostało jeszcze zweryfikowane – sprawdź swoją skrzynkę e‑mail.');
        updateUIUnauthenticated();
    }
}

/*  UI po zalogowaniu (zweryfikowanym) */
function updateUIAuthenticated() {
    hide(menuLogin); hide(menuRegister);
    show(menuSecret); show(menuLogout);
    hide(secLogin); hide(secRegister);
    show(secSecret);
}

/*  UI po wylogowaniu / braku autoryzacji */
function updateUIUnauthenticated() {
    show(menuLogin); show(menuRegister);
    hide(menuSecret); hide(menuLogout);
    hide(secLogin); hide(secRegister); hide(secSecret);
}

/*  Pobranie tajnej treści z chronionego endpointu */
document.getElementById('fetchSecret').addEventListener('click', async () => {
    const token = localStorage.getItem('jwt');
    const resp = await fetch('/api/secret-data', {
        headers: { Authorization: `Bearer ${token}` }
    });
    const data = await resp.json();
    if (resp.ok) {
        document.getElementById('secretResult').textContent = data.secret;
    } else {
        document.getElementById('secretResult').textContent = `Błąd: ${data.message}`;
    }
});

/*  Przy ładowaniu strony sprawdzamy, czy mamy token i odświeżamy stan  */
window.addEventListener('load', () => {
    refreshCurrentUser();
});
-----------------------------------------------------------------------


**Podsumowanie najważniejszych momentów**  

1. **Zapis statusu „zweryfikowany”** – jedynie w endpointzie `/api/verify` po udanym
   sprawdzeniu tokenu i daty wygaśnięcia.  Aktualizacja: `is_verified = TRUE`.

2. **Blokowanie/odblokowanie elementów** – front‑end po każdym odświeżeniu wywołuje
   `/api/me`.  Na podstawie pola `is_verified` (oraz tego, czy token istnieje) 
   decyduje które linki w menu i które sekcje są widoczne.

3. **Bezpieczeństwo** – wszystkie chronione API (np. `/api/secret-data`) używają
   middleware `authenticate`, który weryfikuje JWT.  Ponieważ token jest
   przyznawany wyłącznie po `is_verified = true`, nie ma ryzyka, że niezweryfikowany
   użytkownik uzyska dostęp.

4. **Odświeżanie tokenu** – w prostym przykładzie token jest ważny 7 dni; w realnej
   aplikacji warto dodać odświeżanie (refresh‑token) i mechanizm wylogowania
   po wygaśnięciu.

5. **Obsługa błędów i komunikatów** – po kliknięciu w link weryfikacyjny
   użytkownik jest przekierowywany do front‑endu z parametrami GET
   (`?verified=1`, `?tokenExpired=1`…), które front‑end może wyświetlić
   jako banery informacyjne.

Teraz masz kompletny schemat działania oraz działający kod bazowy,
który możesz rozbudować o dodatkowe walidacje, UI, testy i integrację CI/CD.

下面的 **单文件代码块** 包含了完整的解决方案：

```java
/* -------------------------------------------------------------
   1️⃣ Spring Boot 端 – WebSocket 配置（控制最大消息大小）
   ------------------------------------------------------------- */
package com.example.demo.config;

import org.springframework.context.annotation.Configuration;
import org.springframework.web.socket.config.annotation.*;

@Configuration
@EnableWebSocketMessageBroker      // 如果使用 STOMP；若只用原生 WebSocket 可去掉
public class WebSocketConfig implements WebSocketMessageBrokerConfigurer {

    // ---------- ① 配置端点 ----------
    @Override
    public void registerStompEndpoints(StompEndpointRegistry registry) {
        // “/ws” 为前端连接的 URL，使用 SockJS 兼容老浏览器
        registry.addEndpoint("/ws").setAllowedOrigins("*").withSockJS();
    }

    // ---------- ② 配置消息传输参数 ----------
    @Override
    public void configureWebSocketTransport(WebSocketTransportRegistration registration) {
        // 1) 单条消息（文本或二进制）最大大小，单位：字节
        //    默认 64KB，下面示例设为 5 MB
        registration.setMessageSizeLimit(5 * 1024 * 1024);

        // 2) 发送缓冲区的总大小（累计未发完的消息），超出会被关闭
        registration.setSendBufferSizeLimit(10 * 1024 * 1024);

        // 3) 发送超时时间（毫秒），防止卡死
        registration.setSendTimeLimit(30_000);
    }

    // ---------- ③ 如需开启二进制（Binary）支持 ----------
    @Override
    public void configureMessageBroker(MessageBrokerRegistry registry) {
        // 简单内置 broker，仅演示用
        registry.enableSimpleBroker("/topic");
        registry.setApplicationDestinationPrefixes("/app");
    }
}

/* -------------------------------------------------------------
   2️⃣ application.yml – 更细粒度的全局属性（可选）
   ------------------------------------------------------------- */
# spring:
#   web:
#     socket:
#       # 对所有容器生效（Tomcat、Jetty、Undertow）
#       max-text-message-buffer-size: 5242880      # 5 MB
#       max-binary-message-buffer-size: 5242880    # 5 MB
#   # 如果你使用 Spring WebFlux：
#   #   webflux:
#   #     websockets:
#   #       max-frame-payload-size: 5242880

/* -------------------------------------------------------------
   3️⃣ 前端 JavaScript – 通过原生 WebSocket 发送图片（Binary）
   ------------------------------------------------------------- */
const ws = new WebSocket('ws://localhost:8080/ws');   // 与 Spring 中 registerStompEndpoints 对应
ws.binaryType = 'arraybuffer';                       // 接收/发送二进制

ws.onopen = () => {
    console.log('WebSocket 已连接');
    // 读取本地文件 (HTML <input type="file">)
    const fileInput = document.getElementById('fileInput');
    fileInput.addEventListener('change', async e => {
        const file = e.target.files[0];
        if (!file) return;

        // 检查文件大小是否超过服务器配置（5 MB 示例）
        const MAX_SIZE = 5 * 1024 * 1024; // 5 MB
        if (file.size > MAX_SIZE) {
            alert(`文件太大，最大只能 ${MAX_SIZE / (1024*1024)} MB`);
            return;
        }

        // 读取为 ArrayBuffer 并直接发送
        const arrayBuffer = await file.arrayBuffer();
        ws.send(arrayBuffer);
        console.log('图片已发送，大小：', file.size);
    });
};

ws.onmessage = event => {
    // 服务器返回的二进制数据会走这里
    console.log('收到服务器返回', event.data);
};

ws.onerror = err => console.error('WebSocket 错误', err);
ws.onclose = () => console.log('WebSocket 已关闭');

/* -------------------------------------------------------------
   4️⃣ 服务器端接收图片（示例 Controller，使用 @MessageMapping）
   ------------------------------------------------------------- */
package com.example.demo.controller;

import org.springframework.messaging.handler.annotation.*;
import org.springframework.stereotype.Controller;

@Controller
public class ImageController {

    // 前端使用 STOMP 时，可写成: @MessageMapping("/upload")
    @MessageMapping("/upload")
    @SendTo("/topic/ack")
    public String receiveImage(byte[] payload,
                               @Header("simpSessionId") String sessionId) {
        // payload 即为前端发送的二进制图片
        System.out.println("收到来自 session " + sessionId + " 的图片，大小 " + payload.length + " byte");

        // 这里可以把 payload 保存到磁盘、DB 或直接转发
        // ...

        return "图片已收到，大小 " + payload.length + " byte";
    }
}

/* -------------------------------------------------------------
   🎯 小结
   -------------------------------------------------------------
   1️⃣ 在 `WebSocketTransportRegistration` 中通过 `setMessageSizeLimit`
      明确限制单条消息的最大字节数（示例 5 MB）。
   2️⃣ `setSendBufferSizeLimit` 与 `setSendTimeLimit` 搭配防止
      大文件导致连接被长时间占用。
   3️⃣ 如使用 Spring Boot 2.6+，也可通过 `application.yml`
      的 `spring.web.socket.*` 属性统一设置。
   4️⃣ 前端在发送前自行检查文件大小，避免因超限而被服务器直接关闭连接。
   5️⃣ 若你用的是原生 WebSocket（不走 STOMP），
      只要在 `WebSocketConfig` 中实现 `WebSocketConfigurer` 并
      注册 `WebSocketHandler`，上述 `configureWebSocketTransport`
      同样生效。 */

```csharp
/*=================================================================================================================
   ASP.NET Core 7 Razor Pages – Minimal “Register” and “Login” (Identity) for a complete beginner
   -------------------------------------------------------------------------------
   1. Create a new Razor Pages project:
        dotnet new webapp -o RazorIdentityDemo
        cd RazorIdentityDemo

   2. Add the required NuGet packages:
        dotnet add package Microsoft.AspNetCore.Identity.EntityFrameworkCore
        dotnet add package Microsoft.EntityFrameworkCore.SqlServer   // or any other provider
        dotnet add package Microsoft.EntityFrameworkCore.Tools

   3. The solution consists of the following files (all code is shown below inside one code block).
      • Program.cs          – registers Identity services and the DbContext
      • Data/ApplicationDbContext.cs – EF Core context that hosts Identity tables
      • Pages/Account/Register.cshtml & Register.cshtml.cs – registration UI & logic
      • Pages/Account/Login.cshtml    & Login.cshtml.cs    – login UI & logic
      • Pages/Shared/_Layout.cshtml   – adds navigation links
      • Pages/Shared/_LoginPartial.cshtml – shows current user / logout link
      • appsettings.json – connection string (adjust to your DB)

   4. Run the migrations and start the app:
        dotnet ef migrations add InitialCreate
        dotnet ef database update
        dotnet run

   -------------------------------------------------------------------------------
   Below is the complete source code for each file. Copy each section into the appropriate
   location in your project. The code is heavily commented to explain every step.
=================================================================================================================*/

///////////////////////////////////////////////////////////////////////
// Program.cs
///////////////////////////////////////////////////////////////////////
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using RazorIdentityDemo.Data;

var builder = WebApplication.CreateBuilder(args);

// ------------------------------------------------------------------
// 1️⃣ Register the EF Core DbContext (use your own connection string)
// ------------------------------------------------------------------
builder.Services.AddDbContext<ApplicationDbContext>(options =>
    options.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));

// ---------------------------------------------------------------
// 2️⃣ Add ASP.NET Core Identity (with default UI disabled – we’ll use Razor pages)
// ---------------------------------------------------------------
builder.Services.AddIdentity<IdentityUser, IdentityRole>(options =>
    {
        // Password policy – you can tune these for dev convenience
        options.Password.RequireDigit = false;
        options.Password.RequiredLength = 6;
        options.Password.RequireNonAlphanumeric = false;
        options.Password.RequireUppercase = false;
        options.Password.RequireLowercase = false;

        // Sign‑in settings
        options.SignIn.RequireConfirmedAccount = false;
    })
    .AddEntityFrameworkStores<ApplicationDbContext>()
    .AddDefaultTokenProviders();

// ------------------------------------------------------------------
// 3️⃣ Add Razor Pages support
// ------------------------------------------------------------------
builder.Services.AddRazorPages();

// ------------------------------------------------------------------
// 4️⃣ Build the app
// ------------------------------------------------------------------
var app = builder.Build();

if (!app.Environment.IsDevelopment())
{
    app.UseExceptionHandler("/Error");
    app.UseHsts();
}
app.UseHttpsRedirection();
app.UseStaticFiles();

app.UseRouting();

// ------------------------------------------------------------------
// 5️⃣ Identity middlewares
// ------------------------------------------------------------------
app.UseAuthentication();
app.UseAuthorization();

app.MapRazorPages();

app.Run();

