#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_MOLI 100
#define MAX_NOME_NAVI 30
#define LUNGHEZZA_ID 6
#define MARGINE 1.10  // 10% in più richiesto

// Struttura per rappresentare un molo
typedef struct {
    char id[LUNGHEZZA_ID + 1];
    double lunghezza;
    int occupato;  // 1 se occupato, 0 se libero
} Molo;

// Struttura per rappresentare una nave assegnata
typedef struct {
    char nome[MAX_NOME_NAVI + 1];
    double lunghezza;
    char id_molo[LUNGHEZZA_ID + 1];
} Nave;

// Dichiarazioni funzioni
void leggi_file_moli(const char* nome_file, Molo moli[]);
void gestione_assegnazione_moli(Molo moli[]);
void calcolo_statistiche_e_stampa(const Molo moli[]);
int main(int argc, char* argv[]);

// Funzione per la lettura del file dei moli
void leggi_file_moli(const char* nome_file, Molo moli[]) {
    FILE* fp = fopen(nome_file, "r");
    if (fp == NULL) {
        fprintf(stderr, "Errore: impossibile aprire il file %s\n", nome_file);
        exit(1);
    }

    int index = 0;
    char id[LUNGHEZZA_ID + 1];
    double lunghezza;

    while (fscanf(fp, "%s %lf", id, &lunghezza) == 2 && index < MAX_MOLI) {
        strncpy(moli[index].id, id, LUNGHEZZA_ID);
        moli[index].id[LUNGHEZZA_ID] = '\0';
        moli[index].lunghezza = lunghezza;
        moli[index].occupato = 0;  // inizialmente libero
        index++;
    }

    fclose(fp);
}

// Funzione per gestire il menu di inserimento navi e assegnazione moli
void gestione_assegnazione_moli(Molo moli[]) {
    char nome_nave[MAX_NOME_NAVI + 1];
    double lunghezza_nave;
    char continua;
    int navi_assegnate = 0;
    Nave navi_assegnate_array[MAX_MOLI];  // per tenere traccia delle navi assegnate

    do {
        printf("Inserire nome nave: ");
        scanf("%s", nome_nave);

        printf("Inserire lunghezza nave in arrivo (in metri): ");
        scanf("%lf", &lunghezza_nave);

        // Controllo se esiste un molo disponibile con lunghezza ≥ lunghezza_nave * 1.10
        int assegnato = 0;
        for (int i = 0; i < MAX_MOLI; i++) {
            if (!moli[i].occupato && moli[i].lunghezza >= lunghezza_nave * MARGINE) {
                strcpy(navi_assegnate_array[navi_assegnate].nome, nome_nave);
                navi_assegnate_array[navi_assegnate].lunghezza = lunghezza_nave;
                strcpy(navi_assegnate_array[navi_assegnate].id_molo, moli[i].id);
                moli[i].occupato = 1;
                navi_assegnate++;
                printf("Nave assegnata al molo %s\n", moli[i].id);
                assegnato = 1;
                break;
            }
        }

        if (!assegnato) {
            int tutti_occupati = 1;
            for (int i = 0; i < MAX_MOLI; i++) {
                if (!moli[i].occupato) {
                    tutti_occupati = 0;
                    break;
                }
            }

            if (tutti_occupati) {
                printf("Molo non assegnato: tutti i moli sono occupati\n");
            } else {
                printf("Molo non assegnato: non esiste un molo disponibile di lunghezza sufficiente\n");
            }
        }

        printf("Continua (S/N)? ");
        scanf(" %c", &continua);
        continua = toupper(continua);

    } while (continua == 'S');

    // Salvataggio nel main dei dati per le statistiche (passato per reference)
    // In questo caso lo passiamo in modo implicito: la funzione calcolo_statistiche_e_stampa
    // riceve i moli e calcola automaticamente le statistiche.
}

// Funzione per calcolare le statistiche e stampare a schermo
void calcolo_statistiche_e_stampa(const Molo moli[]) {
    int moli_liberi = 0;
    double lunghezza_massima = -1;
    char nome_nave_massima[MAX_NOME_NAVI + 1];
    char id_molo_massimo[LUNGHEZZA_ID + 1];

    // Conta i moli liberi
    for (int i = 0; i < MAX_MOLI; i++) {
        if (!moli[i].occupato) moli_liberi++;
    }

    // Cerca la nave più lunga tra quelle assegnate (ma non ne abbiamo una lista separata)
    // Dobbiamo tenere traccia delle navi assegnate all'interno di gestione_assegnazione_moli
    // Ma qui non abbiamo accesso all'array navi_assegnate...
    // Soluzione: modificare gestione_assegnazione_moli per passare anche il numero di navi
    // E l’array. Per questo motivo, dobbiamo ritornare alla struttura con le navi assegnate.

    // Correzione: usiamo una soluzione con passaggio di puntatore a array esterno.
    // Ma poiché non possiamo modificare le funzioni per fare questo, dobbiamo ripensare.
    // Ovvero: l'assegnazione richiede che si memorizzi l'informazione per il calcolo finale.

    // Dato che l'esercizio richiede di stampare la nave più lunga tra quelle assegnate,
    // dobbiamo memorizzare le navi assegnate nel gestore. Implementiamo una versione modificata.

    // NOTA: Per rispettare la consegna, dobbiamo usare una struttura globale o una variabile locale.
    // Poiché il problema non permette modifiche globali, dobbiamo gestire l'interfaccia.

    // In assenza di array con le navi assegnate, non possiamo calcolare il massimo.
    // Quindi: ricodifichiamo il gestione_assegnazione_moli per restituire le info.

    // Ma l'esercizio chiede una funzione senza ritorno. Quindi dobbiamo rivedere.

