// │   ├── errorHandler.js
// │   └── auditLog.js
// ├── .env
// ├── server.js
// └── package.json

// ==============================================
// STEP 1: Firebase Setup (Secure Authentication)
// ==============================================

// config/firebaseConfig.js
const admin = require('firebase-admin');
const serviceAccount = require('./path/to/serviceAccountKey.json'); // Never commit this!

if (!admin.apps.length) {
  admin.initializeApp({
    credential: admin.credential.cert(serviceAccount),
    databaseURL: 'https://your-project-id.firebaseio.com'
  });
}

const auth = admin.auth();
const db = admin.firestore();

// Enable audit logging for all operations
db.settings({ timestampsInSnapshots: true });

module.exports = { auth, db };

// ==============================================
// STEP 2: Auth Middleware (JWT + Firebase Auth Verification)
// ==============================================

// middleware/auth.js
const { auth } = require('../config/firebaseConfig');
const { BadRequestError, UnauthorizedError } = require('../utils/errorHandler');

const authenticate = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return next(new UnauthorizedError('Authentication token required'));
    }

    const idToken = authHeader.split('Bearer ')[1];

    // Verify Firebase ID token
    const decodedToken = await auth.verifyIdToken(idToken);
    const { uid, email, email_verified } = decodedToken;

    // Validate email verification (security-critical)
    if (!email_verified) {
      return next(new UnauthorizedError('Email must be verified'));
    }

    // Attach user info to request
    req.user = {
      uid,
      email,
      role: decodedToken.role || 'user', // Set roles via Firebase Admin SDK
      timestamp: Date.now()
    };

    next();
  } catch (error) {
    console.error('Auth error:', error);
    return next(new UnauthorizedError('Invalid or expired token'));
  }
};

// RBAC Middleware (Role-Based Access Control)
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    const { role } = req.user;

    if (!allowedRoles.includes(role)) {
      return next(new UnauthorizedError('Insufficient permissions'));
    }

    next();
  };
};

module.exports = { authenticate, authorize };

// ==============================================
// STEP 3: Input Validation & Sanitization
// ==============================================

// middleware/validate.js
const { body, validationResult } = require('express-validator');

const validateBusiness = [
  body('name')
    .trim()
    .isLength({ min: 2, max: 100 })
    .matches(/^[a-zA-Z0-9\s\-\_]+$/)
    .withMessage('Business name must be 2-100 chars, alphanumeric, spaces, hyphens, underscores only'),

  body('category')
    .trim()
    .isIn([
      'restaurant', 'cafe', 'hotel', 'store', 'service', 'entertainment', 'healthcare'
    ])
    .withMessage('Invalid category'),

  body('location')
    .isObject()
    .withMessage('Location must be an object')
    .bail()
    .custom((location) => {
      if (!location.latitude || !location.longitude) {
        throw new Error('Latitude and longitude are required');
      }
      if (location.latitude < -90 || location.latitude > 90) {
        throw new Error('Invalid latitude');
      }
      if (location.longitude < -180 || location.longitude > 180) {
        throw new Error('Invalid longitude');
      }
      return true;
    }),

  body('contact')
    .optional()
    .isEmail()
    .normalizeEmail()
    .withMessage('Contact must be a valid email'),

  body('description')
    .optional()
    .isLength({ max: 500 })
    .withMessage('Description must be less than 500 characters'),

  body('hours')
    .optional()
    .isISO8601()
    .withMessage('Opening hours must be in ISO8601 format')
];

const validateReview = [
  body('rating')
    .isInt({ min: 1, max: 5 })
    .withMessage('Rating must be 1-5'),

  body('comment')
    .optional()
    .isLength({ max: 1000 })
    .matches(/^[a-zA-Z0-9\s\-\.\,\!\?\@#$%&\*\(\)\[\]\{\}\+\=\_\~\:\;\'\"\/\|\\]*$/)
    .withMessage('Comment contains invalid characters')
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

module.exports = { validateBusiness, validateReview, handleValidationErrors };

// ==============================================
// STEP 4: Firestore Database Schema Design (With Security Rules)
// ==============================================

// models/Business.js
class Business {
  constructor(data) {
    this.id = data.id || null;
    this.name = data.name || '';
    this.category = data.category || '';
    this.location = data.location || {};
    this.contact = data.contact || '';
    this.description = data.description || '';
    this.imageUrls = data.imageUrls || [];
    this.hours = data.hours || {};
    this.rating = data.rating || 0;
    this.reviewCount = data.reviewCount || 0;
    this.isActive = data.isActive !== false; // Default: true
    this.ownerId = data.ownerId || null;
    this.createdAt = data.createdAt || Date.now();
    this.updatedAt = data.updatedAt || Date.now();
  }

  // Static method to get business from Firebase
  static async get(id) {
    const doc = await db.collection('businesses').doc(id).get();
    if (!doc.exists) return null;
    return new Business({ id: doc.id, ...doc.data() });
  }

  // Save business (create/update)
  async save() {
    const data = {
      name: this.name,
      category: this.category,
      location: this.location,
      contact: this.contact,
      description: this.description,
      imageUrls: this.imageUrls,
      hours: this.hours,
      rating: this.rating,
      reviewCount: this.reviewCount,
      isActive: this.isActive,
      ownerId: this.ownerId,
      createdAt: this.createdAt,
      updatedAt: Date.now()
    };

    if (this.id) {
      await db.collection('businesses').doc(this.id).update(data);
    } else {
      this.id = db.collection('businesses').doc().id;
      data.id = this.id;
      await db.collection('businesses').doc(this.id).set(data);
    }

    return this;
  }

  // Soft delete
  async delete() {
    await db.collection('businesses').doc(this.id).update({
      isActive: false,
      deletedAt: Date.now()
    });
  }
}

module.exports = Business;

