  handleValidationErrors,
  async (req, res) => {
    try {
      const { name, category, location, contact, description, hours } = req.body;

      // Validate owner is not already running another business
      const existingCount = await db.collection('businesses')
        .where('ownerId', '==', req.user.uid)
        .where('isActive', '==', true)
        .count()
        .get();

      if (existingCount.data().count > 0) {
        return res.status(400).json({
          success: false,
          message: 'Owner can only have one active business at a time'
        });
      }

      const business = new Business({
        name,
        category,
        location,
        contact,
        description,
        hours,
        ownerId: req.user.uid
      });

      await business.save();

      auditLog(req.user.uid, 'CREATE', 'business', business.id, {
        name: business.name,
        category: business.category
      });

      res.status(201).json({
        success: true,
        business: {
          id: business.id,
          name: business.name,
          category: business.category,
          location: business.location,
          contact: business.contact,
          createdAt: business.createdAt
        }
      });

    } catch (error) {
      console.error('Create business error:', error);
      res.status(500).json({
        success: false,
        message: 'Server error'
      });
