      let limit = parseInt(req.query.limit) || 20;

      // For pagination, we need to use startAfter and limit
      if (page > 1) {
        const snap = await db.collection('businesses')
          .where('isActive', '==', true)
          .orderBy('createdAt', 'desc')
          .limit((page - 1) * limit)
          .get();

        if (snap.empty) {
          return res.json({
            success: true,
            businesses: [],
            pagination: {
              page,
              limit,
              total: 0,
              pages: 0,
              hasNext: false,
              hasPrev: false
            }
          });
        }

        const lastDoc = snap.docs[snap.docs.length - 1];
        query = query.startAfter(lastDoc);
      }

      const snapshot = await query.limit(limit).get();
      const businesses = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      const total = await db.collection('businesses')
        .where('isActive', '==', true)
        .count()
        .get();

      auditLog(req.user.uid, 'READ', 'businesses', null, { count: businesses.length });

      res.json({
        success: true,
        businesses,
        pagination: {
          page,
          limit,
          total: total.data().count,
          pages: Math.ceil(total.data().count / limit),
          hasNext: businesses.length === limit,
          hasPrev: page > 1
        }
      });

    } catch (error) {
      console.error('Get all businesses error:', error);
      res.status(500).json({
        success: false,
        message: 'Server error'
      });
    }
  }
];

module.exports = {
  createBusiness,
  getBusiness,
  updateBusiness,
  deleteBusiness,
  getAllBusinesses
};

